const e=(a,n=320)=>`https://upload.wikimedia.org/wikipedia/commons/thumb/${a}/${n}px-${a.split("/").pop()}`,o=[{id:"snow-white",coverImage:e("f/f8/Snow-white-1882.jpg"),title:"Blanche-Neige",summary:"Une douce princesse a la peau blanche comme la neige trouve un foyer aupres de sept petits aides bienveillants et apprend que les vrais amis veillent les uns sur les autres.",theme:"gentillesse et amitie",emoji:"🍎",palette:{primary:"#C0392B",accent:"#F8C8DC",background:"#FFF5F6"},difficulty:"doux",ageMin:4,ageMax:8,scenes:[{text:"Il y a longtemps, une petite princesse naquit avec la peau blanche comme la neige. Tout le monde l'appelait Blanche-Neige."},{text:"Une reine jalouse possedait un miroir magique et lui posait la meme question chaque jour.",dialogue:{speaker:"Reine",line:"Miroir, miroir, qui est la plus gentille et la plus belle de toutes ?"}},{text:"Blanche-Neige marcha au coeur de la foret. Sept petits mineurs bienveillants l'accueillirent dans leur chaumiere douillette.",dialogue:{speaker:"Un mineur",line:"Tu es en securite ici, petite amie. Viens te reposer."}},{text:"La reine la trompa avec une pomme brillante, et Blanche-Neige tomba dans un sommeil tres, tres profond."},{text:"Une amie attentionnee la reveilla d'un geste tout doux. Blanche-Neige sourit, et tous feterent leur courageuse amie.",dialogue:{speaker:"Blanche-Neige",line:"Vous ne m'avez jamais quittee. Merci, mes amis !"}}],vocabulary:[{word:"la plus belle",meaning:"la plus gentille et la plus jolie",emoji:"🌷"},{word:"jalouse",meaning:"fachee parce qu'on veut ce qu'un autre a",emoji:"😠"},{word:"chaumiere",meaning:"une petite maison toute douillette",emoji:"🏡"},{word:"accueillir",meaning:"rendre quelqu'un heureux d'etre arrive",emoji:"🤗"}],miniGame:{type:"count",prompt:"Combien de gentils petits mineurs ont accueilli Blanche-Neige ?",answer:7,options:[6,7,8]},emotionalMoment:{feeling:"entoure et protege",prompt:"Les amis de Blanche-Neige veillaient sur elle. Qui veille sur toi ?"},rewardEmoji:"🪞",rewardName:"Miroir bienveillant"},{id:"cinderella",coverImage:e("6/60/Cinderella_canziani.jpg"),title:"Cendrillon",summary:"Une fille travailleuse et au grand coeur recoit un peu d'aide d'une amie magique et decouvre qu'etre gentille est une magie en soi.",theme:"espoir et gentillesse",emoji:"👠",palette:{primary:"#6C5CE7",accent:"#A29BFE",background:"#F4F2FF"},difficulty:"aventure",ageMin:5,ageMax:8,scenes:[{text:"Cendrillon faisait toutes les taches et ne perdait jamais son doux sourire, meme quand les autres etaient mechants."},{text:"Un soir, un grand bal fut annonce, mais Cendrillon n'avait rien a se mettre.",dialogue:{speaker:"Cendrillon",line:"Si seulement je pouvais aller danser, juste une fois."}},{text:"Une gentille fee apparut et, d'un coup de baguette, changea une citrouille en carrosse.",dialogue:{speaker:"Fee amie",line:"Rentre avant minuit, ma cherie — la magie s'arrete alors."}},{text:"Au bal, Cendrillon dansa et rit. Mais quand l'horloge se mit a sonner, elle dut courir."},{text:"La pantoufle lui allait parfaitement. Sa gentillesse s'etait vue depuis toujours, et la joie remplit ses journees.",dialogue:{speaker:"Cendrillon",line:"Etre gentil ne coute rien."}}],vocabulary:[{word:"taches",meaning:"petits travaux pour aider a la maison",emoji:"🧹"},{word:"carrosse",meaning:"une voiture tiree pour transporter des gens",emoji:"🛞"},{word:"minuit",meaning:"douze heures de la nuit",emoji:"🕛"},{word:"doux",meaning:"tendre, calme et gentil",emoji:"🕊️"}],miniGame:{type:"count",prompt:"A quelle heure Cendrillon doit-elle rentrer ? Compte les coups de l'horloge !",answer:12,options:[10,11,12]},emotionalMoment:{feeling:"plein d'espoir",prompt:"Meme les jours difficiles, Cendrillon restait gentille. Qu'est-ce qui t'aide a garder espoir ?"},rewardEmoji:"👠",rewardName:"Pantoufle de verre"},{id:"little-red-riding-hood",coverImage:e("c/c2/Carl_Larsson_-_Little_Red_Riding_Hood_1881.jpg"),title:"Le Petit Chaperon rouge",summary:"Une petite fille courageuse au chaperon rouge va chez sa grand-mere et apprend a ecouter ses sentiments sages en chemin.",theme:"ecouter et rester en securite",emoji:"🧣",palette:{primary:"#E84855",accent:"#FFB3B3",background:"#FFF4F2"},difficulty:"doux",ageMin:4,ageMax:8,scenes:[{text:"Une petite fille portait partout un chaperon rouge vif ; alors tout le monde l'appelait le Petit Chaperon rouge."},{text:"Sa maman lui donna un panier de pain pour mamie.",dialogue:{speaker:"Maman",line:"Reste sur le chemin et tout ira tres bien."}},{text:"Dans les bois, un loup ruse posa beaucoup de questions. Le Petit Chaperon sentit quelque chose de bizarre et continua a marcher.",dialogue:{speaker:"Petit Chaperon",line:"Je n'ai pas a te repondre. Je le dirai a un adulte."}},{text:"Un gentil bucheron l'entendit et marcha avec elle. Ensemble, ils arriverent chez mamie."},{text:"Mamie etait en securite, et le Petit Chaperon aussi. Ils partagerent du bon pain chaud et rirent tout l'apres-midi.",dialogue:{speaker:"Mamie",line:"Tu as ecoute tes sentiments sages. Je suis fiere de toi."}}],vocabulary:[{word:"chemin",meaning:"une voie qui montre par ou aller en securite",emoji:"🛤️"},{word:"panier",meaning:"un porteur avec une anse pour transporter des choses",emoji:"🧺"},{word:"ruse",meaning:"qui fait des tours pour te tromper",emoji:"🦊"},{word:"bucheron",meaning:"une personne qui travaille parmi les arbres",emoji:"🪓"}],miniGame:{type:"choice",prompt:"Un inconnu demande au Petit Chaperon ou elle va. Quel est le choix sur ?",options:["Tout lui raconter","Continuer a marcher et prevenir un adulte","Le suivre entre les arbres"],answerIndex:1},emotionalMoment:{feeling:"en securite",prompt:"Le Petit Chaperon a ecoute sa sensation bizarre. Quand un sentiment t'a-t-il aide a rester en securite ?"},rewardEmoji:"🧣",rewardName:"Chaperon rouge"},{id:"hansel-and-gretel",coverImage:e("a/a4/Hansel_and_Gretel4.jpg"),title:"Hansel et Gretel",summary:"Un frere et une soeur se perdent dans les bois et utilisent un plan astucieux, et leur esprit d'equipe, pour rentrer sains et saufs.",theme:"astuce et rester ensemble",emoji:"✨",palette:{primary:"#B7791F",accent:"#FBD38D",background:"#FFFBF0"},difficulty:"aventure",ageMin:5,ageMax:8,scenes:[{text:"Hansel et Gretel entrerent dans la grande foret, se tenant la main pour ne pas se perdre."},{text:"L'astucieux Hansel laissa tomber de petits cailloux blancs et brillants, un a un, pour marquer le retour.",dialogue:{speaker:"Hansel",line:"Ces cailloux brilleront et nous rameneront a la maison."}},{text:"Ils trouverent une petite maison faite de friandises, mais une vieille femme rusee y habitait."},{text:"Les enfants etaient trop malins pour se laisser tromper. Ils se prirent la main et sortirent sur la pointe des pieds.",dialogue:{speaker:"Gretel",line:"Vite — ensemble, nous sommes plus courageux que seuls."}},{text:"Les cailloux brillants luisirent au clair de lune et les ramenerent droit a la maison, vers un calin tout chaud."}],vocabulary:[{word:"cailloux",meaning:"de petites pierres bien lisses",emoji:"🪨"},{word:"astucieux",meaning:"doue pour trouver des idees malines",emoji:"💡"},{word:"sur la pointe des pieds",meaning:"marcher tout doucement sur les orteils",emoji:"🦶"},{word:"ensemble",meaning:"l'un avec l'autre, cote a cote",emoji:"🤝"}],miniGame:{type:"sequence",prompt:"Remets le plan astucieux de Hansel dans l'ordre !",steps:["Laisser tomber les cailloux brillants","Suivre la piste qui scintille","Retrouver le chemin de la maison"]},emotionalMoment:{feeling:"courageux ensemble",prompt:"Les enfants etaient plus courageux en equipe. Qui te rend plus courageux ?"},rewardEmoji:"✨",rewardName:"Caillou brillant"},{id:"rapunzel",coverImage:e("4/4e/Rapunzel_-_Vintage_Illustration.jpg"),title:"Raiponce",summary:"Une gentille fille aux tres longs cheveux vit dans une haute tour et apprend que la patience et un coeur plein d'espoir peuvent ouvrir n'importe quelle porte.",theme:"patience et espoir",emoji:"👑",palette:{primary:"#9B59B6",accent:"#D7BDE2",background:"#FAF4FF"},difficulty:"aventure",ageMin:5,ageMax:8,scenes:[{text:"Tout en haut d'une grande tour vivait Raiponce, une fille avec la plus longue tresse doree du monde."},{text:"Chaque jour, Raiponce chantait aux oiseaux. Sa douce chanson flottait sur toute la foret.",dialogue:{speaker:"Raiponce",line:"Un jour, je verrai le monde la-bas, sous les arbres."}},{text:'Un gentil voyageur entendit sa chanson et lui cria : "Ta musique fait sourire la foret !"',dialogue:{speaker:"Voyageur",line:"Ta musique fait sourire toute la foret !"}},{text:"Ils devinrent amis. Jour apres jour, avec patience, ils imaginerent une maniere maline de descendre."},{text:"Enfin, Raiponce posa le pied sur l'herbe douce et tournoya au soleil, libre et heureuse.",dialogue:{speaker:"Raiponce",line:"Attendre etait dur, mais l'espoir m'a gardee forte."}}],vocabulary:[{word:"tour",meaning:"un batiment tres haut et etroit",emoji:"🗼"},{word:"tresse",meaning:"des cheveux tisses en une longue corde",emoji:"💇"},{word:"patience",meaning:"attendre calmement sans abandonner",emoji:"⏳"},{word:"prairie",meaning:"un champ d'herbe plein de fleurs",emoji:"🌼"}],miniGame:{type:"find",prompt:"Trouve ce que Raiponce a utilise pour descendre en securite.",target:"l'echelle en tresse doree",decoys:["un cerf-volant en papier","une cuillere en bois","une petite tasse"]},emotionalMoment:{feeling:"patient",prompt:"Raiponce a attendu avec espoir. Quelle belle chose as-tu attendue longtemps ?"},rewardEmoji:"👑",rewardName:"Tresse doree"},{id:"the-ugly-duckling",coverImage:e("9/97/The_Ugly_Duckling_-_Project_Gutenberg_etext_19993.jpg"),title:"Le Vilain Petit Canard",summary:"Un petit oiseau qui se sent different des autres grandit et decouvre qu'il etait merveilleux exactement comme il etait, depuis toujours.",theme:"appartenir et s'aimer",emoji:"🦢",palette:{primary:"#3498DB",accent:"#AED6F1",background:"#EBF5FB"},difficulty:"doux",ageMin:4,ageMax:8,scenes:[{text:"Dans une mare ensoleillee, un petit oiseau ne ressemblait pas a ses freres et soeurs."},{text:"Les autres oiseaux se moquaient de lui, et au fond il se sentait seul et tres triste.",dialogue:{speaker:"Petit oiseau",line:"J'aimerais que quelqu'un me laisse jouer aussi."}},{text:`Une gentille grenouille s'approcha en sautant et s'assit pres de lui. "Tu es le bienvenu avec moi", dit-elle.`,dialogue:{speaker:"Grenouille",line:"Tu es le bienvenu avec moi, mon ami."}},{text:"Les saisons passerent. Un matin lumineux, le petit oiseau vit son visage dans l'eau calme."},{text:"Il etait devenu un magnifique cygne ! Il avait toujours ete special : tout simplement lui-meme.",dialogue:{speaker:"Cygne",line:"Je n'avais pas besoin de changer. J'avais juste besoin de grandir."}}],vocabulary:[{word:"mare",meaning:"une petite etendue d'eau calme",emoji:"💧"},{word:"seul",meaning:"triste parce qu'on se sent tout seul",emoji:"🥺"},{word:"reflet",meaning:"l'image que tu vois dans l'eau calme",emoji:"🪞"},{word:"cygne",meaning:"un grand oiseau d'eau blanc et gracieux",emoji:"🦢"}],miniGame:{type:"choice",prompt:"Un nouvel ami se sent mis a l'ecart. Quelle chose gentille peux-tu dire ?",options:["Tu n'es pas a ta place ici","Tu peux jouer avec nous !","Va-t'en"],answerIndex:1},emotionalMoment:{feeling:"j'ai ma place",prompt:"Le petit oiseau etait special tel qu'il etait. Qu'est-ce qui fait de toi un merveilleux toi ?"},rewardEmoji:"🦢",rewardName:"Cygne tout doux"},{id:"the-little-mermaid",coverImage:e("2/20/The_Little_Mermaid_-_Illustration_by_Edmund_Dulac.jpg"),title:"La Petite Sirene",summary:"Une jeune sirene curieuse a le courage d'explorer un monde nouveau, et apprend qu'un coeur gentil et genereux brille plus que tout.",theme:"courage et bon coeur",emoji:"🐚",palette:{primary:"#1ABC9C",accent:"#A9DFBF",background:"#F0FBF7"},difficulty:"explorateur",ageMin:6,ageMax:8,scenes:[{text:"Au fond des vagues vivait une jeune sirene, la plus petite de six soeurs."},{text:"Elle adorait monter a la surface et regarder le monde lumineux au-dessus de l'eau.",dialogue:{speaker:"Sirene",line:"Le monde d'en haut est plein de choses que je veux apprendre !"}},{text:"Une nuit de tempete, avec courage, elle aida un marin a rejoindre le rivage sain et sauf."},{text:"Elle ne resta pas pour etre remerciee. Aider quelqu'un remplissait son coeur de chaleur.",dialogue:{speaker:"Sirene",line:"J'ai aide par gentillesse, pas pour un merci."}},{text:"De retour chez elle, elle raconta son histoire courageuse, et son bon coeur fit briller toute la mer."}],vocabulary:[{word:"sirene",meaning:"une fille de la mer imaginaire, avec une queue de poisson",emoji:"🧜"},{word:"vagues",meaning:"l'eau qui monte et descend sur la mer",emoji:"🌊"},{word:"courageux",meaning:"faire une chose difficile meme si elle fait peur",emoji:"💪"},{word:"genereux",meaning:"heureux de donner et d'aider les autres",emoji:"💝"}],miniGame:{type:"count",prompt:"Combien de grandes soeurs avait la Petite Sirene ?",answer:6,options:[5,6,7]},emotionalMoment:{feeling:"au grand coeur",prompt:"La sirene a aide juste par gentillesse. Quand as-tu aide sans qu'on te le demande ?"},rewardEmoji:"🐚",rewardName:"Perle de la mer"},{id:"the-snow-queen",coverImage:e("3/38/Edmund_Dulac_-_The_Snow_Queen.jpg"),title:"La Reine des Neiges",summary:"Quand le coeur de son meilleur ami devient froid, une fille fidele nommee Gerda voyage loin dans la neige pour le rechauffer avec amour.",theme:"amitie fidele",emoji:"❄️",palette:{primary:"#5DADE2",accent:"#AED6F1",background:"#EBF5FB"},difficulty:"explorateur",ageMin:6,ageMax:8,scenes:[{text:"Gerda et Kai etaient les meilleurs amis et cultivaient des roses ensemble pres de leur fenetre."},{text:"Un tout petit eclat de givre toucha le coeur de Kai, et il devint froid et lointain.",dialogue:{speaker:"Gerda",line:"Attends... ou vas-tu, Kai ?"}},{text:"La courageuse Gerda n'abandonna pas. Elle partit a travers la neige chercher son ami.",dialogue:{speaker:"Gerda",line:"Je vais te retrouver, Kai. Les amis n'abandonnent pas."}},{text:"Elle trouva Kai dans un palais de glace, assis, immobile et froid comme la pierre."},{text:"Gerda le serra dans ses bras et des larmes chaudes coulerent. Le givre fondit, et Kai sourit et se souvint.",dialogue:{speaker:"Kai",line:"Tu es venue jusqu'ici pour moi. Merci, Gerda."}}],vocabulary:[{word:"givre",meaning:"une fine glace qui se forme quand il fait tres froid",emoji:"🌨️"},{word:"fidele",meaning:"toujours la pour ses amis",emoji:"🤲"},{word:"palais",meaning:"une maison tres grande et magnifique",emoji:"🏰"},{word:"fondre",meaning:"passer de la glace a l'eau avec la chaleur",emoji:"💧"}],miniGame:{type:"choice",prompt:"Comment Gerda a-t-elle fait fondre la glace dans le coeur de Kai ?",options:["Avec un grand feu","Avec des larmes chaudes et un calin","Avec un marteau"],answerIndex:1},emotionalMoment:{feeling:"fidele",prompt:"Gerda n'a jamais abandonne son ami. Comment montres-tu a un ami que tu tiens a lui ?"},rewardEmoji:"🌹",rewardName:"Rose toute chaude"},{id:"puss-in-boots",coverImage:e("d/d4/Puss_in_boots_briton_riviere.jpg"),title:"Le Chat botte",summary:"Un chat malin aux belles bottes utilise sa vivacite d'esprit, et son grand coeur fidele, pour aider son gentil ami a trouver le bonheur.",theme:"astuce et loyaute",emoji:"🐱",palette:{primary:"#E67E22",accent:"#FAD7A0",background:"#FFFAF0"},difficulty:"aventure",ageMin:5,ageMax:8,scenes:[{text:"Un chat malin enfila de belles bottes et un chapeau a plume, pret pour l'aventure."},{text:"Son ami etait pauvre mais gentil, alors le chat imagina un plan malin pour l'aider.",dialogue:{speaker:"Le Chat",line:"Fais-moi confiance, mon ami. Une idee maline arrive !"}},{text:"Le chat salua le roi avec politesse et offrit des cadeaux, faisant sourire tout le monde."},{text:"Avec de l'esprit plutot que des ruses, le chat aida son ami a gagner un grand chateau au bord de la riviere.",dialogue:{speaker:"Le Chat",line:"Les bonnes idees ouvrent plus de portes que les grands rugissements."}},{text:"Son ami fut enfin heureux, et le chat se pelotonna pres du feu, le chat le plus fidele de tous."}],vocabulary:[{word:"malin",meaning:"doue pour trouver des idees astucieuses",emoji:"🧠"},{word:"bottes",meaning:"des chaussures qui montent haut sur les jambes",emoji:"🥾"},{word:"poli",meaning:"gentil et doux avec ses mots",emoji:"🙏"},{word:"fidele",meaning:"toujours la pour ses amis",emoji:"🤝"}],miniGame:{type:"sequence",prompt:"Remets le plan malin du Chat dans l'ordre !",steps:["Enfiler les belles bottes","Saluer le roi avec politesse","Aider son ami a gagner la journee"]},emotionalMoment:{feeling:"serviable",prompt:"Le Chat a use d'idees malines pour aider un ami. De quelle facon astucieuse as-tu deja aide quelqu'un ?"},rewardEmoji:"🥾",rewardName:"Belles bottes"},{id:"pinocchio",coverImage:e("c/c8/Carlo_Chiostri-Pinocchio_1901-p214.jpg"),title:"Pinocchio",summary:"Une marionnette de bois qui reve d'etre un vrai garcon apprend que dire la verite, c'est ce qui fait grandir un bon coeur.",theme:"honnetete",emoji:"🪵",palette:{primary:"#27AE60",accent:"#A9DFBF",background:"#F0FBF5"},difficulty:"aventure",ageMin:5,ageMax:8,scenes:[{text:"Il etait une fois une petite marionnette de bois nommee Pinocchio, qui revait de devenir un vrai garcon."},{text:"Chaque fois que Pinocchio disait un mensonge, son nez s'allongeait comme une branche.",dialogue:{speaker:"Pinocchio",line:"Ce n'est pas moi ! Je promets !"}},{text:"Son ami grillon essayait de lui apprendre a toujours dire la verite.",dialogue:{speaker:"Grillon",line:"Dire la verite te rendra leger comme une plume."}},{text:"Pinocchio fit une grosse erreur et se retrouva perdu. Il apprit alors que l'honnetete etait son seul guide."},{text:"Quand Pinocchio dit enfin la verite, son coeur grandit, et son voeu le plus cher se realisa.",dialogue:{speaker:"Pinocchio",line:"La verite, c'est la magie la plus puissante de toutes."}}],vocabulary:[{word:"marionnette",meaning:"une poupee que l'on fait bouger",emoji:"🎭"},{word:"verite",meaning:"dire exactement ce qui s'est passe",emoji:"✅"},{word:"mensonge",meaning:"dire quelque chose qui n'est pas vrai",emoji:"❌"},{word:"honnete",meaning:"quelqu'un qui dit toujours la verite",emoji:"🌟"}],miniGame:{type:"choice",prompt:"Quand le nez de Pinocchio s'allonge-t-il ?",options:["Quand il dit la verite","Quand il dit un mensonge","Quand il chante une chanson"],answerIndex:1},emotionalMoment:{feeling:"honnete",prompt:"Dire la verite a rendu Pinocchio leger. Que ressens-tu quand tu dis la verite ?"},rewardEmoji:"🦗",rewardName:"Grillon de la verite"},{id:"peter-pan",coverImage:e("6/6d/Peter_Pan_1915_poster.jpg"),title:"Peter Pan",summary:"Un garcon qui ne grandit jamais emmene de nouveaux amis dans une aventure volante ou les pensees heureuses et un peu de courage menent partout.",theme:"imagination et courage",emoji:"🧚",palette:{primary:"#16A085",accent:"#A2D9CE",background:"#F0F9F8"},difficulty:"explorateur",ageMin:6,ageMax:8,scenes:[{text:"Dans une chambre pleine d'etoiles, un garcon nomme Peter Pan apprit aux enfants a voler."},{text:"Peter dit a Wendy le secret : il fallait penser a quelque chose de tres heureux.",dialogue:{speaker:"Peter Pan",line:"Pense a ta chose la plus heureuse — et hop, tu t'envoles !"}},{text:"Ensemble, ils s'envolerent vers le Pays Imaginaire, une ile magique pleine d'aventures."},{text:"Meme face au mechant capitaine, Peter n'eut pas peur. Il affronta le danger avec un grand sourire.",dialogue:{speaker:"Peter Pan",line:"Etre courageux, c'est essayer quand meme."}},{text:"Les enfants rentrerent chez eux avec des souvenirs plein le coeur et un zeste de magie pour toujours."}],vocabulary:[{word:"chambre",meaning:"la piece ou l'on dort et ou l'on reve",emoji:"🛏️"},{word:"ombre",meaning:"la forme sombre que ton corps fait sur le sol",emoji:"👤"},{word:"imaginer",meaning:"creer des choses belles dans sa tete",emoji:"💭"},{word:"courage",meaning:"essayer meme quand on a peur",emoji:"💪"}],miniGame:{type:"choice",prompt:"Qu'est-ce qui a aide les enfants a voler ?",options:["Des pensees heureuses et de la poudre de fee","Des bottes lourdes","Crier tres fort"],answerIndex:0},emotionalMoment:{feeling:"courageux",prompt:"Peter dit qu'etre courageux, c'est essayer quand meme. Quelle chose courageuse aimerais-tu essayer ?"},rewardEmoji:"✨",rewardName:"Poudre de fee"},{id:"alice-in-wonderland",coverImage:e("a/a5/Alice_in_Wonderland_-_Lewis_Carroll_-_Alices_Adventures_in_Wonderland_1865.jpg"),title:"Alice au pays des merveilles",summary:"Une fille curieuse suit un lapin presse dans un monde sens dessus dessous et apprend que poser des questions, c'est une sorte de magie.",theme:"curiosite",emoji:"🐇",palette:{primary:"#8E44AD",accent:"#D2B4DE",background:"#F9F0FF"},difficulty:"explorateur",ageMin:6,ageMax:8,scenes:[{text:"Alice vit un lapin blanc presse sauter dans un terrier et, tres curieuse, elle le suivit."},{text:"Elle tomba dans un long couloir magique et trouva une toute petite porte dans un jardin.",dialogue:{speaker:"Alice",line:"Comme c'est etrange ! Je me demande ce qui se passe ici."}},{text:"Alice but une petite bouteille et rapetissa, puis mangea un gateau et grandit tres vite.",dialogue:{speaker:"Alice",line:"Les questions sont la cle de toutes les merveilles !"}},{text:"Elle rencontra un chat souriant, une reine colereuse et un grand chapelier fou."},{text:"Alice se reveilla et sourit. Poser des questions l'avait menee dans le plus beau des reves.",dialogue:{speaker:"Alice",line:"La curiosite est la plus grande aventure."}}],vocabulary:[{word:"curieuse",meaning:"quelqu'un qui aime decouvrir de nouvelles choses",emoji:"🔍"},{word:"terrier",meaning:"un tunnel creuse dans la terre par un animal",emoji:"🕳️"},{word:"rapetisser",meaning:"devenir plus petit",emoji:"🔻"},{word:"merveille",meaning:"quelque chose d'incroyable et de tres surprenant",emoji:"😲"}],miniGame:{type:"sequence",prompt:"Remets l'aventure d'Alice dans l'ordre !",steps:["Boire la bouteille et rapetisser","Manger le gateau et grandir","Trouver la petite porte du jardin"]},emotionalMoment:{feeling:"curieux",prompt:"Alice adorait poser des questions. Qu'est-ce qui te rend curieux aujourd'hui ?"},rewardEmoji:"⏰",rewardName:"Horloge curieuse"},{id:"the-wizard-of-oz",coverImage:e("8/81/The_Wonderful_Wizard_of_Oz_cover_art.jpg"),title:"Le Magicien d'Oz",summary:"Une fille et trois nouveaux amis suivent une route doree et decouvrent que les cadeaux qu'ils cherchaient etaient en eux depuis le debut.",theme:"tu as deja ce qu'il te faut",emoji:"🌈",palette:{primary:"#F39C12",accent:"#FAD7A0",background:"#FFFBF0"},difficulty:"explorateur",ageMin:6,ageMax:8,scenes:[{text:"Un grand tourbillon emporta Dorothee et son petit chien Toto dans le pays magique d'Oz."},{text:"Sur la route doree, Dorothee rencontra un epouvantail, un homme de fer-blanc et un lion.",dialogue:{speaker:"Epouvantail",line:"Je veux juste un cerveau malin !"}},{text:"Ensemble, ils marchererent vers la ville d'Emeraude pour trouver le grand Magicien.",dialogue:{speaker:"Dorothee",line:"Si nous sommes ensemble, nous pouvons tout faire."}},{text:"Le Magicien leur revela un grand secret : ils possedaient deja tout ce qu'ils desiraient."},{text:"Dorothee appuya trois fois ses souliers et retrouva sa maison. Chacun avait trouve son cadeau.",dialogue:{speaker:"Dorothee",line:"Il n'y a nulle part de mieux que chez soi."}}],vocabulary:[{word:"tourbillon",meaning:"un vent tres fort qui tourne en rond",emoji:"🌪️"},{word:"epouvantail",meaning:"une grande poupee de paille pour effrayer les oiseaux",emoji:"🌾"},{word:"courage",meaning:"continuer meme quand on a peur",emoji:"💪"},{word:"voyage",meaning:"une longue marche ou aventure vers un endroit nouveau",emoji:"🗺️"}],miniGame:{type:"choice",prompt:"Quel ami avait deja du courage depuis le debut ?",options:["L'epouvantail","L'homme de fer-blanc","Le lion"],answerIndex:2},emotionalMoment:{feeling:"capable",prompt:"Les amis avaient deja leurs cadeaux en eux. Quel cadeau as-tu deja en toi ?"},rewardEmoji:"👟",rewardName:"Souliers scintillants"},{id:"robin-hood",coverImage:e("1/14/Robin_Hood_and_Maid_Marian_cropped.jpg"),title:"Robin des Bois",summary:"Un gentil archer de la foret verte partage avec ceux qui ont tres peu et apprend a ses amis que la justice rend tout le monde plus heureux.",theme:"justice et generosite",emoji:"🏹",palette:{primary:"#27AE60",accent:"#A9DFBF",background:"#F0FBF5"},difficulty:"aventure",ageMin:5,ageMax:8,scenes:[{text:"Dans une grande foret verte vivait Robin des Bois, le meilleur archer du pays."},{text:"Il vit que beaucoup de gens etaient tres pauvres pendant que d'autres avaient tout.",dialogue:{speaker:"Robin",line:"Partager, c'est le plus beau des cadeaux."}},{text:"Avec ses amis joyeux, Robin devisa un plan pour aider ceux dans le besoin.",dialogue:{speaker:"Petit Jean",line:"Ensemble, nous sommes la force de la foret !"}},{text:"Robin distribua ce dont les gens avaient besoin, et des sourires fleurirent partout."},{text:"La foret bourdonnait de bonheur. Robin avait appris que la generosite est la vraie victoire.",dialogue:{speaker:"Robin",line:"La generosite rend tout le monde plus riche."}}],vocabulary:[{word:"archer",meaning:"quelqu'un qui tire des fleches avec un arc",emoji:"🎯"},{word:"foret",meaning:"un grand endroit plein d'arbres et d'animaux",emoji:"🌳"},{word:"juste",meaning:"traiter tout le monde de la meme facon",emoji:"⚖️"},{word:"genereux",meaning:"qui aime donner et partager",emoji:"🎁"}],miniGame:{type:"choice",prompt:"Robin des Bois partageait avec des gens qui etaient...",options:["affames et dans le besoin","deja tres riches","mechants avec les autres"],answerIndex:0},emotionalMoment:{feeling:"juste",prompt:"Robin adorait partager. Que pourrais-tu partager pour faire sourire un ami ?"},rewardEmoji:"🏹",rewardName:"Arc amical"},{id:"goldilocks",coverImage:e("c/cb/Goldilocks_and_the_Three_Bears_-_Project_Gutenberg_etext_17034.jpg"),title:"Boucle d'or et les trois ours",summary:"Une fille curieuse entre dans la chaumiere douillette des ours et apprend qu'il vaut mieux demander d'abord et prendre soin des affaires des autres.",theme:"le respect des autres",emoji:"🐻",palette:{primary:"#D4A017",accent:"#FAD7A0",background:"#FFFBF0"},difficulty:"doux",ageMin:4,ageMax:8,scenes:[{text:"Une petite fille aux boucles dorees se promenait dans la foret quand elle trouva une jolie chaumiere."},{text:"Elle entra et gouta trois bols de bouillie. Celui du bebe ours etait parfait.",dialogue:{speaker:"Boucle d'or",line:"Oh ! Ce bol est parfait, ni trop chaud ni trop froid !"}},{text:"Elle essaya trois chaises, puis trois lits. Elle s'endormit dans le plus douillet."},{text:"Les trois ours rentrerent et trouverent leur maison bousculee.",dialogue:{speaker:"Bebe ours",line:"Quelqu'un a mange dans mon bol !"}},{text:"Boucle d'or se reveilla, s'excusa et apprit que demander d'abord est la politesse la plus douce.",dialogue:{speaker:"Boucle d'or",line:"Pardon. Je demanderai toujours avant d'entrer."}}],vocabulary:[{word:"bouillie",meaning:"une nourriture chaude et douce, comme la cereale du matin",emoji:"🥣"},{word:"chaumiere",meaning:"une petite maison douillette dans la foret",emoji:"🏡"},{word:"respect",meaning:"prendre soin des affaires et des sentiments des autres",emoji:"🙏"},{word:"desole",meaning:"ce qu'on dit quand on regrette quelque chose",emoji:"💙"}],miniGame:{type:"count",prompt:"Combien d'ours vivaient dans la chaumiere douillette ?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"respectueux",prompt:"Boucle d'or a appris a demander d'abord. Quand est-ce gentil de demander avant d'emprunter quelque chose ?"},rewardEmoji:"🥣",rewardName:"Bol parfait"},{id:"three-little-pigs",coverImage:e("9/93/Three-pigs-1.jpg"),title:"Les Trois Petits Cochons",summary:"Trois petits cochons construisent trois maisons differentes et apprennent qu'un travail soigneux et applique garde tout le monde en securite et au chaud.",theme:"travail et organisation",emoji:"🐷",palette:{primary:"#E74C3C",accent:"#FADBD8",background:"#FFF5F4"},difficulty:"doux",ageMin:4,ageMax:8,scenes:[{text:"Trois petits cochons partirent dans le monde pour construire leur maison."},{text:"Le premier construisit vite une maison de paille. Le deuxieme, une maison de bois.",dialogue:{speaker:"Premier cochon",line:"Vite fait, bien fait ! Je veux aller jouer !"}},{text:"Le troisieme cochon travailla dur et construisit une maison solide de briques, pierre par pierre.",dialogue:{speaker:"Troisieme cochon",line:"Je prends mon temps pour que ma maison soit solide."}},{text:"Le grand mechant loup souffla sur les maisons de paille et de bois, et elles s'ecroulerent."},{text:"Mais la maison de briques resta solide. Les trois cochons etaient en securite, et tout le monde apprit que travailler avec soin protege.",dialogue:{speaker:"Troisieme cochon",line:"Un bon travail prend du temps, mais ca en vaut la peine !"}}],vocabulary:[{word:"paille",meaning:"des tiges seches de plantes, faciles a casser",emoji:"🌾"},{word:"briques",meaning:"des blocs de terre cuite tres solides",emoji:"🧱"},{word:"resistante",meaning:"tres solide, pas facile a casser",emoji:"💪"},{word:"planifier",meaning:"reflechir avant de commencer quelque chose",emoji:"📋"}],miniGame:{type:"count",prompt:"Combien de petits cochons construisirent des maisons ?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"fier de mon travail",prompt:"Le troisieme cochon a travaille dur et est reste en securite. Sur quoi as-tu travaille dur, toi ?"},rewardEmoji:"🧱",rewardName:"Brique solide"},{id:"aladdin",coverImage:e("7/7e/Aladdin_and_the_Wonderful_Lamp_p58.jpg"),title:"Aladin et la lampe merveilleuse",summary:"Un garcon ordinaire et gentil trouve une lampe magique et apprend que ce que tu souhaites compte moins que le bien que tu fais aux autres.",theme:"honnetete et coeur humble",emoji:"🪔",palette:{primary:"#F39C12",accent:"#FAD7A0",background:"#FFFBF0"},difficulty:"aventure",ageMin:5,ageMax:8,scenes:[{text:"Dans un marche anime vivait Aladin, un garcon pauvre mais au coeur d'or."},{text:"Il trouva une vieille lampe et, en la frottant, un grand genie en sortit !",dialogue:{speaker:"Genie",line:"Je t'accorde trois souhaits. Choisis avec soin !"}},{text:"Aladin souhaiita d'abord aider sa famille, puis les gens pauvres de son quartier.",dialogue:{speaker:"Aladin",line:"Je veux que personne dans ce marche ne soit affame."}},{text:"Son humilite et sa generosite lui gagnererent de vrais amis et beaucoup de bonheur."},{text:"Aladin apprit que les meilleurs souhaits sont ceux que l'on fait pour les autres.",dialogue:{speaker:"Aladin",line:"Un coeur genereux est le plus grand des tresors."}}],vocabulary:[{word:"marche",meaning:"un endroit anime ou les gens vendent et achetent",emoji:"🏪"},{word:"lampe",meaning:"un objet qui donne de la lumiere ou garde un genie",emoji:"🪔"},{word:"humble",meaning:"quelqu'un qui ne se vante pas de lui-meme",emoji:"🙏"},{word:"souhait",meaning:"quelque chose que tu desires tres fort",emoji:"⭐"}],miniGame:{type:"count",prompt:"Combien de souhaits le genie a-t-il donnes a Aladin ?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"genereux",prompt:"Aladin a souhaite aider les autres. Si tu avais un souhait gentil, lequel serait-ce ?"},rewardEmoji:"🪔",rewardName:"Lampe a souhaits"},{id:"ali-baba",coverImage:e("9/9a/Ali_Baba_Forty_Thieves_Cassim.jpg"),title:"Ali Baba et les quarante voleurs",summary:"Un doux bucheron decouvre une grotte secrete et apprend qu'etre honnete et prudent vaut bien mieux qu'etre avide.",theme:"l'honnetete plutot que l'avidite",emoji:"💎",palette:{primary:"#8E44AD",accent:"#D2B4DE",background:"#F9F0FF"},difficulty:"aventure",ageMin:5,ageMax:8,scenes:[{text:"Ali Baba etait un bucheron doux qui vivait simplement et contenment."},{text:"Un jour dans la foret, il entendit des voleurs dire les mots magiques devant un grand rocher.",dialogue:{speaker:"Voleurs",line:"Sesame, ouvre-toi !"}},{text:"Ali Baba entra dans la grotte et vit des tresors etincelants de toutes les couleurs.",dialogue:{speaker:"Ali Baba",line:"Je prendrai juste ce qu'il nous faut, pas plus."}},{text:"Son frere avide prit trop et fut surpris par les voleurs. Ali Baba comprit la lecon."},{text:"Ali Baba partagea sa bonne fortune avec les autres et vecut simplement et heureusement.",dialogue:{speaker:"Ali Baba",line:"Avoir assez et etre honnete, c'est la vraie richesse."}}],vocabulary:[{word:"grotte",meaning:"une grande cavite naturelle dans la roche",emoji:"🕳️"},{word:"tresor",meaning:"une grande quantite d'or et de choses precieuses",emoji:"💎"},{word:"avide",meaning:"quelqu'un qui veut toujours plus que ce qu'il lui faut",emoji:"😤"},{word:"assez",meaning:"juste ce dont on a besoin, ni plus ni moins",emoji:"✅"}],miniGame:{type:"choice",prompt:"Quels sont les mots magiques qui ouvrent la grotte ?",options:["Sesame, ouvre-toi !","Ferme la porte !","Bonjour !"],answerIndex:0},emotionalMoment:{feeling:"content",prompt:"Ali Baba n'a pris que ce qu'il fallait. Quelle chose que tu as deja est juste suffisante pour toi ?"},rewardEmoji:"🗝️",rewardName:"Grotte secrete"},{id:"aesops-fables",coverImage:e("a/a8/The-hare-and-the-tortoise.jpg"),title:"Fables d'Esope : Le Lievre et la Tortue",summary:"Un lievre rapide et une tortue lente font une course amicale, et la tortue apprend a tous que ne jamais abandonner gagne la journee.",theme:"perseverance — doucement mais surement",emoji:"🐢",palette:{primary:"#27AE60",accent:"#A9DFBF",background:"#F0FBF5"},difficulty:"doux",ageMin:4,ageMax:8,scenes:[{text:"Dans une prairie ensoleilee, un lievre rapide se vantait toujours de sa vitesse."},{text:"La tortue lente et calme proposa un defi. Le lievre accepta en riant.",dialogue:{speaker:"Lievre",line:"Une course contre toi ? Facile ! Je vais me reposer en chemin."}},{text:"La tortue avanca pas a pas, regulierement, sans jamais s'arreter.",dialogue:{speaker:"Tortue",line:"Doucement mais surement, j'avancerai."}},{text:"Le lievre s'endormit sous un arbre, sur que la tortue ne pourrait jamais le rattraper."},{text:"Quand le lievre se reveilla, la tortue avait deja franchi la ligne d'arrivee. Perseverer gagne toujours.",dialogue:{speaker:"Tortue",line:"Pas a pas, on arrive plus loin qu'on ne croit."}}],vocabulary:[{word:"lievre",meaning:"un grand lapin sauvage tres rapide",emoji:"🐇"},{word:"tortue",meaning:"un animal a carapace qui marche lentement mais sans s'arreter",emoji:"🐢"},{word:"regulier",meaning:"avancer au meme rythme, sans s'arretere",emoji:"⏱️"},{word:"perseverer",meaning:"continuer a essayer meme quand c'est difficile",emoji:"💪"}],miniGame:{type:"choice",prompt:"Qui a gagne la course en n'abandonnant jamais ?",options:["le lievre rapide","la tortue lente et reguliere","le renard endormi"],answerIndex:1},emotionalMoment:{feeling:"determine",prompt:"La tortue a continue pas apres pas. Sur quoi continues-tu d'essayer, toi ?"},rewardEmoji:"🐢",rewardName:"Tortue perseverante"},{id:"sleeping-beauty",coverImage:null,title:"La Belle au Bois Dormant",summary:"Une belle princesse tombe dans un sommeil magique et attend le vrai amour.",theme:"patience et esperance",emoji:"🌹",palette:{primary:"#e91e8c",accent:"#f8bbd9",background:"#1a0026"},difficulty:"doux",ageMin:4,ageMax:8,scenes:[{text:"Un roi et une reine heureux eurent enfin une petite fille. Ils inviterent toutes les fees du royaume pour la baptiser."},{text:"Les bonnes fees offrirent leurs dons a la princesse : beaute, grace, douceur. Mais une mauvaise fee arriva en colere.",dialogue:{speaker:"Mauvaise fee",line:"Quand elle aura seize ans, elle se piquera au fuseau et tombera morte !"}},{text:"La derniere bonne fee n'avait pas encore parle. Elle adoucit le sort : la princesse ne mourrait pas, elle dormirait cent ans.",dialogue:{speaker:"Bonne fee",line:"Elle dormira, mais l'amour la reveillera."}},{text:"A seize ans, la princesse trouva une vieille femme qui filait. Elle toucha le fuseau et tomba dans un profond sommeil. Tout le chateau s'endormit avec elle."},{text:"Un prince entendit parler du chateau endormi cache derriere une foret de roses. Il coupa les ronces et penetra dans le chateau silencieux.",dialogue:{speaker:"Prince",line:"Comme elle est belle ! Je vais la reveiller."}},{text:"Le prince s'approcha de la belle princesse et lui donna un doux baiser. Elle ouvrit les yeux et sourit. Tout le chateau se reveilla en meme temps, et ils vecurent heureux.",dialogue:{speaker:"Princesse",line:"J'ai attendu si longtemps. Enfin tu es arrive !"}}],vocabulary:[{word:"fuseau",meaning:"un outil pour filer la laine, avec une pointe",emoji:"🧵"},{word:"malefique",meaning:"qui fait du mal avec de la magie mechante",emoji:"🧙"},{word:"enchante",meaning:"transforme par une magie speciale",emoji:"✨"},{word:"rosier",meaning:"un buisson qui fait pousser de belles roses",emoji:"🌹"}],miniGame:{type:"choice",prompt:"Quelle mauvaise fee lance le sort sur la princesse ?",options:["Une fee qui n'etait pas invitee","La fee du palais","La fee de la foret"],answerIndex:0},emotionalMoment:{feeling:"espoir",prompt:"As-tu deja attendu quelque chose avec impatience ? Comment tu te sentais ?"},rewardEmoji:"🌹",rewardName:"Rose Enchantee"},{id:"beauty-and-the-beast",coverImage:null,title:"La Belle et la Bete",summary:"Belle apprend que la vraie beaute se trouve dans le coeur, pas dans l'apparence.",theme:"gentillesse et amour vrai",emoji:"🌺",palette:{primary:"#d4af37",accent:"#8b0000",background:"#0d0005"},difficulty:"aventure",ageMin:5,ageMax:9,scenes:[{text:"Un marchand se perdit dans la foret pendant une tempete. Il trouva un grand chateau mysterieux et s'y abrita pour la nuit."},{text:"En repartant, le marchand cueillit une rose pour sa fille Belle. Une Bete terrifiante surgit alors.",dialogue:{speaker:"Bete",line:"Tu as vole ma rose ! Tu es mon prisonnier !"}},{text:"Le marchand supplia la Bete de le laisser dire au revoir a ses enfants. La Bete accepta, a condition qu'une de ses filles revienne a sa place.",dialogue:{speaker:"Belle",line:"Papa, je vais y aller. Je n'ai pas peur."}},{text:"Belle vecut au chateau. La Bete etait laide mais douce et gentille. Chaque soir, ils parlaient et riaient ensemble."},{text:"Belle demanda a rentrer chez elle voir son pere malade. La Bete accepta tristement.",dialogue:{speaker:"Bete",line:"Tu me manqueras, Belle. Mais ton bonheur passe avant le mien."}},{text:"Belle, loin du chateau, realisa qu'elle aimait la Bete. Elle courut la retrouver. En confessant son amour, la Bete se transforma en beau prince.",dialogue:{speaker:"Belle",line:"Je t'aime, non pour ton visage, mais pour ton coeur."}},{text:"Le prince expliqua qu'une sorciere l'avait enchante. Seul l'amour sincere pouvait le liberer. Belle et le prince vecurent heureux pour toujours."}],vocabulary:[{word:"bete",meaning:"un grand animal effrayant, ici un monstre enchante",emoji:"🐾"},{word:"prisonnier",meaning:"quelqu'un qui ne peut pas partir librement",emoji:"🔒"},{word:"apparence",meaning:"ce qu'on voit de quelqu'un de l'exterieur",emoji:"👁️"},{word:"transformation",meaning:"changer completement de forme ou d'aspect",emoji:"✨"}],miniGame:{type:"choice",prompt:"Pourquoi le pere de Belle va-t-il au chateau ?",options:["Il cherche un tresor","Il s'abrite de la tempete et cueille une rose","Il rend visite a la Bete"],answerIndex:1},emotionalMoment:{feeling:"gentillesse",prompt:"As-tu deja juge quelqu'un sur son apparence avant de le connaitre ?"},rewardEmoji:"🌺",rewardName:"Rose Magique"},{id:"little-thumb",coverImage:null,title:"Le Petit Poucet",summary:"Le plus petit des sept freres utilise son intelligence pour sauver sa famille.",theme:"courage et intelligence",emoji:"👣",palette:{primary:"#2e7d32",accent:"#a5d6a7",background:"#001209"},difficulty:"aventure",ageMin:5,ageMax:9,scenes:[{text:"Un pauvre bucheron et sa femme avaient sept fils. Le plus petit s'appelait le Petit Poucet. Il etait minuscule mais tres intelligent."},{text:"Un soir, le pere et la mere, trop pauvres pour nourrir leurs enfants, les abandonnerent dans la foret.",dialogue:{speaker:"Petit Poucet",line:"Je savais qu'ils allaient faire ca. Je suis pret."}},{text:"Le Petit Poucet avait prevu le coup : il avait rempli ses poches de petits cailloux blancs. Il en sema tout le long du chemin, et les enfants retrouverent la maison grace a eux."},{text:"Une deuxieme fois abandonnes, le Petit Poucet n'avait que du pain pour semer des miettes. Les oiseaux les mangerent et les freres se perdirent pour de bon."},{text:"Perdus, ils arriverent a la maison d'un ogre. La femme de l'ogre les cacha, mais l'ogre les trouva.",dialogue:{speaker:"Ogre",line:"Je sens la chair fraiche ! Ou sont-ils caches ?"}},{text:"Le Petit Poucet eut une idee brillante : il echangea les bonnets de ses freres avec les couronnes des filles de l'ogre. L'ogre se trompa dans l'obscurite."},{text:"Le Petit Poucet vola les bottes de sept lieues de l'ogre endormi. En quelques pas, il put ramener de l'or et sauver toute sa famille.",dialogue:{speaker:"Petit Poucet",line:"L'intelligence vaut mieux que la force !"}}],vocabulary:[{word:"cailloux",meaning:"de petites pierres lisses qu'on peut semer en chemin",emoji:"🪨"},{word:"ogre",meaning:"un grand monstre qui mange les enfants dans les contes",emoji:"👹"},{word:"lieue",meaning:"une grande distance, comme plusieurs kilometres",emoji:"🗺️"},{word:"ruse",meaning:"une idee maline pour tromper quelqu'un",emoji:"💡"}],miniGame:{type:"sequence",prompt:"Remets les etapes dans l'ordre !",steps:["Semer les cailloux blancs pour retrouver le chemin","Arriver chez l'ogre dans la foret","Voler les bottes de sept lieues"]},emotionalMoment:{feeling:"courage",prompt:"As-tu deja eu peur mais tu as quand meme continue ? Qu'est-ce qui t'a aide ?"},rewardEmoji:"👟",rewardName:"Bottes de Sept Lieues"},{id:"jack-beanstalk",coverImage:null,title:"Jack et le Haricot Magique",summary:"Jack echange sa vache contre des haricots magiques et decouvre un chateau dans les nuages.",theme:"aventure et curiosite",emoji:"🌱",palette:{primary:"#33691e",accent:"#c5e1a5",background:"#001000"},difficulty:"aventure",ageMin:5,ageMax:9,scenes:[{text:"Jack et sa mere etaient tres pauvres. Un jour, la mere envoya Jack vendre leur vieille vache au marche."},{text:"Sur la route, un vieux monsieur proposa a Jack des haricots magiques en echange de la vache. Jack accepta.",dialogue:{speaker:"Jack",line:"Des haricots magiques ! C'est une bonne affaire !"}},{text:"La mere de Jack fut tres en colere et jeta les haricots par la fenetre. Mais pendant la nuit, une enorme tige de haricot poussa jusqu'aux nuages."},{text:"Jack grimpa le long de la tige et decouvrit un immense chateau dans les nuages. Un geant terrible y vivait.",dialogue:{speaker:"Geant",line:"Fe, fi, fo, fum ! Je sens le sang d'un homme !"}},{text:"La femme du geant aida Jack a se cacher. Jack profita que le geant dormait pour voler la poule aux oeufs d'or et la harpe enchantee."},{text:"Jack devala la tige en courant. Le geant le poursuivit. Jack saisit sa hache et coupa la tige. Le geant tomba loin, tres loin.",dialogue:{speaker:"Jack",line:"Maman ! Nous serons riches ! Plus jamais faim !"}}],vocabulary:[{word:"haricot",meaning:"une petite graine qui peut pousser tres haut",emoji:"🫘"},{word:"geant",meaning:"un etre imaginaire enormement grand et fort",emoji:"🦣"},{word:"nuages",meaning:"les grandes formes blanches ou grises dans le ciel",emoji:"☁️"},{word:"tresor",meaning:"des objets precieux comme de l'or ou des bijoux",emoji:"🪙"}],miniGame:{type:"choice",prompt:"Contre quoi Jack echange-t-il sa vache ?",options:["Des pieces d'or","Des haricots magiques","Une harpe"],answerIndex:1},emotionalMoment:{feeling:"curiosite",prompt:"As-tu deja decouvert quelque chose de surprenant ? Que ressentais-tu ?"},rewardEmoji:"🪙",rewardName:"Tresor du Geant"},{id:"thumbelina",coverImage:null,title:"Poucette",summary:"Poucette, une toute petite fille, cherche sa place dans un monde trop grand pour elle.",theme:"identite et appartenance",emoji:"🌸",palette:{primary:"#e91e63",accent:"#f8bbd0",background:"#1a0010"},difficulty:"doux",ageMin:4,ageMax:8,scenes:[{text:"Une femme qui souhaitait avoir un enfant planta une graine magique. Une fleur poussa et, a l'interieur, dormait une toute petite fille. Elle s'appelait Poucette."},{text:"Un soir, une vilaine grenouille enleva Poucette pour la marier a son fils. Poucette pleurait sur son nenuphare.",dialogue:{speaker:"Poucette",line:"Je ne veux pas rester ici. Je veux trouver ma vraie maison."}},{text:"Des poissons amicaux rongerent la tige du nenuphare et Poucette s'echappa. Elle voyagea a travers pres et forets, toujours trop petite pour les autres."},{text:"En hiver, Poucette trouva refugie chez une souris des champs. Mais la souris voulait la marier a une vieille taupe aveugle."},{text:"Poucette trouva une hirondelle blessee et la soigna toute l'hiver avec tendresse.",dialogue:{speaker:"Hirondelle",line:"Tu m'as sauvee. Quand le printemps reviendra, je t'emmenerai loin d'ici."}},{text:"Au printemps, l'hirondelle emporta Poucette vers un pays chaud et fleuri. La, elle rencontra un tout petit prince des fleurs. Elle avait enfin trouve sa place.",dialogue:{speaker:"Prince des fleurs",line:"Tu es la bienvenue ici. Veux-tu etre notre reine ?"}}],vocabulary:[{word:"minuscule",meaning:"extremement petit, beaucoup plus petit que tout le monde",emoji:"🔬"},{word:"kidnapper",meaning:"emmener quelqu'un de force sans sa permission",emoji:"😨"},{word:"hirondelle",meaning:"un petit oiseau rapide qui voyage vers les pays chauds",emoji:"🐦"},{word:"fee",meaning:"un etre magique avec des ailes, qui aide les autres",emoji:"🧚"}],miniGame:{type:"find",prompt:"Trouve la fleur ou dort Poucette !",target:"la grande fleur rose",decoys:["un nenuphar vert","une feuille seche","un champignon"]},emotionalMoment:{feeling:"appartenance",prompt:"As-tu deja eu l'impression de ne pas etre a ta place ? Comment tu as trouve ta place ?"},rewardEmoji:"🦋",rewardName:"Ailes de Fee"},{id:"twelve-dancing-princesses",coverImage:null,title:"Les Douze Princesses Danseuses",summary:"Chaque nuit, douze princesses secretement usent leurs souliers en dansant. Un soldat decouvre leur mystere.",theme:"mystere et perseverance",emoji:"👠",palette:{primary:"#6a1b9a",accent:"#e040fb",background:"#0d0017"},difficulty:"explorateur",ageMin:6,ageMax:10,scenes:[{text:"Un roi avait douze filles. Chaque matin, leurs souliers etaient troues comme si elles avaient danse toute la nuit. Mais personne ne savait pourquoi."},{text:"Le roi annonca que celui qui decouvrirait le secret epouserait une de ses filles. Des princes essayerent, mais tous s'endormaient mysterieusement.",dialogue:{speaker:"Roi",line:"Qui percera ce mystere ? Ses souliers sont troues encore !"}},{text:"Un vieux soldat revenant de la guerre rencontra une sage vieille femme qui lui donna une cape d'invisibilite.",dialogue:{speaker:"Vieille femme",line:"Ne bois pas le breuvage qu'on t'offrira. Et prends garde !"}},{text:"Le soldat fit semblant de dormir. A minuit, les princesses se leverent. Il les suivit, invisible, par un passage secret sous le sol."},{text:"Sous la terre, il decouvrit un lac avec des bateaux, une foret aux arbres d'argent et d'or, et un chateau illumine ou douze princes attendaient les princesses pour danser."},{text:"Le soldat cueillit secrettement une branche argentee pour prouver sa decouverte. La princesse ainee entendit un bruit.",dialogue:{speaker:"Princesse ainee",line:"Quelque chose ne va pas ce soir. J'ai peur."}},{text:"Le lendemain, le soldat presenta la branche au roi et raconta tout. Le roi reconnut la verite. Le soldat choisit d'epouser la princesse ainee et le mystere fut leve pour toujours.",dialogue:{speaker:"Soldat",line:"La verite vaut mieux que tous les secrets."}}],vocabulary:[{word:"mystere",meaning:"quelque chose de cache qu'on ne comprend pas encore",emoji:"🔍"},{word:"invisible",meaning:"qu'on ne peut pas voir, meme s'il est la",emoji:"👻"},{word:"soulier",meaning:"une chaussure elegante, souvent pour danser",emoji:"👠"},{word:"souterrain",meaning:"qui se trouve sous la terre, cache en dessous",emoji:"🕳️"}],miniGame:{type:"match",prompt:"Associe chaque princesse a son prince danseur !",pairs:[{left:"Princesse Rose",right:"Prince Dorian"},{left:"Princesse Lune",right:"Prince Silvain"},{left:"Princesse Etoile",right:"Prince Aurele"},{left:"Princesse Violette",right:"Prince Florian"}]},emotionalMoment:{feeling:"mystere",prompt:"As-tu un secret ? Comment ca fait de garder un secret ?"},rewardEmoji:"👑",rewardName:"Couronne du Mystere"},{id:"rumpelstiltskin",coverImage:null,title:"Rumpelstiltskin",summary:"Un petit homme mysterieux aide une jeune fille a filer de la paille en or — mais a quel prix ?",theme:"promesses et honnetete",emoji:"🧵",palette:{primary:"#f9a825",accent:"#ffe082",background:"#1a1000"},difficulty:"aventure",ageMin:5,ageMax:9,scenes:[{text:'Un meunier voulut impressionner le roi et dit un gros mensonge : "Ma fille peut filer de la paille en or !" Le roi enferma la jeune fille dans une tour remplie de paille.'},{text:"La fille pleurait quand un petit homme etrange apparut.",dialogue:{speaker:"Rumpelstiltskin",line:"Que donneras-tu si je file toute cette paille en or pour toi ?"}},{text:"Elle lui donna son collier. Le petit homme fila toute la paille en or. Le roi, emerveille, la mit dans une salle encore plus grande."},{text:"La troisieme nuit, la fille n'avait plus rien a donner. Elle promit son premier enfant. Le roi l'epousa et elle devint reine."},{text:"Un an plus tard, le petit homme revint reclamer l'enfant. La reine supplia. Il lui donna trois jours pour deviner son nom.",dialogue:{speaker:"Rumpelstiltskin",line:"Si tu trouves mon nom, tu garderas l'enfant !"}},{text:"Un messager entendit le petit homme danser en chantant son nom dans la foret. Il revint en courir l'annoncer a la reine.",dialogue:{speaker:"Messager",line:"Il s'appelle Rumpelstiltskin ! Je l'ai entendu chanter !"}}],vocabulary:[{word:"paille",meaning:"des tiges seches de cereales, jaunes et legeres",emoji:"🌾"},{word:"filer",meaning:"transformer des fibres en fil avec un rouet",emoji:"🧶"},{word:"promesse",meaning:"ce qu'on dit qu'on va faire et qu'on doit tenir",emoji:"🤝"},{word:"devinette",meaning:"une question avec une reponse cachee a trouver",emoji:"❓"}],miniGame:{type:"choice",prompt:"Comment la reine devine-t-elle le nom du lutin ?",options:["Un messager l'a entendu chanter dans la foret","Elle l'a lu dans un livre","Le lutin le lui a dit lui-meme"],answerIndex:0},emotionalMoment:{feeling:"honnetete",prompt:"Est-ce qu'il est important de tenir ses promesses ? Pourquoi ?"},rewardEmoji:"🥇",rewardName:"Fil d'Or"},{id:"emperor-new-clothes",coverImage:null,title:"Les Habits Neufs de l'Empereur",summary:"Deux escrocs font croire a un empereur vaniteux qu'ils lui font des habits invisibles pour les sots.",theme:"honnetete et courage",emoji:"👑",palette:{primary:"#1565c0",accent:"#90caf9",background:"#000d1a"},difficulty:"aventure",ageMin:5,ageMax:9,scenes:[{text:"Il etait une fois un empereur qui adorait les beaux habits par-dessus tout. Il changeait de tenue plusieurs fois par jour."},{text:"Deux escrocs se presenterent comme les meilleurs tisseurs du monde. Ils pretendirent tisser un tissu magique : invisible pour les sots et les incompetents.",dialogue:{speaker:"Escroc",line:"Seules les personnes vraiment intelligentes peuvent voir ces habits !"}},{text:"Les ministres furent envoyes voir l'avancement. Ils ne voyaient rien, mais n'osaient pas le dire de peur de paraitre stupides.",dialogue:{speaker:"Ministre",line:"C'est magnifique... absolument magnifique."}},{text:"Les escrocs remirent a l'Empereur ses habits neufs imaginaires. L'Empereur ne voyait rien non plus, mais il fit semblant."},{text:"L'Empereur defila dans les rues. Tout le monde applaudit, craignant de paraitre sot."},{text:"Soudain, un petit enfant cria la verite.",dialogue:{speaker:"Enfant",line:"Mais il n'a rien sur lui ! L'Empereur est tout nu !"}}],vocabulary:[{word:"vaniteux",meaning:"quelqu'un qui pense trop a son apparence et se croit beau",emoji:"🪞"},{word:"escroc",meaning:"quelqu'un qui ment pour voler ou tromper les autres",emoji:"🎭"},{word:"invisible",meaning:"qu'on ne peut pas voir de ses yeux",emoji:"👻"},{word:"verite",meaning:"ce qui est reellement vrai, meme si ca derange",emoji:"✅"}],miniGame:{type:"choice",prompt:"Qui dit la verite en premier ?",options:["Un petit enfant","Un ministre","L'Empereur lui-meme"],answerIndex:0},emotionalMoment:{feeling:"courage",prompt:"As-tu deja eu le courage de dire une verite difficile ?"},rewardEmoji:"🪡",rewardName:"Courage de la Verite"},{id:"steadfast-tin-soldier",coverImage:null,title:"Le Soldat de Plomb",summary:"Un brave petit soldat de plomb vit une grande aventure et prouve que le courage vient du coeur.",theme:"courage et fidelite",emoji:"🪖",palette:{primary:"#455a64",accent:"#90a4ae",background:"#060a0d"},difficulty:"aventure",ageMin:5,ageMax:9,scenes:[{text:"Parmi une boite de soldats de plomb, l'un d'eux n'avait qu'une seule jambe. Mais il se tenait droit et fier comme les autres."},{text:"Sur une etagere en face, une petite danseuse en papier levait une jambe. Le soldat crut qu'elle etait comme lui, et en tomba amoureux.",dialogue:{speaker:"Soldat",line:"Elle est si belle. Je voudrais rester pres d'elle pour toujours."}},{text:"Un diablotin jaloux dans une boite cria que le soldat ne devait pas regarder la danseuse. Le lendemain, le soldat tomba d'une fenetre."},{text:"Dans la rue, des enfants le trouverent et le mirent dans un bateau en papier. Il naviga dans le caniveau sous la pluie, puis fut avale par un gros poisson."},{text:"Le poisson fut peche et finit a la cuisine. La cuisiniere l'ouvrit et trouva le soldat de plomb intact, toujours droit.",dialogue:{speaker:"Cuisiniere",line:"Mais comment as-tu pu survivre a tout ca !"}},{text:"Le soldat fut rendu a l'enfant. Mais le diablotin jaloux poussa le soldat dans le feu. La petite danseuse tomba aussi par le vent. Il ne resta du soldat qu'un petit coeur de metal en forme de coeur, symbole de sa fidelite eternelle.",dialogue:{speaker:"Soldat",line:"Je suis reste vaillant jusqu'au bout."}}],vocabulary:[{word:"plomb",meaning:"un metal gris tres lourd, utilise pour faire des jouets autrefois",emoji:"⚙️"},{word:"vaillant",meaning:"courageux et fort face au danger",emoji:"🛡️"},{word:"torrent",meaning:"un courant d'eau fort et rapide",emoji:"🌊"},{word:"fidelite",meaning:"rester loyal a quelqu'un qu'on aime, quoi qu'il arrive",emoji:"💙"}],miniGame:{type:"choice",prompt:"De quoi le soldat de plomb tombe-t-il amoureux ?",options:["D'une petite danseuse en papier","D'une princesse au chateau","D'une fee magique"],answerIndex:0},emotionalMoment:{feeling:"fidelite",prompt:"As-tu quelqu'un ou quelque chose a qui tu es tres fidele ? Qu'est-ce que ca signifie pour toi ?"},rewardEmoji:"🎖️",rewardName:"Medaille du Courage"},{id:"musicians-of-bremen",coverImage:null,title:"Les musiciens de Breme",summary:"Un ane, un chien, un chat et un coq trop vieux pour travailler partent ensemble vers Breme et decouvrent que l'amitie et le courage valent mieux que la force.",theme:"amitie et courage",emoji:"🎺",palette:{primary:"#D97706",accent:"#FCD34D",background:"#FFFBEB"},difficulty:"doux",ageMin:4,ageMax:8,scenes:[{text:"Un vieux ane, trop fatigue pour travailler a la ferme, decidait de partir vers la grande ville de Breme pour devenir musicien."},{text:"En chemin il rencontra un chien, puis un chat, puis un coq — tous trop vieux pour leurs maitres. Ensemble ils marcherent.",dialogue:{speaker:"L'ane",line:"Venez avec moi ! A Breme, nous ferons de la belle musique ensemble !"}},{text:"La nuit tombee, ils trouverent une maison ou vivaient des brigands. Les quatre amis grimperent les uns sur les autres pres de la fenetre."},{text:"Ils se mirent a chanter tous en meme temps. Les brigands, terrifies par ce bruit etrange, s'enfuirent dans la foret.",dialogue:{speaker:"Coq",line:"Cocorico ! Notre musique est si belle qu'elle fait fuir les mechants !"}},{text:"Les quatre amis s'installerent dans la maison, si heureux ensemble qu'ils n'eurent jamais besoin d'aller a Breme."}],vocabulary:[{word:"musicien",meaning:"quelqu'un qui joue de la musique",emoji:"🎵"},{word:"brigand",meaning:"un voleur qui fait peur aux gens",emoji:"😈"},{word:"terrifier",meaning:"faire tres tres peur",emoji:"😱"},{word:"ensemble",meaning:"tous les uns avec les autres",emoji:"🤝"}],miniGame:{type:"count",prompt:"Combien d'animaux partent vers Breme ?",answer:4,options:[3,4,5]},emotionalMoment:{feeling:"amitie",prompt:"Les animaux etaient plus forts ensemble. Quand tes amis t'ont-ils aide a etre courageux ?"},rewardEmoji:"🎺",rewardName:"Trompette de Breme"},{id:"pied-piper",coverImage:e("7/7c/The_pied_piper_of_Hamelin2.jpg"),title:"Le Joueur de flute de Hamelin",summary:"Dans la ville de Hamelin envahie de rats, un joueur de flute magique promet de resoudre le probleme — et apprend que les promesses doivent toujours etre tenues.",theme:"honnetet et promesses",emoji:"🎶",palette:{primary:"#7C3AED",accent:"#C4B5FD",background:"#F5F3FF"},difficulty:"aventure",ageMin:5,ageMax:9,scenes:[{text:"La ville de Hamelin etait envahie de rats. Les habitants etaient desesperes et ne savaient que faire."},{text:"Un joueur de flute aux habits colores arriva et promit de chasser tous les rats pour une recompense.",dialogue:{speaker:"Joueur de flute",line:"Je peux chasser vos rats. Mais vous devez tenir votre promesse de me payer."}},{text:"Il joua une melodie magique. Tous les rats le suivirent jusqu'au bord de la riviere et disparurent."},{text:"Mais les habitants refuserent de le payer. Le joueur de flute joua une autre melodie — pour les enfants cette fois.",dialogue:{speaker:"Maire",line:"Nous ne te paierons pas. Va-t'en !"}},{text:"Les enfants suivirent la musique dans la montagne. Ce jour-la, toute la ville apprit que les promesses doivent etre tenues."}],vocabulary:[{word:"flute",meaning:"un instrument de musique qu'on souffle",emoji:"🎵"},{word:"melodie",meaning:"une suite de notes qui font une belle musique",emoji:"🎼"},{word:"promesse",meaning:"dire qu'on va faire quelque chose et le faire vraiment",emoji:"🤝"},{word:"recompense",meaning:"quelque chose qu'on donne en echange d'un service",emoji:"🏆"}],miniGame:{type:"choice",prompt:"Qu'est-ce qui arrive quand on ne tient pas sa promesse ?",options:["Rien du tout","On perd la confiance des autres","Les autres sont contents"],answerIndex:1},emotionalMoment:{feeling:"honnete",prompt:"As-tu deja tenu une promesse difficile ? Comment tu t'es senti apres ?"},rewardEmoji:"🎶",rewardName:"Flute magique"},{id:"little-match-girl",coverImage:e("f/f2/Edmund_Dulac_-_The_Little_Match_Girl.jpg"),title:"La Petite Fille aux allumettes",summary:"Par une nuit froide, une petite fille pauvre allume des allumettes qui lui montrent de beaux reves de chaleur et d'amour.",theme:"espoir et bonte",emoji:"🕯️",palette:{primary:"#F59E0B",accent:"#FDE68A",background:"#FFFBEB"},difficulty:"doux",ageMin:5,ageMax:9,scenes:[{text:"Le soir du Nouvel An, par un froid terrible, une petite fille marchait pieds nus dans la neige en vendant des allumettes."},{text:"Personne ne lui achetait rien. Elle se blottit dans un coin et alluma une allumette pour se rechauffer les doigts.",dialogue:{speaker:"Petite fille",line:"Juste une allumette pour avoir un peu chaud..."}},{text:"Dans la flamme elle vit un grand poele chaud, puis une belle table couverte de nourriture."},{text:"Elle alluma une autre allumette et vit son ancienne grand-mere, douce et aimante, qui lui souriait.",dialogue:{speaker:"Grand-mere",line:"Je suis la, ma cherie. Viens avec moi dans un endroit tout chaud."}},{text:"Le lendemain matin, les passants trouverent la petite fille endormie avec un sourire paisible. Elle avait vu de beaux reves de chaleur et d'amour."}],vocabulary:[{word:"allumette",meaning:"un petit baton qui fait du feu quand on le frotte",emoji:"🔥"},{word:"blottir",meaning:"se mettre en boule dans un coin pour avoir chaud",emoji:"🤗"},{word:"poele",meaning:"un appareil qui chauffe une piece",emoji:"🔥"},{word:"paisible",meaning:"calme et serein, sans peur",emoji:"😌"}],miniGame:{type:"choice",prompt:"Que voit la petite fille dans la flamme de sa premiere allumette ?",options:["Un grand poele chaud","Sa grand-mere","Un arbre de Noel"],answerIndex:0},emotionalMoment:{feeling:"espoir",prompt:"Meme dans les moments difficiles, la petite fille gardait espoir. Qu'est-ce qui te donne de l'espoir quand tout va mal ?"},rewardEmoji:"🕯️",rewardName:"Lumiere d'espoir"},{id:"princess-pea",coverImage:e("1/1a/Hans_Christian_Andersen_-_The_Real_Princess.jpg"),title:"La Princesse au petit pois",summary:"Une vraie princesse est reconnue grace a sa grande sensibilite — une fable amusante sur l'importance d'etre soi-meme.",theme:"etre soi-meme",emoji:"👸",palette:{primary:"#EC4899",accent:"#FBCFE8",background:"#FFF0F6"},difficulty:"doux",ageMin:4,ageMax:8,scenes:[{text:"Un prince cherchait une vraie princesse a epouser. Mais comment savoir si une princesse etait vraiment vraie ?"},{text:"Par une nuit de tempete, une jeune fille toute mouilee frappa a la porte du chateau et dit qu'elle etait une princesse.",dialogue:{speaker:"Jeune fille",line:"Je suis une vraie princesse, je vous l'assure !"}},{text:"La vieille reine eut une idee maligne. Elle posa un petit pois sous vingt matelas et vingt couvertures en duvet."},{text:"Le lendemain matin, on demanda a la jeune fille comment elle avait dormi.",dialogue:{speaker:"Jeune fille",line:"Oh, tres mal ! J'ai senti quelque chose de dur toute la nuit. Je suis toute couverte de bleus !"}},{text:"Seule une vraie princesse pouvait sentir un tout petit pois a travers tant de matelas. Le prince l'epousa et ils furent tres heureux."}],vocabulary:[{word:"princesse",meaning:"la fille d'un roi ou d'une reine",emoji:"👸"},{word:"matelas",meaning:"la partie douce du lit sur laquelle on dort",emoji:"🛏️"},{word:"sensible",meaning:"qui ressent les choses tres fort",emoji:"💝"},{word:"tempete",meaning:"un temps tres mauvais avec vent et pluie",emoji:"⛈️"}],miniGame:{type:"count",prompt:"Combien de matelas la reine a-t-elle empiles ?",answer:20,options:[10,15,20]},emotionalMoment:{feeling:"soi-meme",prompt:"La princesse etait reconnue pour ce qu'elle etait vraiment. Qu'est-ce qui te rend unique ?"},rewardEmoji:"👸",rewardName:"Couronne de sensibilite"},{id:"wild-swans",coverImage:null,title:"Les Cygnes Sauvages",summary:"Une courageuse princesse travaille en silence pendant des annees pour briser le sort qui a transforme ses onze freres en cygnes.",theme:"courage silencieux et amour",emoji:"🦢",palette:{primary:"#0EA5E9",accent:"#BAE6FD",background:"#F0F9FF"},difficulty:"aventure",ageMin:6,ageMax:10,scenes:[{text:"Elise avait onze freres que la mechante belle-mere avait transformes en cygnes sauvages grace a un sort terrible."},{text:"Une fee lui dit le secret : elle devait tricoter onze manteaux d'orties sans jamais prononcer un seul mot.",dialogue:{speaker:"Fee",line:"Tu dois travailler en silence. Un seul mot et tes freres resteront cygnes pour toujours."}},{text:"Elise tricotat sans s'arreter, meme quand ses mains saignaient, meme quand les gens la regardaient d'un mauvais oeil."},{text:"Des annees passerent. Enfin, dans un grand effort, elle jeta les manteaux sur les cygnes.",dialogue:{speaker:"Elise",line:"Mes freres ! Je vous ai attendus si longtemps !"}},{text:"Les cygnes redevinrent ses freres, grands et beaux. Elise put enfin parler et leur dire tout son amour."}],vocabulary:[{word:"sort",meaning:"une magie qui transforme quelqu'un",emoji:"✨"},{word:"ortie",meaning:"une plante aux feuilles qui piquent",emoji:"🌿"},{word:"tricoter",meaning:"faire des vetements avec des fils et des aiguilles",emoji:"🧶"},{word:"silence",meaning:"quand on ne dit pas un seul mot",emoji:"🤫"}],miniGame:{type:"count",prompt:"Combien de freres Elise doit-elle sauver ?",answer:11,options:[7,9,11]},emotionalMoment:{feeling:"determination",prompt:"Elise a travaille en silence pendant des annees pour aider ses freres. Qu'est-ce que tu ferais pour quelqu'un que tu aimes ?"},rewardEmoji:"🦢",rewardName:"Plume de cygne"},{id:"chevre-monsieur-seguin",coverImage:null,title:"La Chevre de Monsieur Seguin",summary:"La petite chevre Blanquette veut la liberte et s'enfuit dans la montagne, mais elle decouvre que la vraie liberte s'accompagne de responsabilite.",theme:"liberte et prudence",emoji:"🐐",palette:{primary:"#65A30D",accent:"#D9F99D",background:"#F7FEE7"},difficulty:"aventure",ageMin:5,ageMax:9,scenes:[{text:"Monsieur Seguin avait une belle petite chevre blanche qu'il appelait Blanquette. Mais Blanquette voulait la liberte de la montagne."},{text:"Monsieur Seguin la supplia de rester.",dialogue:{speaker:"M. Seguin",line:"Blanquette, reste ! Dans la montagne il y a un grand loup qui mange toutes les chevres !"}},{text:"Blanquette n'ecouta pas. Elle sauta par-dessus la clôture et s'elanca vers les pres de la montagne, tout heureuse."},{text:"Toute la journee elle gambada, mangea de belles herbes et respira l'air frais. Mais le soir, le grand loup arriva.",dialogue:{speaker:"Blanquette",line:"Je vais me battre jusqu'a l'aube ! Je ne capitulerai pas !"}},{text:"Blanquette se battit courageusement toute la nuit. Quand l'aube arriva, epuisee, elle avait appris que la liberte demande aussi de la prudence."}],vocabulary:[{word:"chevre",meaning:"un animal de ferme avec des cornes qui donne du lait",emoji:"🐐"},{word:"gambader",meaning:"sauter et courir librement comme par jeu",emoji:"🦘"},{word:"capitulier",meaning:"abandonner et admettre qu'on a perdu",emoji:"🏳️"},{word:"aube",meaning:"le premier moment du matin quand le soleil se leve",emoji:"🌅"}],miniGame:{type:"choice",prompt:"Pourquoi Monsieur Seguin veut-il garder Blanquette ?",options:["Pour avoir du lait","Pour la proteger du loup","Pour ne pas etre seul"],answerIndex:1},emotionalMoment:{feeling:"liberte et prudence",prompt:"Blanquette voulait etre libre mais n'etait pas prudente. Comment peut-on etre libre et en securite en meme temps ?"},rewardEmoji:"🐐",rewardName:"Clochette de montagne"},{id:"sinbad",coverImage:null,title:"Sinbad le Marin",summary:"Le courageux marin Sinbad voyage sur les mers du monde entier, affronte des monstres et des tempetes, et revient toujours plus sage qu'il n'etait parti.",theme:"courage et sagesse",emoji:"⛵",palette:{primary:"#0284C7",accent:"#7DD3FC",background:"#F0F9FF"},difficulty:"explorateur",ageMin:6,ageMax:10,scenes:[{text:"Sinbad etait un riche marchand de Bagdad qui adorait les aventures. Il avait fait sept grands voyages sur les mers du monde."},{text:"Lors de son premier voyage, son bateau s'echoua sur ce qu'il croyait etre une ile — mais c'etait un enorme poisson endormi !",dialogue:{speaker:"Sinbad",line:"Ce n'est pas une ile... c'est une creature vivante ! Fuyons !"}},{text:"A chaque voyage, Sinbad affrontait des perils nouveaux : un geant borgne, un roi des oiseaux, un serpent de mer. Il surmontait tout grace a son esprit."},{text:"Il rapportait toujours des tresors, mais surtout des histoires et de la sagesse.",dialogue:{speaker:"Sinbad",line:"Les vraies richesses ne sont pas les pierreries, mais ce qu'on apprend dans ses voyages."}},{text:"A Bagdad, les gens l'ecoutaient des heures entdentierement. Chaque voyage lui avait appris quelque chose de nouveau sur le monde et sur lui-meme."}],vocabulary:[{word:"marin",meaning:"quelqu'un qui voyage et travaille sur la mer",emoji:"⚓"},{word:"echouer",meaning:"quand un bateau s'arrete sur le fond ou sur une plage",emoji:"🏖️"},{word:"peril",meaning:"un grand danger",emoji:"⚠️"},{word:"sagesse",meaning:"la connaissance qu'on gagne avec l'experience",emoji:"🦉"}],miniGame:{type:"count",prompt:"Combien de grands voyages Sinbad a-t-il faits en tout ?",answer:7,options:[5,7,9]},emotionalMoment:{feeling:"aventure et sagesse",prompt:"Sinbad apprenait quelque chose a chaque voyage. Qu'est-ce que tu as appris lors d'un voyage ou d'une nouvelle experience ?"},rewardEmoji:"⛵",rewardName:"Boussole du voyageur"},{id:"tinder-box",coverImage:null,title:"Le Briquet magique",summary:"Un soldat trouve un briquet magique qui commande trois chiens enormes. Une histoire sur la generosit'e, la bonte et la valeur de l'amitie.",theme:"generosite et amitie",emoji:"🔦",palette:{primary:"#F59E0B",accent:"#FDE68A",background:"#FFFBEB"},difficulty:"aventure",ageMin:5,ageMax:9,scenes:[{text:"Un soldat revenait de la guerre quand une vieille sorciere lui proposa un marche : entrer dans un arbre creux et lui rapporter un briquet."},{text:"Dans l'arbre, le soldat trouva trois chiens enormes aux yeux comme des soucoupes, gardant des coffres pleins de pices d'or.",dialogue:{speaker:"Soldat",line:"Ces chiens sont enormes... mais tant que je tiens le briquet, ils obeissent !"}},{text:"Le soldat prit le briquet et beaucoup d'or. Il devint riche et genereux — il donnait a manger a tous les pauvres de la ville."},{text:"Un soir il alluma le briquet et les chiens apparurent. Ils accomplissaient tous ses voeux, mais il leur demandait toujours des choses gentilles.",dialogue:{speaker:"Soldat",line:"Allez, mes bons amis ! Apportez de la nourriture pour tout le village !"}},{text:"Grace a sa bonte, le soldat gagna l'amour de tous. Il apprit que la vraie magie, c'est un coeur genereux."}],vocabulary:[{word:"briquet",meaning:"un petit objet qui fait du feu",emoji:"🔥"},{word:"sorciere",meaning:"une personne qui fait de la magie, parfois mechamment",emoji:"🧙"},{word:"coffre",meaning:"une grande boite solide pour garder des tresors",emoji:"📦"},{word:"genereux",meaning:"qui aime donner et partager avec les autres",emoji:"🎁"}],miniGame:{type:"count",prompt:"Combien de chiens magiques gardent les tresors ?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"generosite",prompt:"Le soldat partageait sa richesse avec les pauvres. As-tu partage quelque chose que tu aimais ? Comment tu t'es senti ?"},rewardEmoji:"🔦",rewardName:"Briquet de bonte"},{id:"blue-bird",coverImage:null,title:"L'Oiseau Bleu",summary:"Deux enfants, Tyltyl et Mytyl, partent a la recherche de l'Oiseau Bleu du bonheur et decouvrent que le bonheur se trouve souvent tout pres de chez soi.",theme:"bonheur et gratitude",emoji:"🐦",palette:{primary:"#3B82F6",accent:"#BFDBFE",background:"#EFF6FF"},difficulty:"explorateur",ageMin:5,ageMax:9,scenes:[{text:"Tyltyl et Mytyl, deux enfants pauvres mais joyeux, vivaient avec leurs parents dans une petite maison au bord de la foret."},{text:"La fee Berylune leur apparut et leur demanda de trouver l'Oiseau Bleu du bonheur pour guerir sa petite-fille malade.",dialogue:{speaker:"Fee Berylune",line:"Partez chercher l'Oiseau Bleu ! Il est quelque part dans le monde."}},{text:"Les enfants voyagerent dans le Pays du Souvenir, le Palais de la Nuit et le Jardin des Bonheurs Futurs. Partout ils cherchaient l'oiseau."},{text:"Partout les oiseaux bleus qu'ils trouvaient mouraient ou changeaient de couleur. Decourages, ils rentrerent chez eux.",dialogue:{speaker:"Tyltyl",line:"Nous avons cherche partout... l'Oiseau Bleu n'existe peut-etre pas ?"}},{text:"De retour a la maison, Tyltyl remarqua que son pigeon — qu'il avait depuis toujours — avait des plumes d'un bleu magnifique. Le bonheur etait la, tout pres."}],vocabulary:[{word:"bonheur",meaning:"un sentiment de joie et de satisfaction profonde",emoji:"😊"},{word:"guerir",meaning:"aller mieux apres avoir ete malade",emoji:"💊"},{word:"souvenir",meaning:"une image ou un sentiment qu'on garde dans sa memoire",emoji:"💭"},{word:"gratitude",meaning:"etre reconnaissant et content de ce qu'on a",emoji:"🙏"}],miniGame:{type:"choice",prompt:"Ou Tyltyl trouve-t-il finalement l'Oiseau Bleu ?",options:["Dans un chateau lointain","Dans sa propre maison","Au fond de la mer"],answerIndex:1},emotionalMoment:{feeling:"gratitude",prompt:"Le bonheur etait tout pres de chez eux depuis le debut. Quelles belles choses as-tu deja qui te rendent heureux ?"},rewardEmoji:"🐦",rewardName:"Plume de bonheur"},{id:"renart-goupil",coverImage:null,title:"Renart le Goupil",summary:"Le rusé renard Renart utilise son intelligence pour se sortir de toutes les situations — une serie de fables medievales sur la ruse et ses limites.",theme:"intelligence et humilite",emoji:"🦊",palette:{primary:"#DC2626",accent:"#FCA5A5",background:"#FFF5F5"},difficulty:"aventure",ageMin:6,ageMax:10,scenes:[{text:"Au Moyen Age, dans la grande foret, vivait Renart le Goupil, le renard le plus ruse de tous les animaux."},{text:"Un jour, Renart vola un beau poulet a Chantecler le coq. Mais Chantecler avait un plan.",dialogue:{speaker:"Chantecler",line:"Renart, tu es si beau ! Montre-moi comment tu chantes quand tu es fier !"}},{text:"Renart, flatte, ouvrit la gueule pour chanter — et le poulet s'echappa. La ruse avait ete retournee contre lui !"},{text:"Renart essaya de voler le fromage d'Ysengrin le loup. Cette fois, c'est le loup qui le battit de vitesse.",dialogue:{speaker:"Ysengrin",line:"Tu n'es pas le seul a pouvoir etre ruse, Renart !"}},{text:"Renart apprit que meme le renard le plus ruse peut etre attrape. Il vaut mieux parfois etre honnete plutot que tricher."}],vocabulary:[{word:"goupil",meaning:"l'ancien mot francais pour renard",emoji:"🦊"},{word:"ruse",meaning:"tres habile pour tromper les autres par des astuces",emoji:"🎭"},{word:"flatter",meaning:"dire trop de compliments pour obtenir quelque chose",emoji:"😏"},{word:"honnete",meaning:"qui dit la verite et ne triche pas",emoji:"✅"}],miniGame:{type:"choice",prompt:"Comment Chantecler recupere-t-il son poulet ?",options:["En courant plus vite","En flattant Renart pour qu'il ouvre la gueule","En appelant d'autres animaux"],answerIndex:1},emotionalMoment:{feeling:"humilite",prompt:"Renart pensait etre le plus ruse mais il s'est fait avoir. As-tu deja appris quelque chose d'important en te trompant ?"},rewardEmoji:"🦊",rewardName:"Queue de Renart"},{id:"la-fontaine-crow-fox",coverImage:null,title:"Le Corbeau et le Renard",summary:"Un renard tres ruse flatte un corbeau pour lui voler son fromage. Une fable sur la vanite.",theme:"ruse et humilite",emoji:"🦊",palette:{primary:"#4a148c",accent:"#ce93d8",background:"#0d0014"},difficulty:"doux",ageMin:4,ageMax:8,scenes:[{text:"Un corbeau etait perche sur une branche, tenant dans son bec un beau morceau de fromage bien parfume."},{text:"Un renard tres ruse passa par la et sentit le fromage. Il decida de le lui voler par la flatterie.",dialogue:{speaker:"Renard",line:"Oh Monsieur le Corbeau, que vous etes beau ! Que votre plumage est magnifique !"}},{text:"Le corbeau, tout fier des compliments, gonflait ses plumes de plaisir. Le renard continua.",dialogue:{speaker:"Renard",line:"Si votre voix est aussi belle que vos plumes, vous etes le roi des oiseaux !"}},{text:"Le corbeau, trop flatte, ouvrit grand le bec pour chanter. Le fromage tomba."},{text:"Le renard attrapa le fromage en riant et dit la morale de la fable.",dialogue:{speaker:"Renard",line:"Tout flatteur vit aux depens de celui qui l'ecoute. Cette lecon vaut bien un fromage !"}}],vocabulary:[{word:"corbeau",meaning:"un grand oiseau noir avec un fort bec courbe",emoji:"🐦‍⬛"},{word:"flatteur",meaning:"quelqu'un qui dit trop de compliments pour obtenir quelque chose",emoji:"😏"},{word:"fromage",meaning:"un aliment fait avec du lait, souvent jaune ou blanc",emoji:"🧀"},{word:"morale",meaning:"la lecon qu'on apprend a la fin d'une fable",emoji:"📜"}],miniGame:{type:"choice",prompt:"Comment le renard obtient-il le fromage ?",options:["En flattant le corbeau pour qu'il ouvre le bec","En grimpant a l'arbre","En demandant poliment"],answerIndex:0},emotionalMoment:{feeling:"humilite",prompt:"As-tu deja ete flatte et fait quelque chose de stupide ? Qu'as-tu appris ?"},rewardEmoji:"📜",rewardName:"Sagesse de la Fable"}];function i(a){return o.find(n=>n.id===a)||null}const t={"snow-white":{title:"Sneeuwwitje",summary:"Een lief prinsesje met een huid zo wit als sneeuw vindt een thuis bij zeven vriendelijke kleine helpers en leert dat echte vrienden voor elkaar zorgen.",theme:"vriendelijkheid en vriendschap",scenes:[{text:"Lang geleden werd er een prinsesje geboren met een huid zo wit als sneeuw. Iedereen noemde haar Sneeuwwitje."},{text:"Een jaloerse koningin bezat een magische spiegel en stelde hem elke dag dezelfde vraag.",dialogue:{speaker:"Koningin",line:"Spiegel, spiegel, wie is de liefste en de mooiste van allemaal?"}},{text:"Sneeuwwitje liep diep het bos in. Zeven kleine, vriendelijke mijnwerkers verwelkomden haar in hun gezellige huisje.",dialogue:{speaker:"Een mijnwerker",line:"Je bent hier veilig, kleine vriendin. Kom uitrusten."}},{text:"De koningin bedroog haar met een glanzende appel, en Sneeuwwitje viel in een heel, heel diepe slaap."},{text:"Een zorgzame vriendin wekte haar heel zachtjes. Sneeuwwitje glimlachte, en iedereen vierde haar dappere vriendin.",dialogue:{speaker:"Sneeuwwitje",line:"Jullie hebben me nooit verlaten. Dank jullie wel, vrienden!"}}],vocabulary:[{word:"de mooiste",meaning:"de liefste en de knapste persoon",emoji:"🌷"},{word:"jaloers",meaning:"boos omdat je wil wat een ander heeft",emoji:"😠"},{word:"huisje",meaning:"een klein, knus huisje",emoji:"🏡"},{word:"verwelkomen",meaning:"iemand blij maken dat hij er is",emoji:"🤗"}],miniGame:{type:"count",prompt:"Hoeveel vriendelijke kleine mijnwerkers verwelkomden Sneeuwwitje?",answer:7,options:[6,7,8]},emotionalMoment:{feeling:"omringd en beschermd",prompt:"De vrienden van Sneeuwwitje pasten op haar. Wie past er op jou?"},rewardName:"Vriendelijke spiegel"},cinderella:{title:"Assepoester",summary:"Een hardwerkend meisje met een groot hart krijgt wat hulp van een magische vriendin en ontdekt dat vriendelijk zijn zelf een soort magie is.",theme:"hoop en vriendelijkheid",scenes:[{text:"Assepoester deed alle klusjes en verloor nooit haar lieve glimlach, ook niet als anderen gemeen waren."},{text:"Op een avond werd er een groot bal aangekondigd, maar Assepoester had niets om aan te trekken.",dialogue:{speaker:"Assepoester",line:"Was ik maar een keertje mee kunnen dansen."}},{text:"Een vriendelijke fee verscheen en veranderde met een zwaai van haar toverstaf een pompoen in een koets.",dialogue:{speaker:"Vriendin-fee",line:"Wees terug voor middernacht, lieverd — dan stopt de magie."}},{text:"Op het bal danste en lachte Assepoester. Maar toen de klok begon te slaan, moest ze rennen."},{text:"Het muiltje paste haar precies. Haar vriendelijkheid was altijd zichtbaar geweest, en vreugde vulde haar dagen.",dialogue:{speaker:"Assepoester",line:"Vriendelijk zijn kost niets."}}],vocabulary:[{word:"klusjes",meaning:"kleine taakjes om thuis te helpen",emoji:"🧹"},{word:"koets",meaning:"een wagen die getrokken wordt om mensen te vervoeren",emoji:"🛞"},{word:"middernacht",meaning:"twaalf uur s nachts",emoji:"🕛"},{word:"lief",meaning:"teder, rustig en vriendelijk",emoji:"🕊️"}],miniGame:{type:"count",prompt:"Hoe laat moet Assepoester terug zijn? Tel de slagen van de klok!",answer:12,options:[10,11,12]},emotionalMoment:{feeling:"vol hoop",prompt:"Zelfs op moeilijke dagen bleef Assepoester vriendelijk. Wat helpt jou om hoopvol te blijven?"},rewardName:"Glazen muiltje"},"little-red-riding-hood":{title:"Roodkapje",summary:"Een dapper meisje met een rood kapje gaat naar haar oma en leert onderweg naar haar wijze gevoel te luisteren.",theme:"luisteren en veilig blijven",scenes:[{text:"Een klein meisje droeg overal een felrood kapje; daarom noemde iedereen haar Roodkapje."},{text:"Haar mama gaf haar een mand met brood voor oma.",dialogue:{speaker:"Mama",line:"Blijf op het pad en alles komt goed."}},{text:"In het bos stelde een slimme wolf veel vragen. Roodkapje voelde dat er iets vreemds was en liep gewoon door.",dialogue:{speaker:"Roodkapje",line:"Ik hoef jou geen antwoord te geven. Ik zeg het aan een volwassene."}},{text:"Een vriendelijke houthakker hoorde haar en liep met haar mee. Samen kwamen ze bij oma aan."},{text:"Oma was veilig, en Roodkapje ook. Ze deelden lekker warm brood en lachten de hele middag.",dialogue:{speaker:"Oma",line:"Je hebt naar je verstandige gevoel geluisterd. Ik ben trots op jou."}}],vocabulary:[{word:"pad",meaning:"een weg die laat zien waar je veilig kunt lopen",emoji:"🛤️"},{word:"mand",meaning:"een drager met een hengsel om dingen in te vervoeren",emoji:"🧺"},{word:"slim",meaning:"iemand die trucjes gebruikt om je te bedriegen",emoji:"🦊"},{word:"houthakker",meaning:"iemand die tussen de bomen werkt",emoji:"🪓"}],miniGame:{type:"choice",prompt:"Een vreemde vraagt Roodkapje waar ze naartoe gaat. Wat is de veilige keuze?",options:["Alles vertellen","Doorlopen en een volwassene waarschuwen","Hem volgen het bos in"],answerIndex:1},emotionalMoment:{feeling:"veilig",prompt:"Roodkapje luisterde naar haar rare gevoel. Wanneer hielp een gevoel jou veilig te blijven?"},rewardName:"Rood kapje"},"hansel-and-gretel":{title:"Hans en Grietje",summary:"Een broer en zus raken verdwaald in het bos en gebruiken een slim plan en teamwork om veilig thuis te komen.",theme:"slimheid en samen blijven",scenes:[{text:"Hans en Grietje liepen het grote bos in, hand in hand om niet te verdwalen."},{text:"De slimme Hans liet kleine, glanzende witte steentjes vallen, een voor een, om de weg terug te markeren.",dialogue:{speaker:"Hans",line:"Deze steentjes zullen schitteren en ons naar huis brengen."}},{text:"Ze vonden een klein huisje van snoep, maar een slimme oude vrouw woonde er."},{text:"De kinderen waren te slim om zich te laten bedriegen. Ze pakten elkaars hand en sloopen naar buiten.",dialogue:{speaker:"Grietje",line:"Snel — samen zijn we moediger dan alleen."}},{text:"De glanzende steentjes glinsterden in het maanlicht en brachten hen recht naar huis, naar een warme knuffel."}],vocabulary:[{word:"steentjes",meaning:"kleine, gladde kiezels",emoji:"🪨"},{word:"slim",meaning:"goed in het bedenken van slimme ideeen",emoji:"💡"},{word:"op je tenen",meaning:"heel zachtjes lopen op je tenen",emoji:"🦶"},{word:"samen",meaning:"met elkaar, zij aan zij",emoji:"🤝"}],miniGame:{type:"sequence",prompt:"Zet het slimme plan van Hans in de goede volgorde!",steps:["De glanzende steentjes laten vallen","Het schitterende spoor volgen","De weg naar huis terugvinden"]},emotionalMoment:{feeling:"samen dapper",prompt:"De kinderen waren moediger als team. Wie maakt jou moediger?"},rewardName:"Glanzend steentje"},rapunzel:{title:"Rapunzel",summary:"Een lief meisje met heel lang haar woont in een hoge toren en leert dat geduld en een hart vol hoop elke deur kunnen openen.",theme:"geduld en hoop",scenes:[{text:"Helemaal bovenin een hoge toren woonde Rapunzel, een meisje met de langste gouden vlecht ter wereld."},{text:"Elke dag zong Rapunzel voor de vogels. Haar zachte lied zweefde door het hele bos.",dialogue:{speaker:"Rapunzel",line:"Op een dag zal ik de wereld daarbineden zien, onder de bomen."}},{text:'Een vriendelijke reiziger hoorde haar lied en riep: "Jouw muziek laat het bos glimlachen!"',dialogue:{speaker:"Reiziger",line:"Jouw muziek laat het hele bos glimlachen!"}},{text:"Ze werden vrienden. Dag na dag bedachten ze geduldig een slimme manier om naar beneden te komen."},{text:"Eindelijk zette Rapunzel haar voet op het zachte gras en draaide rond in de zon, vrij en blij.",dialogue:{speaker:"Rapunzel",line:"Wachten was moeilijk, maar hoop hield me sterk."}}],vocabulary:[{word:"toren",meaning:"een heel hoog en smal gebouw",emoji:"🗼"},{word:"vlecht",meaning:"haar dat gevlochten is tot een lange touwachtige streng",emoji:"💇"},{word:"geduld",meaning:"rustig wachten zonder op te geven",emoji:"⏳"},{word:"weide",meaning:"een veld met gras vol bloemen",emoji:"🌼"}],miniGame:{type:"find",prompt:"Zoek wat Rapunzel gebruikte om veilig naar beneden te komen.",target:"de gouden gevlochten ladder",decoys:["een papieren vlieger","een houten lepel","een klein kopje"]},emotionalMoment:{feeling:"geduldig",prompt:"Rapunzel wachtte met hoop. Op welk mooi ding heb jij lang gewacht?"},rewardName:"Gouden vlecht"},"the-ugly-duckling":{title:"Het Lelijke Eendje",summary:"Een klein vogeltje dat zich anders voelt dan de anderen groeit op en ontdekt dat het al die tijd prachtig was, precies zoals het was.",theme:"erbij horen en van jezelf houden",scenes:[{text:"In een zonnige vijver leek een klein vogeltje niet op zijn broers en zussen."},{text:"De andere vogels lachten hem uit, en diep vanbinnen voelde hij zich eenzaam en heel verdrietig.",dialogue:{speaker:"Klein vogeltje",line:"Ik wou dat iemand mij ook liet meedoen."}},{text:'Een vriendelijke kikker sprong dichterbij en ging naast hem zitten. "Jij bent bij mij welkom", zei ze.',dialogue:{speaker:"Kikker",line:"Jij bent bij mij welkom, mijn vriend."}},{text:"De seizoenen gingen voorbij. Op een heldere ochtend zag het kleine vogeltje zijn gezicht in het stille water."},{text:"Het was een prachtige zwaan geworden! Het was altijd al bijzonder geweest: gewoon zichzelf.",dialogue:{speaker:"Zwaan",line:"Ik hoefde niet te veranderen. Ik moest alleen groeien."}}],vocabulary:[{word:"vijver",meaning:"een kleine plas rustig water",emoji:"💧"},{word:"eenzaam",meaning:"verdrietig omdat je je helemaal alleen voelt",emoji:"🥺"},{word:"spiegeling",meaning:"het beeld dat je ziet in stil water",emoji:"🪞"},{word:"zwaan",meaning:"een grote, witte, sierlijke watervogel",emoji:"🦢"}],miniGame:{type:"choice",prompt:"Een nieuwe vriend voelt zich buitengesloten. Wat is iets liefs om te zeggen?",options:["Je hoort hier niet thuis","Je mag met ons meedoen!","Ga weg"],answerIndex:1},emotionalMoment:{feeling:"ik hoor erbij",prompt:"Het kleine vogeltje was bijzonder zoals het was. Wat maakt jou een geweldige jij?"},rewardName:"Zacht zwaan"},"the-little-mermaid":{title:"De Kleine Zeemeermin",summary:"Een nieuwsgierige jonge zeemeermin heeft de moed om een nieuwe wereld te verkennen en leert dat een lief en grootmoedig hart meer straalt dan alles.",theme:"moed en een goed hart",scenes:[{text:"Diep onder de golven woonde een jonge zeemeermin, de kleinste van zes zusjes."},{text:"Ze hield ervan om naar de oppervlakte te zwemmen en de lichte wereld boven het water te bekijken.",dialogue:{speaker:"Zeemeermin",line:"De wereld daarboven zit vol dingen die ik wil leren!"}},{text:"Op een stormachtige nacht hielp ze met moed een zeeman veilig naar de kust."},{text:"Ze bleef niet om bedankt te worden. Iemand helpen vulde haar hart met warmte.",dialogue:{speaker:"Zeemeermin",line:"Ik hielp uit vriendelijkheid, niet voor een bedankje."}},{text:"Thuis vertelde ze haar dappere verhaal, en haar goede hart liet de hele zee stralen."}],vocabulary:[{word:"zeemeermin",meaning:"een denkbeeldig meisje van de zee, met een vissenstaart",emoji:"🧜"},{word:"golven",meaning:"water dat op en neer beweegt op de zee",emoji:"🌊"},{word:"moedig",meaning:"iets moeilijks doen ook al ben je bang",emoji:"💪"},{word:"grootmoedig",meaning:"blij om te geven en anderen te helpen",emoji:"💝"}],miniGame:{type:"count",prompt:"Hoeveel grote zusjes had de Kleine Zeemeermin?",answer:6,options:[5,6,7]},emotionalMoment:{feeling:"een groot hart",prompt:"De zeemeermin hielp puur uit vriendelijkheid. Wanneer hielp jij zonder dat iemand het vroeg?"},rewardName:"Zeeparel"},"the-snow-queen":{title:"De Sneeuwkoningin",summary:"Als het hart van haar beste vriend koud wordt, reist een trouw meisje genaamd Gerda ver door de sneeuw om hem met liefde te verwarmen.",theme:"trouwe vriendschap",scenes:[{text:"Gerda en Kai waren de beste vrienden en verbouwden samen rozen bij hun raam."},{text:"Een heel klein ijssplintje raakte het hart van Kai, en hij werd koud en afstandelijk.",dialogue:{speaker:"Gerda",line:"Wacht... waar ga je naartoe, Kai?"}},{text:"De dappere Gerda gaf niet op. Ze vertrok door de sneeuw om haar vriend te zoeken.",dialogue:{speaker:"Gerda",line:"Ik vind je terug, Kai. Vrienden geven niet op."}},{text:"Ze vond Kai in een ijspaleis, roerloos en koud als steen."},{text:"Gerda omhelsde hem en warme tranen stroomden. Het ijs smolt, en Kai glimlachte en herinnerde zich alles.",dialogue:{speaker:"Kai",line:"Je bent helemaal hierheen voor mij gekomen. Dank je, Gerda."}}],vocabulary:[{word:"rijp",meaning:"een dunne laag ijs die vormt als het heel erg koud is",emoji:"🌨️"},{word:"trouw",meaning:"er altijd zijn voor je vrienden",emoji:"🤲"},{word:"paleis",meaning:"een heel groot en prachtig huis",emoji:"🏰"},{word:"smelten",meaning:"van ijs naar water gaan door warmte",emoji:"💧"}],miniGame:{type:"choice",prompt:"Hoe liet Gerda het ijs in Kais hart smelten?",options:["Met een groot vuur","Met warme tranen en een knuffel","Met een hamer"],answerIndex:1},emotionalMoment:{feeling:"trouw",prompt:"Gerda gaf haar vriend nooit op. Hoe laat jij een vriend zien dat je om hem geeft?"},rewardName:"Warme roos"},"puss-in-boots":{title:"De Gelaarsde Kat",summary:"Een slimme kat met mooie laarzen gebruikt zijn vindingrijkheid en trouwe hart om zijn vriendelijke vriend te helpen het geluk te vinden.",theme:"slimheid en loyaliteit",scenes:[{text:"Een slimme kat trok mooie laarzen aan en een hoed met een veer, klaar voor het avontuur."},{text:"Zijn vriend was arm maar lief, dus de kat bedacht een slim plan om hem te helpen.",dialogue:{speaker:"De Kat",line:"Vertrouw me, mijn vriend. Er komt een slim idee!"}},{text:"De kat begroette de koning beleefd en bood cadeaus aan, waardoor iedereen glimlachte."},{text:"Met vindingrijkheid in plaats van trucjes hielp de kat zijn vriend een groot kasteel aan de rivier te winnen.",dialogue:{speaker:"De Kat",line:"Goede ideeen openen meer deuren dan hard gebrul."}},{text:"Zijn vriend was eindelijk gelukkig, en de kat kroelde op bij het vuur, de trouwste kat van allemaal."}],vocabulary:[{word:"slim",meaning:"goed in het bedenken van slimme ideeen",emoji:"🧠"},{word:"laarzen",meaning:"schoenen die hoog op de benen reiken",emoji:"🥾"},{word:"beleefd",meaning:"vriendelijk en zacht met je woorden",emoji:"🙏"},{word:"trouw",meaning:"er altijd zijn voor je vrienden",emoji:"🤝"}],miniGame:{type:"sequence",prompt:"Zet het slimme plan van de Kat in de goede volgorde!",steps:["De mooie laarzen aantrekken","De koning beleefd begroeten","Zijn vriend helpen de dag te winnen"]},emotionalMoment:{feeling:"behulpzaam",prompt:"De Kat gebruikte slimme ideeen om een vriend te helpen. Op welke slimme manier heb jij al eens iemand geholpen?"},rewardName:"Mooie laarzen"},pinocchio:{title:"Pinokkio",summary:"Een houten poppetje dat droomt van een echt jongetje te zijn, leert dat de waarheid spreken is wat een goed hart doet groeien.",theme:"eerlijkheid",scenes:[{text:"Er was eens een klein houten poppetje dat Pinokkio heette en dat droomde van een echt jongetje te worden."},{text:"Elke keer als Pinokkio een leugen vertelde, groeide zijn neus uit als een tak.",dialogue:{speaker:"Pinokkio",line:"Dat was ik niet! Echt waar!"}},{text:"Zijn vriend het krekel probeerde hem te leren altijd de waarheid te vertellen.",dialogue:{speaker:"Krekel",line:"De waarheid vertellen maakt je licht als een veertje."}},{text:"Pinokkio maakte een grote fout en raakte verdwaald. Toen leerde hij dat eerlijkheid zijn enige gids was."},{text:"Toen Pinokkio eindelijk de waarheid zei, groeide zijn hart, en zijn liefste wens ging in vervulling.",dialogue:{speaker:"Pinokkio",line:"De waarheid is de krachtigste magie van allemaal."}}],vocabulary:[{word:"poppetje",meaning:"een pop die beweegt",emoji:"🎭"},{word:"waarheid",meaning:"precies vertellen wat er is gebeurd",emoji:"✅"},{word:"leugen",meaning:"iets zeggen dat niet waar is",emoji:"❌"},{word:"eerlijk",meaning:"iemand die altijd de waarheid zegt",emoji:"🌟"}],miniGame:{type:"choice",prompt:"Wanneer wordt de neus van Pinokkio langer?",options:["Als hij de waarheid zegt","Als hij een leugen vertelt","Als hij een liedje zingt"],answerIndex:1},emotionalMoment:{feeling:"eerlijk",prompt:"De waarheid zeggen maakte Pinokkio licht. Hoe voel jij je als je de waarheid vertelt?"},rewardName:"Krekel van de waarheid"},"peter-pan":{title:"Peter Pan",summary:"Een jongen die nooit opgroeit neemt nieuwe vrienden mee op een vliegavontuur waarbij blije gedachten en een beetje moed je overal brengen.",theme:"verbeelding en moed",scenes:[{text:"In een kamer vol sterren leerde een jongen genaamd Peter Pan de kinderen vliegen."},{text:"Peter vertelde Wendy het geheim: je moest aan iets heel gelukkigs denken.",dialogue:{speaker:"Peter Pan",line:"Denk aan je gelukkigste ding — en hop, je vliegt!"}},{text:"Samen vlogen ze naar Nooitgedachtland, een magisch eiland vol avonturen."},{text:"Zelfs tegenover de boze kapitein was Peter niet bang. Hij stond het gevaar met een grote glimlach te woord.",dialogue:{speaker:"Peter Pan",line:"Dapper zijn is toch proberen."}},{text:"De kinderen gingen naar huis met herinneringen in hun hart en een vleugje magie voor altijd."}],vocabulary:[{word:"slaapkamer",meaning:"de kamer waar je slaapt en droomt",emoji:"🛏️"},{word:"schaduw",meaning:"de donkere vorm die jouw lichaam op de grond maakt",emoji:"👤"},{word:"verbeelden",meaning:"mooie dingen bedenken in je hoofd",emoji:"💭"},{word:"moed",meaning:"toch proberen ook al ben je bang",emoji:"💪"}],miniGame:{type:"choice",prompt:"Wat hielp de kinderen vliegen?",options:["Blije gedachten en feestenstuif","Zware laarzen","Heel hard schreeuwen"],answerIndex:0},emotionalMoment:{feeling:"moedig",prompt:"Peter zegt dat dapper zijn toch proberen is. Wat moedigs zou jij graag willen proberen?"},rewardName:"Feenstof"},"alice-in-wonderland":{title:"Alice in Wonderland",summary:"Een nieuwsgierig meisje volgt een haastig konijn een ondersteboven wereld in en leert dat vragen stellen een soort magie is.",theme:"nieuwsgierigheid",scenes:[{text:"Alice zag een haastig wit konijn in een hol springen en volgde het uit pure nieuwsgierigheid."},{text:"Ze viel in een lange magische gang en vond een heel kleine deur naar een tuin.",dialogue:{speaker:"Alice",line:"Wat raar! Ik vraag me af wat hier aan de hand is."}},{text:"Alice dronk een klein flesje en werd kleiner, daarna at ze een koekje en werd heel snel groter.",dialogue:{speaker:"Alice",line:"Vragen zijn de sleutel tot alle wonderen!"}},{text:"Ze ontmoette een glimlachende kat, een boze koningin en een gekke hoedenmaker."},{text:"Alice werd wakker en glimlachte. Vragen stellen had haar naar de mooiste droom geleid.",dialogue:{speaker:"Alice",line:"Nieuwsgierigheid is het grootste avontuur."}}],vocabulary:[{word:"nieuwsgierig",meaning:"iemand die graag nieuwe dingen ontdekt",emoji:"🔍"},{word:"hol",meaning:"een tunnel gegraven in de grond door een dier",emoji:"🕳️"},{word:"krimpen",meaning:"kleiner worden",emoji:"🔻"},{word:"wonder",meaning:"iets ongelooflijks en heel verrassends",emoji:"😲"}],miniGame:{type:"sequence",prompt:"Zet het avontuur van Alice in de goede volgorde!",steps:["Het flesje drinken en krimpen","Het koekje eten en groeien","De kleine tuindeur vinden"]},emotionalMoment:{feeling:"nieuwsgierig",prompt:"Alice hield van vragen stellen. Waar ben jij vandaag nieuwsgierig naar?"},rewardName:"Nieuwsgierig klokje"},"the-wizard-of-oz":{title:"De Tovenaar van Oz",summary:"Een meisje en drie nieuwe vrienden volgen een gouden weg en ontdekken dat de gaven die ze zochten al die tijd al in henzelf zaten.",theme:"je hebt al wat je nodig hebt",scenes:[{text:"Een grote wervelwind nam Dorothee en haar kleine hond Toto mee naar het magische land Oz."},{text:"Op de gouden weg ontmoette Dorothee een vogelverschrikker, een man van blik en een leeuw.",dialogue:{speaker:"Vogelverschrikker",line:"Ik wil gewoon een slim brein!"}},{text:"Samen liepen ze naar de Smaragdstad om de grote Tovenaar te vinden.",dialogue:{speaker:"Dorothee",line:"Als we samen zijn, kunnen we alles."}},{text:"De Tovenaar onthulde hun een groot geheim: ze hadden al die tijd al alles wat ze begeerden."},{text:"Dorothee tikte drie keer met haar schoentjes en was weer thuis. Iedereen had zijn gave gevonden.",dialogue:{speaker:"Dorothee",line:"Er is geen plek zoals thuis."}}],vocabulary:[{word:"wervelwind",meaning:"een heel sterke wind die in het rond draait",emoji:"🌪️"},{word:"vogelverschrikker",meaning:"een grote stropen pop om vogels te verjagen",emoji:"🌾"},{word:"moed",meaning:"doorgaan ook al ben je bang",emoji:"💪"},{word:"reis",meaning:"een lange wandeling of avontuur naar een nieuwe plek",emoji:"🗺️"}],miniGame:{type:"choice",prompt:"Welke vriend had van het begin af aan al moed?",options:["De vogelverschrikker","De blikken man","De leeuw"],answerIndex:2},emotionalMoment:{feeling:"bekwaam",prompt:"De vrienden hadden hun gaven al in henzelf. Welke gave heb jij al in jezelf?"},rewardName:"Schitterende schoentjes"},"robin-hood":{title:"Robin Hood",summary:"Een vriendelijke boogschutter uit het groene bos deelt met mensen die weinig hebben en leert zijn vrienden dat rechtvaardigheid iedereen gelukkiger maakt.",theme:"rechtvaardigheid en vrijgevigheid",scenes:[{text:"In een groot groen bos woonde Robin Hood, de beste boogschutter van het land."},{text:"Hij zag dat veel mensen erg arm waren terwijl anderen alles hadden.",dialogue:{speaker:"Robin",line:"Delen is het mooiste cadeau."}},{text:"Samen met zijn vrolijke vrienden bedacht Robin een plan om mensen in nood te helpen.",dialogue:{speaker:"Kleine Jan",line:"Samen zijn we de kracht van het bos!"}},{text:"Robin deelde wat mensen nodig hadden, en overal verschenen glimlachen."},{text:"Het bos gonste van geluk. Robin had geleerd dat vrijgevigheid de echte overwinning is.",dialogue:{speaker:"Robin",line:"Vrijgevigheid maakt iedereen rijker."}}],vocabulary:[{word:"boogschutter",meaning:"iemand die pijlen schiet met een boog",emoji:"🎯"},{word:"bos",meaning:"een grote plek vol bomen en dieren",emoji:"🌳"},{word:"rechtvaardig",meaning:"iedereen op dezelfde manier behandelen",emoji:"⚖️"},{word:"vrijgevig",meaning:"graag geven en delen",emoji:"🎁"}],miniGame:{type:"choice",prompt:"Robin Hood deelde met mensen die...",options:["honger hadden en in nood waren","al heel rijk waren","gemeen waren voor anderen"],answerIndex:0},emotionalMoment:{feeling:"rechtvaardig",prompt:"Robin hield van delen. Wat zou jij kunnen delen om een vriend te laten glimlachen?"},rewardName:"Vriendschapsboog"},goldilocks:{title:"Goudlokje",summary:"Een nieuwsgierig meisje gaat het gezellige berenhuisje binnen en leert dat het beter is eerst te vragen en goed te zorgen voor andermans spullen.",theme:"respect voor anderen",scenes:[{text:"Een meisje met gouden krullen wandelde door het bos en vond een lief huisje."},{text:"Ze ging naar binnen en proefde drie kommetjes pap. Die van het kleine beertje was precies goed.",dialogue:{speaker:"Goudlokje",line:"Oh! Dit kommetje is perfect, niet te warm en niet te koud!"}},{text:"Ze probeerde drie stoelen, daarna drie bedden. Ze viel in slaap in het zachtste."},{text:"De drie beren kwamen terug en vonden hun huis overhoop.",dialogue:{speaker:"Klein beertje",line:"Iemand heeft uit mijn kommetje gegeten!"}},{text:"Goudlokje werd wakker, zei sorry en leerde dat eerst vragen de liefste beleefdheidsvorm is.",dialogue:{speaker:"Goudlokje",line:"Sorry. Ik zal altijd eerst vragen voor ik binnenkom."}}],vocabulary:[{word:"pap",meaning:"warm en zacht eten, zoals ontbijtgranen",emoji:"🥣"},{word:"huisje",meaning:"een klein, gezellig huisje in het bos",emoji:"🏡"},{word:"respect",meaning:"goed zorgen voor andermans spullen en gevoelens",emoji:"🙏"},{word:"sorry",meaning:"wat je zegt als je ergens spijt van hebt",emoji:"💙"}],miniGame:{type:"count",prompt:"Hoeveel beren woonden er in het gezellige huisje?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"respectvol",prompt:"Goudlokje leerde eerst te vragen. Wanneer is het vriendelijk om toestemming te vragen voor je iets leent?"},rewardName:"Perfect kommetje"},"three-little-pigs":{title:"De Drie Biggetjes",summary:"Drie kleine biggetjes bouwen drie verschillende huizen en leren dat zorgvuldig en ijverig werk iedereen veilig en warm houdt.",theme:"werk en organisatie",scenes:[{text:"Drie kleine biggetjes trokken de wereld in om hun huis te bouwen."},{text:"Het eerste biggetje bouwde snel een huis van stro. Het tweede een huis van hout.",dialogue:{speaker:"Eerste biggetje",line:"Snel klaar, goed gedaan! Ik wil gaan spelen!"}},{text:"Het derde biggetje werkte hard en bouwde steen voor steen een stevig huis van bakstenen.",dialogue:{speaker:"Derde biggetje",line:"Ik neem de tijd zodat mijn huis stevig is."}},{text:"De grote boze wolf blies op de huizen van stro en hout, en ze stortten in."},{text:"Maar het bakstenen huis bleef stevig staan. De drie biggetjes waren veilig, en iedereen leerde dat zorgvuldig werken beschermt.",dialogue:{speaker:"Derde biggetje",line:"Goed werk kost tijd, maar het is de moeite waard!"}}],vocabulary:[{word:"stro",meaning:"droge plantenstengels die makkelijk breken",emoji:"🌾"},{word:"bakstenen",meaning:"heel stevige gebakken aardblokken",emoji:"🧱"},{word:"stevig",meaning:"heel sterk, niet makkelijk te breken",emoji:"💪"},{word:"plannen",meaning:"nadenken voor je ergens mee begint",emoji:"📋"}],miniGame:{type:"count",prompt:"Hoeveel kleine biggetjes bouwden een huis?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"trots op mijn werk",prompt:"Het derde biggetje werkte hard en bleef veilig. Waar heb jij hard aan gewerkt?"},rewardName:"Stevige baksteen"},aladdin:{title:"Aladdin",summary:"Een gewoon maar lief jongetje vindt een magische lamp en leert dat wat je wenst minder telt dan het goede dat je voor anderen doet.",theme:"eerlijkheid en bescheidenheid",scenes:[{text:"Op een levendige markt woonde Aladdin, een arme jongen met een hart van goud."},{text:"Hij vond een oude lamp en toen hij eraan wreef, verscheen er een grote geest!",dialogue:{speaker:"Geest",line:"Ik geef je drie wensen. Kies zorgvuldig!"}},{text:"Aladdin wenste eerst zijn familie te helpen, dan de arme mensen in zijn wijk.",dialogue:{speaker:"Aladdin",line:"Ik wil dat niemand op deze markt honger heeft."}},{text:"Zijn bescheidenheid en vrijgevigheid bezorgden hem echte vrienden en veel geluk."},{text:"Aladdin leerde dat de beste wensen die zijn die je voor anderen doet.",dialogue:{speaker:"Aladdin",line:"Een vrijgevig hart is de grootste schat."}}],vocabulary:[{word:"markt",meaning:"een drukke plek waar mensen kopen en verkopen",emoji:"🏪"},{word:"lamp",meaning:"een voorwerp dat licht geeft of een geest bewaart",emoji:"🪔"},{word:"bescheiden",meaning:"iemand die niet opschept over zichzelf",emoji:"🙏"},{word:"wens",meaning:"iets waar je heel erg naar verlangt",emoji:"⭐"}],miniGame:{type:"count",prompt:"Hoeveel wensen gaf de geest aan Aladdin?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"vrijgevig",prompt:"Aladdin wenste om anderen te helpen. Als jij een lieve wens mocht doen, welke zou dat zijn?"},rewardName:"Wensenlamp"},"ali-baba":{title:"Ali Baba",summary:"Een vriendelijke houthakker ontdekt een geheime grot en leert dat eerlijk en voorzichtig zijn veel beter is dan hebzuchtig zijn.",theme:"eerlijkheid boven hebzucht",scenes:[{text:"Ali Baba was een vriendelijke houthakker die eenvoudig en tevreden leefde."},{text:"Op een dag in het bos hoorde hij rovers de magische woorden zeggen bij een grote rots.",dialogue:{speaker:"Rovers",line:"Sesam, open u!"}},{text:"Ali Baba liep de grot in en zag schitterende schatten in alle kleuren.",dialogue:{speaker:"Ali Baba",line:"Ik neem alleen wat we nodig hebben, niet meer."}},{text:"Zijn hebzuchtige broer nam te veel en werd verrast door de rovers. Ali Baba begreep de les."},{text:"Ali Baba deelde zijn goede fortuin met anderen en leefde eenvoudig en gelukkig.",dialogue:{speaker:"Ali Baba",line:"Genoeg hebben en eerlijk zijn, dat is de echte rijkdom."}}],vocabulary:[{word:"grot",meaning:"een grote, natuurlijke holte in de rots",emoji:"🕳️"},{word:"schat",meaning:"een grote hoeveelheid goud en kostbare dingen",emoji:"💎"},{word:"hebzuchtig",meaning:"iemand die altijd meer wil dan hij nodig heeft",emoji:"😤"},{word:"genoeg",meaning:"precies wat je nodig hebt, niet meer en niet minder",emoji:"✅"}],miniGame:{type:"choice",prompt:"Welke magische woorden openen de grot?",options:["Sesam, open u!","Doe de deur dicht!","Goedemorgen!"],answerIndex:0},emotionalMoment:{feeling:"tevreden",prompt:"Ali Baba nam alleen wat nodig was. Welk ding dat je al hebt, is precies genoeg voor jou?"},rewardName:"Geheime grot"},"aesops-fables":{title:"De Haas en de Schildpad",summary:"Een snelle haas en een langzame schildpad houden een vriendschappelijke race, en de schildpad laat iedereen zien dat nooit opgeven de dag wint.",theme:"doorzettingsvermogen — langzaam maar zeker",scenes:[{text:"In een zonnige weide schepte een snelle haas altijd op over zijn snelheid."},{text:"De langzame, rustige schildpad daagde hem uit. De haas accepteerde lachend.",dialogue:{speaker:"Haas",line:"Een race tegen jou? Makkelijk! Ik ga onderweg even rusten."}},{text:"De schildpad liep stap voor stap, gestaag, zonder ooit te stoppen.",dialogue:{speaker:"Schildpad",line:"Langzaam maar zeker kom ik vooruit."}},{text:"De haas viel in slaap onder een boom, zeker dat de schildpad hem nooit zou inhalen."},{text:"Toen de haas wakker werd, had de schildpad de finish al gehaald. Doorzetten wint altijd.",dialogue:{speaker:"Schildpad",line:"Stap voor stap kom je verder dan je denkt."}}],vocabulary:[{word:"haas",meaning:"een groot, wild konijn dat heel snel is",emoji:"🐇"},{word:"schildpad",meaning:"een dier met een schild dat langzaam maar zonder stoppen loopt",emoji:"🐢"},{word:"gestaag",meaning:"in hetzelfde tempo vooruitgaan zonder te stoppen",emoji:"⏱️"},{word:"doorzetten",meaning:"blijven proberen ook als het moeilijk is",emoji:"💪"}],miniGame:{type:"choice",prompt:"Wie won de race door nooit op te geven?",options:["de snelle haas","de langzame, gestadige schildpad","de slapende vos"],answerIndex:1},emotionalMoment:{feeling:"vastberaden",prompt:"De schildpad ging stap voor stap door. Waar blijf jij zelf mee doorgaan?"},rewardName:"Doorzettingsschildpad"},"sleeping-beauty":{title:"Doornroosje",summary:"Een mooie prinses valt in een magische slaap en wacht op de ware liefde.",theme:"geduld en hoop",scenes:[{text:"Een blije koning en koningin kregen eindelijk een dochtertje. Ze nodigden alle feeeen van het koninkrijk uit voor de doop."},{text:"De goede feeeen schonken de prinses gaven: schoonheid, gratie en zachtheid. Maar een boze fee arriveerde woedend.",dialogue:{speaker:"Boze fee",line:"Wanneer ze zestien wordt, prikt ze haar vinger aan een spoel en valt ze dood neer!"}},{text:"De laatste goede fee had nog niet gesproken. Ze verzachtte de vloek: de prinses zou niet sterven, maar honderd jaar slapen.",dialogue:{speaker:"Goede fee",line:"Ze slaapt, maar de liefde zal haar wakker maken."}},{text:"Op haar zestiende vond de prinses een oude vrouw die spon. Ze raakte de spoel aan en viel in een diepe slaap. Het hele kasteel sliep met haar mee."},{text:"Een prins hoorde over het slapende kasteel verborgen achter een rozenbos. Hij hakte door de dorens en betrad het stille kasteel.",dialogue:{speaker:"Prins",line:"Wat is ze mooi! Ik zal haar wakker kussen."}},{text:"De prins boog zich over de mooie prinses en gaf haar een zachte kus. Ze deed haar ogen open en glimlachte. Het hele kasteel ontwaakte, en ze leefden gelukkig.",dialogue:{speaker:"Prinses",line:"Ik heb zo lang gewacht. Eindelijk ben je er!"}}],vocabulary:[{word:"spoel",meaning:"een gereedschap om wol mee te spinnen, met een punt",emoji:"🧵"},{word:"kwaadaardig",meaning:"iemand die met slechte magie schade doet",emoji:"🧙"},{word:"betoverd",meaning:"veranderd door bijzondere magie",emoji:"✨"},{word:"rozenstruik",meaning:"een struik die mooie rozen laat groeien",emoji:"🌹"}],miniGame:{type:"choice",prompt:"Welke boze fee spreekt de vloek uit over de prinses?",options:["Een fee die niet was uitgenodigd","De kasteelfee","De bosfee"],answerIndex:0},emotionalMoment:{feeling:"hoop",prompt:"Heb je wel eens ongeduldig op iets gewacht? Hoe voelde dat?"},rewardName:"Betoverde Roos"},"beauty-and-the-beast":{title:"Belle en het Beest",summary:"Belle leert dat echte schoonheid in het hart zit, niet in het uiterlijk.",theme:"vriendelijkheid en echte liefde",scenes:[{text:"Een koopman verdwaalde in het bos tijdens een storm. Hij vond een groot mysterieus kasteel en schuilde er voor de nacht."},{text:"Bij het vertrek plukte hij een roos voor zijn dochter Belle. Een verschrikkelijk Beest dook plotseling op.",dialogue:{speaker:"Beest",line:"Je hebt mijn roos gestolen! Je bent mijn gevangene!"}},{text:"De koopman smeekte het Beest hem gedag te laten zeggen. Het Beest stemde in, op voorwaarde dat een van zijn dochters zijn plaats innam.",dialogue:{speaker:"Belle",line:"Papa, ik ga. Ik ben niet bang."}},{text:"Belle woonde in het kasteel. Het Beest was lelijk maar zacht en vriendelijk. Elke avond praatten en lachten ze samen."},{text:"Belle vroeg naar huis te mogen om haar zieke vader te bezoeken. Het Beest stemde verdrietig in.",dialogue:{speaker:"Beest",line:"Ik zal je missen, Belle. Maar jouw geluk gaat voor het mijne."}},{text:"Belle besefte ver van het kasteel dat ze van het Beest hield. Ze rende terug. Toen ze haar liefde bekende, veranderde het Beest in een knappe prins.",dialogue:{speaker:"Belle",line:"Ik hou van jou, niet om je gezicht, maar om je hart."}},{text:"De prins vertelde dat een heks hem had betoverd. Alleen oprechte liefde kon hem bevrijden. Belle en de prins leefden voor altijd gelukkig."}],vocabulary:[{word:"beest",meaning:"een groot eng dier, hier een betoverd monster",emoji:"🐾"},{word:"gevangene",meaning:"iemand die niet vrij kan vertrekken",emoji:"🔒"},{word:"uiterlijk",meaning:"wat je van buiten van iemand ziet",emoji:"👁️"},{word:"transformatie",meaning:"volledig van vorm of aanzien veranderen",emoji:"✨"}],miniGame:{type:"choice",prompt:"Waarom gaat Belles vader naar het kasteel?",options:["Hij zoekt een schat","Hij schuilt voor de storm en plukt een roos","Hij bezoekt het Beest"],answerIndex:1},emotionalMoment:{feeling:"vriendelijkheid",prompt:"Heb je wel eens iemand beoordeeld op zijn uiterlijk voor je hem kende?"},rewardName:"Magische Roos"},"little-thumb":{title:"Klein Duimpje",summary:"De kleinste van zeven broers gebruikt zijn slimheid om zijn familie te redden.",theme:"moed en intelligentie",scenes:[{text:"Een arme houtshakker en zijn vrouw hadden zeven zoons. De kleinste heette Klein Duimpje. Hij was minuscuul maar heel slim."},{text:"Op een avond lieten de ouders, te arm om de kinderen te voeden, hen achter in het bos.",dialogue:{speaker:"Klein Duimpje",line:"Ik wist dat ze dit zouden doen. Ik ben er klaar voor."}},{text:"Klein Duimpje had zich voorbereid: hij had zijn zakken gevuld met kleine witte kiezelstenen. Hij strooide ze langs het pad, en de kinderen vonden zo de weg naar huis terug."},{text:"De tweede keer verlaten had Klein Duimpje alleen brood om kruimels te strooien. De vogels aten ze op en de broers raakten voorgoed verdwaald."},{text:"Verdwaald kwamen ze aan bij het huis van een rees. De vrouw van de reus verstopte hen, maar de reus vond hen.",dialogue:{speaker:"Reus",line:"Ik ruik vers vlees! Waar zitten ze verstopt?"}},{text:"Klein Duimpje had een briljant idee: hij wisselde de mutsen van zijn broers met de kroontjes van de dochters van de reus. De reus vergiste zich in het donker."},{text:"Klein Duimpje stal de zevenmijlslaarzen van de slapende reus. In enkele stappen haalde hij goud op en redde zijn hele familie.",dialogue:{speaker:"Klein Duimpje",line:"Slimheid is beter dan kracht!"}}],vocabulary:[{word:"kiezelstenen",meaning:"kleine gladde steentjes die je langs een pad kunt strooien",emoji:"🪨"},{word:"reus",meaning:"een groot monster dat kinderen eet in sprookjes",emoji:"👹"},{word:"mijl",meaning:"een grote afstand, zoals meerdere kilometers",emoji:"🗺️"},{word:"list",meaning:"een slim idee om iemand te misleiden",emoji:"💡"}],miniGame:{type:"sequence",prompt:"Zet de stappen in de goede volgorde!",steps:["Witte kiezelstenen strooien om de weg terug te vinden","Aankomen bij het huis van de reus in het bos","De zevenmijlslaarzen stelen"]},emotionalMoment:{feeling:"moed",prompt:"Heb je wel eens bang geweest maar toch doorgegaan? Wat hielp je?"},rewardName:"Zevenmijlslaarzen"},"jack-beanstalk":{title:"Jaap en de Bonenstaak",summary:"Jaap ruilt zijn koe voor magische bonen en ontdekt een kasteel in de wolken.",theme:"avontuur en nieuwsgierigheid",scenes:[{text:"Jaap en zijn moeder waren erg arm. Op een dag stuurde zijn moeder Jaap om hun oude koe te verkopen op de markt."},{text:"Onderweg bood een oude man Jaap magische bonen aan in ruil voor de koe. Jaap accepteerde.",dialogue:{speaker:"Jaap",line:"Magische bonen! Dat is een goede ruil!"}},{text:"Jaaps moeder was erg boos en gooide de bonen uit het raam. Maar in de nacht groeide er een enorme bonenstaak tot aan de wolken."},{text:"Jaap klom langs de staak omhoog en ontdekte een reusachtig kasteel in de wolken. Een verschrikkelijke reus woonde er.",dialogue:{speaker:"Reus",line:"Fe, fi, fo, fum! Ik ruik het bloed van een mens!"}},{text:"De vrouw van de reus hielp Jaap zich te verstoppen. Jaap profiteerde ervan dat de reus sliep om de gouden hen en de betoverde harp te stelen."},{text:"Jaap gleed snel langs de staak naar beneden. De reus achtervolgde hem. Jaap greep zijn bijl en hakte de staak om. De reus viel ver, ver weg.",dialogue:{speaker:"Jaap",line:"Mama! We worden rijk! Nooit meer honger!"}}],vocabulary:[{word:"boon",meaning:"een klein zaadje dat heel hoog kan groeien",emoji:"🫘"},{word:"reus",meaning:"een denkbeeldig wezen dat enorm groot en sterk is",emoji:"🦣"},{word:"wolken",meaning:"de grote witte of grijze vormen in de lucht",emoji:"☁️"},{word:"schat",meaning:"waardevolle voorwerpen zoals goud of juwelen",emoji:"🪙"}],miniGame:{type:"choice",prompt:"Waartegen ruilt Jaap zijn koe?",options:["Gouden munten","Magische bonen","Een harp"],answerIndex:1},emotionalMoment:{feeling:"nieuwsgierigheid",prompt:"Heb je wel eens iets verrassends ontdekt? Hoe voelde dat?"},rewardName:"Schat van de Reus"},thumbelina:{title:"Duimelijntje",summary:"Duimelijntje, een heel klein meisje, zoekt haar plek in een wereld die te groot voor haar is.",theme:"identiteit en erbij horen",scenes:[{text:"Een vrouw die zo graag een kind wilde plantte een magisch zaad. Er groeide een bloem, en binnenin sliep een heel klein meisje. Ze heette Duimelijntje."},{text:"Op een avond ontvoerde een lelijke kikker Duimelijntje om haar met zijn zoon te laten trouwen. Duimelijntje huilde op haar waterlelie.",dialogue:{speaker:"Duimelijntje",line:"Ik wil hier niet blijven. Ik wil mijn echte thuis vinden."}},{text:"Vriendelijke vissen knabbelden de stengel van de waterlelie door en Duimelijntje ontsnapte. Ze reisde door velden en bossen, altijd te klein voor de anderen."},{text:"In de winter vond Duimelijntje onderdak bij een veldmuis. Maar de muis wilde haar laten trouwen met een oude blinde mol."},{text:"Duimelijntje vond een gewonde zwaluw en verzorgde haar de hele winter met tederheid.",dialogue:{speaker:"Zwaluw",line:"Je hebt me gered. Als de lente komt, breng ik je ver hiervandaan."}},{text:"In de lente droeg de zwaluw Duimelijntje naar een warm, bloeiend land. Daar ontmoette ze een heel kleine bloemenprinsen. Ze had eindelijk haar plek gevonden.",dialogue:{speaker:"Bloemenprins",line:"Je bent welkom hier. Wil jij onze koningin zijn?"}}],vocabulary:[{word:"minuscuul",meaning:"extreem klein, veel kleiner dan iedereen",emoji:"🔬"},{word:"ontvoeren",meaning:"iemand met geweld meenemen zonder toestemming",emoji:"😨"},{word:"zwaluw",meaning:"een kleine snelle vogel die naar warme landen trekt",emoji:"🐦"},{word:"fee",meaning:"een magisch wezen met vleugels dat anderen helpt",emoji:"🧚"}],miniGame:{type:"find",prompt:"Zoek de bloem waar Duimelijntje in slaapt!",target:"de grote roze bloem",decoys:["een groene waterlelie","een droog blad","een paddenstoel"]},emotionalMoment:{feeling:"erbij horen",prompt:"Heb je wel eens het gevoel gehad dat je niet op je plek was? Hoe heb je je plek gevonden?"},rewardName:"Feevleugels"},"twelve-dancing-princesses":{title:"De Twaalf Dansende Prinsessen",summary:"Elke nacht verslijten twaalf prinsessen stiekem hun schoenen op de dansvloer. Een soldaat ontdekt hun geheim.",theme:"mysterie en doorzettingsvermogen",scenes:[{text:"Een koning had twaalf dochters. Elke ochtend waren hun schoenen versleten alsof ze de hele nacht hadden gedanst. Maar niemand wist waarom."},{text:"De koning kondigde aan dat degene die het geheim ontdekte een van zijn dochters mocht huwen. Prinsen probeerden het, maar vielen allemaal op mysterieuze wijze in slaap.",dialogue:{speaker:"Koning",line:"Wie lost dit mysterie op? Hun schoenen zijn alweer versleten!"}},{text:"Een oude soldaat die terugkeerde van de oorlog ontmoette een wijze oude vrouw die hem een onzichtbare mantel gaf.",dialogue:{speaker:"Oude vrouw",line:"Drink niet van het drankje dat men je aanbiedt. En wees voorzichtig!"}},{text:"De soldaat deed alsof hij sliep. Om middernacht stonden de prinsessen op. Hij volgde hen onzichtbaar door een geheime doorgang onder de grond."},{text:"Onder de grond ontdekte hij een meer met boten, een bos met zilveren en gouden bomen, en een verlicht kasteel waar twaalf prinsen de prinsessen opwachtten om te dansen."},{text:"De soldaat plukte stiekem een zilveren tak als bewijs. De oudste prinses hoorde een geluid.",dialogue:{speaker:"Oudste prinses",line:"Er klopt vanavond iets niet. Ik ben bang."}},{text:"De volgende dag presenteerde de soldaat de tak aan de koning en vertelde alles. De koning erkende de waarheid. De soldaat koos om met de oudste prinses te trouwen en het geheim was voor altijd onthuld.",dialogue:{speaker:"Soldaat",line:"De waarheid is meer waard dan alle geheimen."}}],vocabulary:[{word:"mysterie",meaning:"iets verborgens dat je nog niet begrijpt",emoji:"🔍"},{word:"onzichtbaar",meaning:"wat je niet kunt zien, ook al is het er",emoji:"👻"},{word:"schoen",meaning:"een elegante schoen, vaak voor het dansen",emoji:"👠"},{word:"ondergronds",meaning:"wat zich onder de grond bevindt, verborgen eronder",emoji:"🕳️"}],miniGame:{type:"match",prompt:"Koppel elke prinses aan haar dansprins!",pairs:[{left:"Prinses Roos",right:"Prins Dorian"},{left:"Prinses Maan",right:"Prins Silvain"},{left:"Prinses Ster",right:"Prins Aurele"},{left:"Prinses Violet",right:"Prins Florian"}]},emotionalMoment:{feeling:"mysterie",prompt:"Heb jij een geheim? Hoe voelt het om een geheim te bewaren?"},rewardName:"Kroon van het Mysterie"},rumpelstiltskin:{title:"Repelsteeltje",summary:"Een mysterieus mannetje helpt een meisje stro in goud te spinnen — maar voor welke prijs?",theme:"beloften en eerlijkheid",scenes:[{text:'Een molenaar wilde de koning imponeren en vertelde een grote leugen: "Mijn dochter kan stro in goud spinnen!" De koning sloot het meisje op in een toren vol stro.'},{text:"Het meisje huilde toen een vreemd klein mannetje verscheen.",dialogue:{speaker:"Repelsteeltje",line:"Wat geef je me als ik al dit stro in goud spin voor jou?"}},{text:"Ze gaf hem haar ketting. Het kleine mannetje spon al het stro in goud. De koning, vol bewondering, bracht haar naar een nog grotere kamer."},{text:"De derde nacht had het meisje niets meer te geven. Ze beloofde haar eerste kind. De koning trouwde met haar en ze werd koningin."},{text:"Een jaar later kwam het kleine mannetje terug om het kind op te eisen. De koningin smeekte. Hij gaf haar drie dagen om zijn naam te raden.",dialogue:{speaker:"Repelsteeltje",line:"Als je mijn naam raadt, mag je het kind houden!"}},{text:"Een boodschapper hoorde het kleine mannetje dansen en zijn naam zingen in het bos. Hij rende terug om het de koningin te vertellen.",dialogue:{speaker:"Boodschapper",line:"Hij heet Repelsteeltje! Ik heb hem horen zingen!"}}],vocabulary:[{word:"stro",meaning:"droge grasstengels, geel en licht",emoji:"🌾"},{word:"spinnen",meaning:"vezels omzetten tot draad met een spinnenwiel",emoji:"🧶"},{word:"belofte",meaning:"wat je zegt dat je zult doen en moet nakomen",emoji:"🤝"},{word:"raadsel",meaning:"een vraag met een verborgen antwoord om te vinden",emoji:"❓"}],miniGame:{type:"choice",prompt:"Hoe raadt de koningin de naam van het kabouter?",options:["Een boodschapper hoorde hem zingen in het bos","Ze las het in een boek","De kabouter vertelde het haar zelf"],answerIndex:0},emotionalMoment:{feeling:"eerlijkheid",prompt:"Is het belangrijk om je beloften na te komen? Waarom?"},rewardName:"Gouden Draad"},"emperor-new-clothes":{title:"De Nieuwe Kleren van de Keizer",summary:"Twee oplichters overtuigen een ijdele keizer dat ze hem onzichtbare kleren maken voor dwazen.",theme:"eerlijkheid en moed",scenes:[{text:"Er was eens een keizer die meer van mooie kleren hield dan van wat ook. Hij wisselde meerdere keren per dag van kleding."},{text:"Twee oplichters presenteerden zich als de beste wevers ter wereld. Ze beweerden een magische stof te weven: onzichtbaar voor dwazen en onbekwamen.",dialogue:{speaker:"Oplichter",line:"Alleen echt intelligente mensen kunnen deze kleren zien!"}},{text:"De ministers werden gestuurd om de voortgang te bekijken. Ze zagen niets, maar durfden het niet te zeggen uit angst dom te lijken.",dialogue:{speaker:"Minister",line:"Het is prachtig... absoluut prachtig."}},{text:"De oplichters overhandigden de keizer zijn denkbeeldige nieuwe kleren. De keizer zag ook niets, maar deed alsof."},{text:"De keizer liep in optocht door de straten. Iedereen klapte, bang om dom te lijken."},{text:"Plotseling riep een klein kind de waarheid.",dialogue:{speaker:"Kind",line:"Maar hij heeft niets aan! De keizer is helemaal naakt!"}}],vocabulary:[{word:"ijdel",meaning:"iemand die te veel aan zijn uiterlijk denkt en zichzelf mooi vindt",emoji:"🪞"},{word:"oplichter",meaning:"iemand die liegt om te stelen of anderen te bedriegen",emoji:"🎭"},{word:"onzichtbaar",meaning:"wat je met je ogen niet kunt zien",emoji:"👻"},{word:"waarheid",meaning:"wat echt waar is, ook al is het lastig",emoji:"✅"}],miniGame:{type:"choice",prompt:"Wie zegt als eerste de waarheid?",options:["Een klein kind","Een minister","De keizer zelf"],answerIndex:0},emotionalMoment:{feeling:"moed",prompt:"Heb je wel eens de moed gehad om een moeilijke waarheid te zeggen?"},rewardName:"Moed van de Waarheid"},"steadfast-tin-soldier":{title:"De Standvastige Tinnen Soldaat",summary:"Een dappere kleine tinnen soldaat beleeft een groot avontuur en bewijst dat moed uit het hart komt.",theme:"moed en trouw",scenes:[{text:"Tussen een doos tinnen soldaten had er een maar een been. Maar hij stond recht en trots zoals de anderen."},{text:"Op een plank tegenover hem stond een klein papieren danseres die een been ophief. De soldaat dacht dat ze net als hij was, en werd verliefd op haar.",dialogue:{speaker:"Soldaat",line:"Ze is zo mooi. Ik wil altijd dicht bij haar blijven."}},{text:"Een jaloerse duiveltje in een doos riep dat de soldaat niet naar de danseres mocht kijken. De volgende dag viel de soldaat uit een raam."},{text:"Op straat vonden kinderen hem en stopten hem in een papieren bootje. Hij voer door de goot in de regen, en werd daarna door een grote vis ingeslikt."},{text:"De vis werd gevangen en belandde in de keuken. De kok sneed hem open en vond de tinnen soldaat ongedeerd, nog steeds rechtop.",dialogue:{speaker:"Kok",line:"Maar hoe heb je dit allemaal overleefd!"}},{text:"De soldaat werd teruggegeven aan het kind. Maar het jaloerse duiveltje gooide de soldaat in het vuur. De kleine danseres viel ook door de wind mee. Van de soldaat bleef alleen een klein metalen hartje over, symbool van zijn eeuwige trouw.",dialogue:{speaker:"Soldaat",line:"Ik bleef dapper tot het einde."}}],vocabulary:[{word:"tin",meaning:"een grijs zwaar metaal, vroeger gebruikt voor speelgoed",emoji:"⚙️"},{word:"dapper",meaning:"moedig en sterk tegenover gevaar",emoji:"🛡️"},{word:"stroom",meaning:"een krachtige, snelle waterstroom",emoji:"🌊"},{word:"trouw",meaning:"loyaal blijven aan iemand van wie je houdt, wat er ook gebeurt",emoji:"💙"}],miniGame:{type:"choice",prompt:"Op wie wordt de tinnen soldaat verliefd?",options:["Een klein papieren danseres","Een prinses in het kasteel","Een magische fee"],answerIndex:0},emotionalMoment:{feeling:"trouw",prompt:"Is er iemand of iets waaraan jij heel erg trouw bent? Wat betekent dat voor jou?"},rewardName:"Moed Medaille"},"la-fontaine-crow-fox":{title:"De Kraai en de Vos",summary:"Een heel slimme vos vleit een kraai om zijn kaas te stelen. Een fabel over ijdelheid.",theme:"slimheid en bescheidenheid",scenes:[{text:"Een kraai zat op een tak met een lekker stuk kaas in zijn bek."},{text:"Een heel slimme vos liep voorbij en rook de kaas. Hij besloot hem te stelen door te vleien.",dialogue:{speaker:"Vos",line:"O Mijnheer de Kraai, wat bent u mooi! Wat zijn uw veren prachtig!"}},{text:"De kraai, trots op de complimenten, blies zijn veren op van genoegen. De vos ging verder.",dialogue:{speaker:"Vos",line:"Als uw stem net zo mooi is als uw veren, bent u de koning der vogels!"}},{text:"De kraai, te gevleid, opende zijn bek wijd om te zingen. De kaas viel naar beneden."},{text:"De vos greep de kaas lachend en sprak de moraal van de fabel.",dialogue:{speaker:"Vos",line:"Elke vleier leeft ten koste van degene die naar hem luistert. Die les is een kaas waard!"}}],vocabulary:[{word:"kraai",meaning:"een grote zwarte vogel met een stevige gebogen snavel",emoji:"🐦‍⬛"},{word:"vleier",meaning:"iemand die te veel complimenten maakt om iets te krijgen",emoji:"😏"},{word:"kaas",meaning:"een gerecht gemaakt van melk, vaak geel of wit",emoji:"🧀"},{word:"moraal",meaning:"de les die je leert aan het einde van een fabel",emoji:"📜"}],miniGame:{type:"choice",prompt:"Hoe krijgt de vos de kaas?",options:["Door de kraai te vleien zodat hij zijn bek opent","Door in de boom te klimmen","Door vriendelijk te vragen"],answerIndex:0},emotionalMoment:{feeling:"bescheidenheid",prompt:"Ben je wel eens gevleid en iets doms gedaan? Wat heb je geleerd?"},rewardName:"Wijsheid van de Fabel"},"musicians-of-bremen":{title:"De stadsmuzikanten van Bremen",summary:"Een ezel, een hond, een kat en een haan trekken samen naar Bremen en ontdekken dat vriendschap sterker is dan kracht.",theme:"vriendschap en moed",scenes:[{text:"Een oude ezel besloot naar Bremen te gaan om muzikant te worden."},{text:"Onderweg ontmoette hij een hond, een kat en een haan. Ze liepen samen verder.",dialogue:{speaker:"Ezel",line:"Kom mee! In Bremen maken we samen mooie muziek!"}},{text:"Ze vonden een huis waar rovers woonden en klommen op elkaar voor het raam."},{text:"Ze zongen allemaal tegelijk. De rovers vluchtten doodsbang het bos in.",dialogue:{speaker:"Haan",line:"Onze muziek verjaagt de boeven!"}},{text:"De vier vrienden installeerden zich in het huis, zo gelukkig dat ze nooit naar Bremen hoefden."}],vocabulary:[{word:"muzikant",meaning:"iemand die muziek speelt",emoji:"🎵"},{word:"rover",meaning:"een dief",emoji:"😈"},{word:"samen",meaning:"met elkaar",emoji:"🤝"},{word:"doodsbang",meaning:"heel erg bang",emoji:"😱"}],miniGame:{type:"count",prompt:"Hoeveel dieren gaan naar Bremen?",answer:4,options:[3,4,5]},emotionalMoment:{feeling:"vriendschap",prompt:"Wanneer hielpen vrienden jou moedig te zijn?"},rewardName:"Trompet van Bremen"},"pied-piper":{title:"De rattenvanger van Hamelen",summary:"Een magische fluitspeler leert de stad Hamelen dat beloften altijd nagekomen moeten worden.",theme:"eerlijkheid en beloften",scenes:[{text:"De stad Hamelen was overspoeld met ratten."},{text:"Een kleurrijke fluitspeler beloofde alle ratten weg te jagen voor een beloning.",dialogue:{speaker:"Fluitspeler",line:"Ik kan uw ratten wegjagen, maar u moet uw belofte nakomen."}},{text:"Hij speelde een magische melodie. Alle ratten volgden hem naar de rivier."},{text:"De inwoners weigerden te betalen.",dialogue:{speaker:"Burgemeester",line:"We betalen je niet. Ga weg!"}},{text:"De kinderen volgden de muziek. Die dag leerde de stad dat beloften nagekomen moeten worden."}],vocabulary:[{word:"fluit",meaning:"een blaasinstrument",emoji:"🎵"},{word:"belofte",meaning:"zeggen dat je iets gaat doen en het doen",emoji:"🤝"},{word:"melodie",meaning:"een mooie rij noten",emoji:"🎼"},{word:"beloning",meaning:"iets dat je geeft voor een dienst",emoji:"🏆"}],miniGame:{type:"choice",prompt:"Wat gebeurt er als je je belofte niet nakomt?",options:["Niets","Je verliest het vertrouwen van anderen","Anderen zijn blij"],answerIndex:1},emotionalMoment:{feeling:"eerlijk",prompt:"Heb je ooit een moeilijke belofte gehouden? Hoe voelde dat?"},rewardName:"Magische fluit"},"little-match-girl":{title:"Het meisje met de lucifers",summary:"Op een koude nacht steekt een arm meisje lucifers aan die haar mooie dromen tonen.",theme:"hoop en vriendelijkheid",scenes:[{text:"Op oudejaarsavond liep een meisje blootsvoets in de sneeuw en verkocht lucifers."},{text:"Niemand kocht iets. Ze stak een lucifer aan om warm te worden.",dialogue:{speaker:"Meisje",line:"Gewoon een lucifertje voor warmte..."}},{text:"In de vlam zag ze een grote warme kachel, daarna een tafel vol eten."},{text:"Ze zag haar lieve oma, die vriendelijk glimlachte.",dialogue:{speaker:"Oma",line:"Ik ben er. Kom mee naar een warme plek."}},{text:"De volgende ochtend vonden voorbijgangers het meisje slapend met een vredig glimlachje."}],vocabulary:[{word:"lucifer",meaning:"een stokje dat vuur maakt",emoji:"🔥"},{word:"vredig",meaning:"kalm en zonder angst",emoji:"😌"},{word:"hoop",meaning:"geloven dat iets goeds kan happen",emoji:"🌟"},{word:"warmte",meaning:"een gevoel van hitte en geborgenheid",emoji:"🔥"}],miniGame:{type:"choice",prompt:"Wat ziet het meisje in de eerste vlam?",options:["Een warme kachel","Haar oma","Een kerstboom"],answerIndex:0},emotionalMoment:{feeling:"hoop",prompt:"Wat geeft jou hoop als het moeilijk is?"},rewardName:"Licht van hoop"},"princess-pea":{title:"De prinses op de erwt",summary:"Een echte prinses wordt herkend aan haar gevoeligheid.",theme:"jezelf zijn",scenes:[{text:"Een prins zocht een echte prinses. Maar hoe weet je of ze echt is?"},{text:"Op een stormige avond klopte een nat meisje aan en zei dat ze een prinses was.",dialogue:{speaker:"Meisje",line:"Ik ben een echte prinses, ik verzeker het!"}},{text:"De koningin legde een erwt onder twintig matrassen."},{text:"De volgende ochtend: hoe had ze geslapen?",dialogue:{speaker:"Meisje",line:"Heel slecht! Ik voelde iets hards de hele nacht!"}},{text:"Alleen een echte prinses kon de erwt voelen. De prins trouwde met haar."}],vocabulary:[{word:"prinses",meaning:"dochter van een koning",emoji:"👸"},{word:"matras",meaning:"het zachte deel van een bed",emoji:"🛏️"},{word:"gevoelig",meaning:"die dingen sterk aanvoelt",emoji:"💝"},{word:"storm",meaning:"slecht weer met wind en regen",emoji:"⛈️"}],miniGame:{type:"count",prompt:"Hoeveel matrassen stapelde de koningin?",answer:20,options:[10,15,20]},emotionalMoment:{feeling:"jezelf zijn",prompt:"Wat maakt jou uniek?"},rewardName:"Kroon van gevoeligheid"},"wild-swans":{title:"De wilde zwanen",summary:"Een moedige prinses werkt jarenlang in stilte om haar elf broers als zwanen te bevrijden.",theme:"stille moed en liefde",scenes:[{text:"Elisa had elf broers die in wilde zwanen waren veranderd door een betovering."},{text:"Ze moest elf brandnetelmantels breien zonder ooit een woord te spreken.",dialogue:{speaker:"Fee",line:"Een enkel woord en je broers blijven zwanen voor altijd."}},{text:"Elisa breidde zonder te stoppen, zelfs als haar handen bloedden."},{text:"Ten slotte wierp ze de mantels over de zwanen.",dialogue:{speaker:"Elisa",line:"Mijn broers! Ik heb zo lang gewacht!"}},{text:"De zwanen werden weer haar broers. Elisa kon eindelijk spreken en alles zeggen van haar liefde."}],vocabulary:[{word:"betovering",meaning:"een magie die iemand verandert",emoji:"✨"},{word:"brandnetel",meaning:"een plant met stekende bladeren",emoji:"🌿"},{word:"breien",meaning:"kleding maken met draden en naalden",emoji:"🧶"},{word:"stilte",meaning:"geen enkel woord zeggen",emoji:"🤫"}],miniGame:{type:"count",prompt:"Hoeveel broers moet Elisa redden?",answer:11,options:[7,9,11]},emotionalMoment:{feeling:"vastberadenheid",prompt:"Wat zou jij doen voor iemand van wie je houdt?"},rewardName:"Zwanenpen"},"chevre-monsieur-seguin":{title:"De geit van meneer Seguin",summary:"Het geitje Blanquette wil vrijheid maar ontdekt dat vrijheid ook verantwoordelijkheid vraagt.",theme:"vrijheid en voorzichtigheid",scenes:[{text:"Meneer Seguin had een mooi wit geitje: Blanquette. Maar ze wilde de vrijheid van de bergen."},{text:"Meneer Seguin smeekte haar te blijven.",dialogue:{speaker:"Meneer Seguin",line:"Er woont een grote wolf in de bergen!"}},{text:"Blanquette luisterde niet en sprong vrolijk over het hek."},{text:"S'avonds kwam de grote wolf.",dialogue:{speaker:"Blanquette",line:"Ik vecht tot de dageraad!"}},{text:"Blanquette vocht dapper de hele nacht en leerde dat vrijheid voorzichtigheid vraagt."}],vocabulary:[{word:"geit",meaning:"een boerderijdier met hoorns",emoji:"🐐"},{word:"dartelen",meaning:"vrij springen en rennen",emoji:"🦘"},{word:"dageraad",meaning:"als de zon opkomt",emoji:"🌅"},{word:"vrijheid",meaning:"doen wat je wilt",emoji:"🕊️"}],miniGame:{type:"choice",prompt:"Waarom wil meneer Seguin Blanquette houden?",options:["Voor de melk","Om haar te beschermen","Om niet alleen te zijn"],answerIndex:1},emotionalMoment:{feeling:"vrijheid en voorzichtigheid",prompt:"Hoe kun je tegelijk vrij zijn en veilig?"},rewardName:"Bergklokje"},sinbad:{title:"Sinbad de zeeman",summary:"De moedige zeeman Sinbad reist over de wereld en keert altijd wijzer terug.",theme:"moed en wijsheid",scenes:[{text:"Sinbad was een rijke koopman die van avonturen hield. Hij had zeven grote reizen gemaakt."},{text:"Op zijn eerste reis strandde zijn schip op een reusachtige slapende vis!",dialogue:{speaker:"Sinbad",line:"Dit is geen eiland... het is een dier! Vluchten!"}},{text:"Op elke reis trotseerde Sinbad nieuwe gevaren. Hij overwon alles met zijn verstand."},{text:"Hij bracht altijd schatten mee, maar vooral wijsheid.",dialogue:{speaker:"Sinbad",line:"De echte rijkdom is wat je leert op reis."}},{text:"Elke reis leerde hem iets nieuws over de wereld en over zichzelf."}],vocabulary:[{word:"zeeman",meaning:"iemand die op zee werkt",emoji:"⚓"},{word:"gevaar",meaning:"een grote bedreiging",emoji:"⚠️"},{word:"wijsheid",meaning:"kennis opgedaan door ervaring",emoji:"🦉"},{word:"stranden",meaning:"als een boot vastloopt",emoji:"🏖️"}],miniGame:{type:"count",prompt:"Hoeveel grote reizen heeft Sinbad gemaakt?",answer:7,options:[5,7,9]},emotionalMoment:{feeling:"avontuur",prompt:"Wat heb jij geleerd tijdens een reis of nieuwe ervaring?"},rewardName:"Kompas van de reiziger"},"tinder-box":{title:"Het vuurslag",summary:"Een soldaat vindt een magisch vuurslag en leert dat een vrijgevig hart de echte magie is.",theme:"vrijgevigheid en vriendschap",scenes:[{text:"Een soldaat ontmoette een heks die hem vroeg een vuurslag te halen uit een holle boom."},{text:"In de boom vond hij drie enorme honden die kisten goud bewaakten.",dialogue:{speaker:"Soldaat",line:"Ze gehoorzamen zolang ik het vuurslag heb!"}},{text:"Hij werd rijk en vrijgevig — hij gaf iedereen te eten."},{text:"Met het vuurslag kwamen de honden en vervulden zijn wensen.",dialogue:{speaker:"Soldaat",line:"Breng eten voor heel het dorp!"}},{text:"Door zijn vrijgevigheid won hij de liefde van iedereen."}],vocabulary:[{word:"vuurslag",meaning:"een voorwerp dat vuur maakt",emoji:"🔥"},{word:"vrijgevig",meaning:"die graag geeft en deelt",emoji:"🎁"},{word:"heks",meaning:"iemand die magie doet",emoji:"🧙"},{word:"kist",meaning:"een grote doos voor schatten",emoji:"📦"}],miniGame:{type:"count",prompt:"Hoeveel magische honden bewaken de schatten?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"vrijgevigheid",prompt:"Heb je ooit iets gedeeld dat je leuk vond? Hoe voelde dat?"},rewardName:"Vuurslag van vriendelijkheid"},"blue-bird":{title:"De Blauwe Vogel",summary:"Twee kinderen zoeken de Blauwe Vogel van het geluk en ontdekken dat geluk vlakbij is.",theme:"geluk en dankbaarheid",scenes:[{text:"Tyltyl en Mytyl woonden in een klein huisje aan de rand van het bos."},{text:"De fee Berylune vroeg hun de Blauwe Vogel van het geluk te zoeken.",dialogue:{speaker:"Fee Berylune",line:"Ga de Blauwe Vogel zoeken!"}},{text:"Ze reisden overal, maar de blauwe vogels stierven of verkleurden telkens."},{text:"Teleurgesteld gingen ze naar huis.",dialogue:{speaker:"Tyltyl",line:"Bestaat de Blauwe Vogel misschien niet?"}},{text:"Thuis had zijn duif — die hij altijd al had — prachtig blauwe veren. Het geluk was er altijd."}],vocabulary:[{word:"geluk",meaning:"een gevoel van vreugde en tevredenheid",emoji:"😊"},{word:"dankbaarheid",meaning:"blij zijn voor wat je hebt",emoji:"🙏"},{word:"herinnering",meaning:"een beeld in je geheugen",emoji:"💭"},{word:"teleurgesteld",meaning:"verdrietig omdat iets niet lukte",emoji:"😔"}],miniGame:{type:"choice",prompt:"Waar vindt Tyltyl de Blauwe Vogel?",options:["In een ver kasteel","In zijn eigen huis","Op de bodem van de zee"],answerIndex:1},emotionalMoment:{feeling:"dankbaarheid",prompt:"Welke mooie dingen heb je al die je blij maken?"},rewardName:"Gelukspen"},"renart-goupil":{title:"Reinaard de Vos",summary:"De slimme vos Reinaard leert dat zelfs de slimste soms betrapt wordt.",theme:"intelligentie en bescheidenheid",scenes:[{text:"In het grote bos woonde Reinaard, de slimste van alle dieren."},{text:"Hij stal een kip van Chantecler. Maar Chantecler had een plan.",dialogue:{speaker:"Chantecler",line:"Reinaard, laat me zien hoe je zingt!"}},{text:"Reinaard opende zijn bek — en de kip ontsnapte!"},{text:"Hij probeerde ook de kaas van Isegrim te stelen. De wolf was hem te slim af.",dialogue:{speaker:"Isegrim",line:"Je bent niet de enige die slim kan zijn!"}},{text:"Reinaard leerde: zelfs de slimste kan betrapt worden. Eerlijk zijn is beter."}],vocabulary:[{word:"vos",meaning:"een slim rood dier",emoji:"🦊"},{word:"slim",meaning:"handig in het bedenken van trucs",emoji:"🎭"},{word:"vleien",meaning:"te veel complimenten geven",emoji:"😏"},{word:"eerlijk",meaning:"die niet bedriegt",emoji:"✅"}],miniGame:{type:"choice",prompt:"Hoe krijgt Chantecler zijn kip terug?",options:["Door sneller te rennen","Door Reinaard te vleien","Door anderen te roepen"],answerIndex:1},emotionalMoment:{feeling:"bescheidenheid",prompt:"Heb je ooit iets belangrijks geleerd door een fout te maken?"},rewardName:"Staart van Reinaard"}},r={"snow-white":{title:"Snow White",summary:"A gentle princess with skin as white as snow finds a home with seven kind little helpers and learns that true friends always look after each other.",theme:"kindness and friendship",scenes:[{text:"Long ago, a little princess was born with skin as white as snow. Everyone called her Snow White."},{text:"A jealous queen owned a magic mirror and asked it the same question every day.",dialogue:{speaker:"Queen",line:"Mirror, mirror, who is the kindest and most beautiful of all?"}},{text:"Snow White walked into the heart of the forest. Seven kind little miners welcomed her into their cosy cottage.",dialogue:{speaker:"A miner",line:"You are safe here, little friend. Come and rest."}},{text:"The queen tricked her with a shiny apple, and Snow White fell into a very, very deep sleep."},{text:"A caring friend woke her with a gentle touch. Snow White smiled, and everyone celebrated their brave friend.",dialogue:{speaker:"Snow White",line:"You never left me. Thank you, my friends!"}}],vocabulary:[{word:"fairest",meaning:"the kindest and most beautiful person",emoji:"🌷"},{word:"jealous",meaning:"upset because you want what someone else has",emoji:"😠"},{word:"cottage",meaning:"a small, cosy house",emoji:"🏡"},{word:"welcome",meaning:"to make someone glad they have arrived",emoji:"🤗"}],miniGame:{type:"count",prompt:"How many kind little miners welcomed Snow White?",answer:7,options:[6,7,8]},emotionalMoment:{feeling:"surrounded and safe",prompt:"Snow White's friends looked after her. Who looks after you?"},rewardName:"Kind Mirror"},cinderella:{title:"Cinderella",summary:"A hard-working girl with a big heart gets a little help from a magical friend and discovers that being kind is a magic all of its own.",theme:"hope and kindness",scenes:[{text:"Cinderella did all the chores and never lost her sweet smile, even when others were unkind."},{text:"One evening, a grand ball was announced, but Cinderella had nothing to wear.",dialogue:{speaker:"Cinderella",line:"If only I could go dancing, just once."}},{text:"A kind fairy appeared and, with a wave of her wand, turned a pumpkin into a carriage.",dialogue:{speaker:"Fairy friend",line:"Be back before midnight, my dear — the magic stops then."}},{text:"At the ball, Cinderella danced and laughed. But when the clock began to strike, she had to run."},{text:"The slipper fitted her perfectly. Her kindness had always been seen, and joy filled her days.",dialogue:{speaker:"Cinderella",line:"Being kind costs nothing."}}],vocabulary:[{word:"chores",meaning:"small jobs that help around the home",emoji:"🧹"},{word:"carriage",meaning:"a coach pulled along to carry people",emoji:"🛞"},{word:"midnight",meaning:"twelve o'clock at night",emoji:"🕛"},{word:"gentle",meaning:"tender, calm, and kind",emoji:"🕊️"}],miniGame:{type:"count",prompt:"What time must Cinderella be back? Count the chimes of the clock!",answer:12,options:[10,11,12]},emotionalMoment:{feeling:"full of hope",prompt:"Even on hard days, Cinderella stayed kind. What helps you keep hoping?"},rewardName:"Glass Slipper"},"little-red-riding-hood":{title:"Little Red Riding Hood",summary:"A brave little girl in a red hood visits her grandmother and learns to listen to her wise feelings along the way.",theme:"listening and staying safe",scenes:[{text:"A little girl wore a bright red hood everywhere she went, so everyone called her Little Red Riding Hood."},{text:"Her mum gave her a basket of bread for Grandma.",dialogue:{speaker:"Mum",line:"Stay on the path and everything will be fine."}},{text:"In the woods, a crafty wolf asked lots of questions. Little Red felt something strange and kept on walking.",dialogue:{speaker:"Little Red",line:"I don't have to answer you. I will tell a grown-up."}},{text:"A kind woodcutter heard her and walked with her. Together, they arrived at Grandma's house."},{text:"Grandma was safe, and so was Little Red. They shared warm bread and laughed all afternoon.",dialogue:{speaker:"Grandma",line:"You listened to your wise feelings. I am so proud of you."}}],vocabulary:[{word:"path",meaning:"a track that shows you where to walk safely",emoji:"🛤️"},{word:"basket",meaning:"a carrier with a handle for taking things along",emoji:"🧺"},{word:"crafty",meaning:"someone who plays tricks to fool you",emoji:"🦊"},{word:"woodcutter",meaning:"a person who works among the trees",emoji:"🪓"}],miniGame:{type:"choice",prompt:"A stranger asks Little Red where she is going. What is the safe choice?",options:["Tell him everything","Keep walking and warn a grown-up","Follow him into the trees"],answerIndex:1},emotionalMoment:{feeling:"safe",prompt:"Little Red listened to her strange feeling. When has a feeling helped you stay safe?"},rewardName:"Red Hood"},"hansel-and-gretel":{title:"Hansel and Gretel",summary:"A brother and sister get lost in the woods and use a clever plan, and great teamwork, to find their way safely home.",theme:"cleverness and sticking together",scenes:[{text:"Hansel and Gretel walked into the great forest, holding hands so they would not get lost."},{text:"Clever Hansel dropped small, shiny white pebbles one by one to mark the way back.",dialogue:{speaker:"Hansel",line:"These pebbles will shine and lead us home."}},{text:"They found a little house made of sweets, but a crafty old woman lived there."},{text:"The children were too clever to be tricked. They held hands and crept quietly outside.",dialogue:{speaker:"Gretel",line:"Quickly — together we are braver than alone."}},{text:"The shiny pebbles glittered in the moonlight and led them straight home to a warm hug."}],vocabulary:[{word:"pebbles",meaning:"small, smooth little stones",emoji:"🪨"},{word:"clever",meaning:"good at thinking of smart ideas",emoji:"💡"},{word:"on tiptoe",meaning:"walking very quietly on your toes",emoji:"🦶"},{word:"together",meaning:"with each other, side by side",emoji:"🤝"}],miniGame:{type:"sequence",prompt:"Put Hansel's clever plan in the right order!",steps:["Drop the shiny pebbles","Follow the glittering trail","Find the way back home"]},emotionalMoment:{feeling:"brave together",prompt:"The children were braver as a team. Who makes you feel braver?"},rewardName:"Shiny Pebble"},rapunzel:{title:"Rapunzel",summary:"A kind girl with very long hair lives in a tall tower and learns that patience and a heart full of hope can open any door.",theme:"patience and hope",scenes:[{text:"Right at the top of a tall tower lived Rapunzel, a girl with the longest golden plait in the world."},{text:"Every day, Rapunzel sang to the birds. Her sweet song floated all through the forest.",dialogue:{speaker:"Rapunzel",line:"One day I will see the world down there, beneath the trees."}},{text:'A kind traveller heard her song and called up: "Your music makes the whole forest smile!"',dialogue:{speaker:"Traveller",line:"Your music makes the whole forest smile!"}},{text:"They became friends. Day after day, patiently, they thought of a clever way to climb down."},{text:"At last, Rapunzel set her foot on the soft grass and twirled in the sunshine, free and happy.",dialogue:{speaker:"Rapunzel",line:"Waiting was hard, but hope kept me strong."}}],vocabulary:[{word:"tower",meaning:"a very tall and narrow building",emoji:"🗼"},{word:"plait",meaning:"hair woven into a long rope-like braid",emoji:"💇"},{word:"patience",meaning:"waiting calmly without giving up",emoji:"⏳"},{word:"meadow",meaning:"a field of grass filled with flowers",emoji:"🌼"}],miniGame:{type:"find",prompt:"Find what Rapunzel used to climb down safely.",target:"the golden plaited ladder",decoys:["a paper kite","a wooden spoon","a little cup"]},emotionalMoment:{feeling:"patient",prompt:"Rapunzel waited with hope. What lovely thing have you waited a long time for?"},rewardName:"Golden Plait"},"the-ugly-duckling":{title:"The Ugly Duckling",summary:"A little bird who feels different from the others grows up and discovers it was wonderful exactly as it was, all along.",theme:"belonging and self-love",scenes:[{text:"In a sunny pond, a little bird did not look like its brothers and sisters."},{text:"The other birds laughed at it, and deep inside it felt lonely and very sad.",dialogue:{speaker:"Little bird",line:"I wish someone would let me join in too."}},{text:'A kind frog hopped over and sat beside it. "You are welcome with me," it said.',dialogue:{speaker:"Frog",line:"You are welcome with me, my friend."}},{text:"The seasons passed. On a bright morning, the little bird saw its face in the still water."},{text:"It had become a beautiful swan! It had always been special — simply itself.",dialogue:{speaker:"Swan",line:"I did not need to change. I just needed to grow."}}],vocabulary:[{word:"pond",meaning:"a small stretch of calm water",emoji:"💧"},{word:"lonely",meaning:"sad because you feel all alone",emoji:"🥺"},{word:"reflection",meaning:"the image you see in still water",emoji:"🪞"},{word:"swan",meaning:"a large, graceful white water bird",emoji:"🦢"}],miniGame:{type:"choice",prompt:"A new friend feels left out. What kind thing could you say?",options:["You don't belong here","You can play with us!","Go away"],answerIndex:1},emotionalMoment:{feeling:"I belong",prompt:"The little bird was special just as it was. What makes you a wonderful you?"},rewardName:"Gentle Swan"},"the-little-mermaid":{title:"The Little Mermaid",summary:"A curious young mermaid bravely explores a new world and learns that a kind and generous heart shines brighter than anything.",theme:"courage and a good heart",scenes:[{text:"Deep beneath the waves lived a young mermaid, the smallest of six sisters."},{text:"She loved to swim to the surface and gaze at the bright world above the water.",dialogue:{speaker:"Mermaid",line:"The world up there is full of things I want to learn!"}},{text:"On a stormy night, she bravely helped a sailor reach the shore safely."},{text:"She did not stay to be thanked. Helping someone filled her heart with warmth.",dialogue:{speaker:"Mermaid",line:"I helped out of kindness, not for a thank-you."}},{text:"Back home, she told her brave story, and her good heart made the whole sea shine."}],vocabulary:[{word:"mermaid",meaning:"an imaginary sea girl with a fish's tail",emoji:"🧜"},{word:"waves",meaning:"water that rises and falls on the sea",emoji:"🌊"},{word:"brave",meaning:"doing a hard thing even when it is scary",emoji:"💪"},{word:"generous",meaning:"happy to give and help others",emoji:"💝"}],miniGame:{type:"count",prompt:"How many older sisters did the Little Mermaid have?",answer:6,options:[5,6,7]},emotionalMoment:{feeling:"big-hearted",prompt:"The mermaid helped purely out of kindness. When have you helped without being asked?"},rewardName:"Sea Pearl"},"the-snow-queen":{title:"The Snow Queen",summary:"When her best friend's heart turns cold, a faithful girl called Gerda travels far through the snow to warm him with love.",theme:"faithful friendship",scenes:[{text:"Gerda and Kai were best friends and grew roses together by their window."},{text:"A tiny sliver of frost touched Kai's heart, and he became cold and distant.",dialogue:{speaker:"Gerda",line:"Wait... where are you going, Kai?"}},{text:"Brave Gerda did not give up. She set off through the snow to find her friend.",dialogue:{speaker:"Gerda",line:"I will find you, Kai. Friends don't give up."}},{text:"She found Kai in an ice palace, sitting still and cold as stone."},{text:"Gerda hugged him and warm tears fell. The frost melted, and Kai smiled and remembered.",dialogue:{speaker:"Kai",line:"You came all this way for me. Thank you, Gerda."}}],vocabulary:[{word:"frost",meaning:"a thin layer of ice that forms when it is very cold",emoji:"🌨️"},{word:"faithful",meaning:"always there for your friends",emoji:"🤲"},{word:"palace",meaning:"a very large and beautiful house",emoji:"🏰"},{word:"melt",meaning:"to go from ice to water with warmth",emoji:"💧"}],miniGame:{type:"choice",prompt:"How did Gerda melt the ice in Kai's heart?",options:["With a big fire","With warm tears and a hug","With a hammer"],answerIndex:1},emotionalMoment:{feeling:"faithful",prompt:"Gerda never gave up on her friend. How do you show a friend you care about them?"},rewardName:"Warm Rose"},"puss-in-boots":{title:"Puss in Boots",summary:"A clever cat in fine boots uses his quick wits and loyal heart to help his kind friend find happiness.",theme:"cleverness and loyalty",scenes:[{text:"A clever cat pulled on fine boots and a feathered hat, ready for adventure."},{text:"His friend was poor but kind, so the cat thought of a clever plan to help him.",dialogue:{speaker:"The Cat",line:"Trust me, my friend. A clever idea is on its way!"}},{text:"The cat greeted the king politely and offered gifts, making everyone smile."},{text:"With wit rather than tricks, the cat helped his friend win a grand castle by the river.",dialogue:{speaker:"The Cat",line:"Good ideas open more doors than loud roars."}},{text:"His friend was happy at last, and the cat curled up by the fire, the most faithful cat of all."}],vocabulary:[{word:"clever",meaning:"good at thinking of smart ideas",emoji:"🧠"},{word:"boots",meaning:"shoes that go up high on your legs",emoji:"🥾"},{word:"polite",meaning:"kind and gentle with your words",emoji:"🙏"},{word:"loyal",meaning:"always there for your friends",emoji:"🤝"}],miniGame:{type:"sequence",prompt:"Put the Cat's clever plan in the right order!",steps:["Put on the fine boots","Greet the king politely","Help his friend win the day"]},emotionalMoment:{feeling:"helpful",prompt:"The Cat used clever ideas to help a friend. In what clever way have you helped someone?"},rewardName:"Fine Boots"},pinocchio:{title:"Pinocchio",summary:"A wooden puppet who dreams of being a real boy learns that telling the truth is what makes a good heart grow.",theme:"honesty",scenes:[{text:"Once upon a time there was a little wooden puppet called Pinocchio, who dreamed of becoming a real boy."},{text:"Every time Pinocchio told a lie, his nose grew longer like a branch.",dialogue:{speaker:"Pinocchio",line:"It wasn't me! I promise!"}},{text:"His friend the cricket tried to teach him always to tell the truth.",dialogue:{speaker:"Cricket",line:"Telling the truth will make you feel light as a feather."}},{text:"Pinocchio made a big mistake and got lost. He learned then that honesty was his only guide."},{text:"When Pinocchio finally told the truth, his heart grew, and his dearest wish came true.",dialogue:{speaker:"Pinocchio",line:"The truth is the most powerful magic of all."}}],vocabulary:[{word:"puppet",meaning:"a doll that is made to move",emoji:"🎭"},{word:"truth",meaning:"saying exactly what happened",emoji:"✅"},{word:"lie",meaning:"saying something that is not true",emoji:"❌"},{word:"honest",meaning:"someone who always tells the truth",emoji:"🌟"}],miniGame:{type:"choice",prompt:"When does Pinocchio's nose grow longer?",options:["When he tells the truth","When he tells a lie","When he sings a song"],answerIndex:1},emotionalMoment:{feeling:"honest",prompt:"Telling the truth made Pinocchio feel light. How do you feel when you tell the truth?"},rewardName:"Cricket of Truth"},"peter-pan":{title:"Peter Pan",summary:"A boy who never grows up takes new friends on a flying adventure where happy thoughts and a little courage take you anywhere.",theme:"imagination and courage",scenes:[{text:"In a bedroom full of stars, a boy called Peter Pan taught the children to fly."},{text:"Peter told Wendy the secret: you had to think of something very happy.",dialogue:{speaker:"Peter Pan",line:"Think of your happiest thing — and off you go!"}},{text:"Together they flew to Neverland, a magical island full of adventures."},{text:"Even facing the wicked captain, Peter was not afraid. He met danger with a big smile.",dialogue:{speaker:"Peter Pan",line:"Being brave means trying anyway."}},{text:"The children went home with hearts full of memories and a little magic for ever."}],vocabulary:[{word:"bedroom",meaning:"the room where you sleep and dream",emoji:"🛏️"},{word:"shadow",meaning:"the dark shape your body makes on the ground",emoji:"👤"},{word:"imagine",meaning:"to create beautiful things inside your head",emoji:"💭"},{word:"courage",meaning:"trying even when you are scared",emoji:"💪"}],miniGame:{type:"choice",prompt:"What helped the children fly?",options:["Happy thoughts and fairy dust","Heavy boots","Shouting very loudly"],answerIndex:0},emotionalMoment:{feeling:"brave",prompt:"Peter says being brave means trying anyway. What brave thing would you like to try?"},rewardName:"Fairy Dust"},"alice-in-wonderland":{title:"Alice in Wonderland",summary:"A curious girl follows a hurrying rabbit into a topsy-turvy world and learns that asking questions is a kind of magic.",theme:"curiosity",scenes:[{text:"Alice saw a hurrying white rabbit jump into a hole and, feeling very curious, she followed it."},{text:"She fell down a long magical tunnel and found a tiny door into a garden.",dialogue:{speaker:"Alice",line:"How very strange! I wonder what is going on here."}},{text:"Alice drank a little bottle and shrank, then ate a cake and grew very quickly.",dialogue:{speaker:"Alice",line:"Questions are the key to all the wonders!"}},{text:"She met a grinning cat, an angry queen, and a very mad hatter."},{text:"Alice woke up and smiled. Asking questions had led her to the most beautiful of dreams.",dialogue:{speaker:"Alice",line:"Curiosity is the greatest adventure."}}],vocabulary:[{word:"curious",meaning:"someone who loves discovering new things",emoji:"🔍"},{word:"burrow",meaning:"a tunnel dug in the earth by an animal",emoji:"🕳️"},{word:"shrink",meaning:"to become smaller",emoji:"🔻"},{word:"wonder",meaning:"something incredible and very surprising",emoji:"😲"}],miniGame:{type:"sequence",prompt:"Put Alice's adventure in the right order!",steps:["Drink the bottle and shrink","Eat the cake and grow","Find the tiny garden door"]},emotionalMoment:{feeling:"curious",prompt:"Alice loved asking questions. What makes you curious today?"},rewardName:"Curious Clock"},"the-wizard-of-oz":{title:"The Wizard of Oz",summary:"A girl and three new friends follow a golden road and discover that the gifts they were searching for were inside them all along.",theme:"you already have what you need",scenes:[{text:"A great whirlwind carried Dorothy and her little dog Toto away to the magical land of Oz."},{text:"On the golden road, Dorothy met a scarecrow, a tin man, and a lion.",dialogue:{speaker:"Scarecrow",line:"I just want a clever brain!"}},{text:"Together they walked towards the Emerald City to find the great Wizard.",dialogue:{speaker:"Dorothy",line:"If we are together, we can do anything."}},{text:"The Wizard revealed a great secret: they already had everything they desired."},{text:"Dorothy tapped her shoes three times and was back home. Everyone had found their gift.",dialogue:{speaker:"Dorothy",line:"There is no place like home."}}],vocabulary:[{word:"whirlwind",meaning:"a very strong wind that spins round and round",emoji:"🌪️"},{word:"scarecrow",meaning:"a large straw figure put out to frighten birds",emoji:"🌾"},{word:"courage",meaning:"to keep going even when you are afraid",emoji:"💪"},{word:"journey",meaning:"a long walk or adventure to a new place",emoji:"🗺️"}],miniGame:{type:"choice",prompt:"Which friend already had courage from the very beginning?",options:["The scarecrow","The tin man","The lion"],answerIndex:2},emotionalMoment:{feeling:"capable",prompt:"The friends already had their gifts inside them. What gift do you already have inside you?"},rewardName:"Sparkling Shoes"},"robin-hood":{title:"Robin Hood",summary:"A kind archer from the green forest shares with those who have very little and teaches his friends that fairness makes everyone happier.",theme:"fairness and generosity",scenes:[{text:"In a great green forest lived Robin Hood, the finest archer in the land."},{text:"He saw that many people were very poor while others had everything.",dialogue:{speaker:"Robin",line:"Sharing is the finest gift of all."}},{text:"With his merry friends, Robin made a plan to help those in need.",dialogue:{speaker:"Little John",line:"Together we are the strength of the forest!"}},{text:"Robin gave people what they needed, and smiles appeared everywhere."},{text:"The forest hummed with happiness. Robin had learned that generosity is the true victory.",dialogue:{speaker:"Robin",line:"Generosity makes everyone richer."}}],vocabulary:[{word:"archer",meaning:"someone who shoots arrows with a bow",emoji:"🎯"},{word:"forest",meaning:"a large place full of trees and animals",emoji:"🌳"},{word:"fair",meaning:"treating everyone in the same way",emoji:"⚖️"},{word:"generous",meaning:"happy to give and share",emoji:"🎁"}],miniGame:{type:"choice",prompt:"Robin Hood shared with people who were...",options:["hungry and in need","already very rich","unkind to others"],answerIndex:0},emotionalMoment:{feeling:"fair",prompt:"Robin loved to share. What could you share to make a friend smile?"},rewardName:"Friendly Bow"},goldilocks:{title:"Goldilocks",summary:"A curious girl steps into the bears' cosy cottage and learns that it is best to ask first and take care of other people's things.",theme:"respect for others",scenes:[{text:"A little girl with golden curls was walking through the forest when she found a pretty cottage."},{text:"She went inside and tasted three bowls of porridge. The baby bear's was just right.",dialogue:{speaker:"Goldilocks",line:"Oh! This bowl is perfect — not too hot and not too cold!"}},{text:"She tried three chairs, then three beds. She fell asleep in the cosiest one."},{text:"The three bears came home and found their house all mixed up.",dialogue:{speaker:"Baby Bear",line:"Someone has been eating my porridge!"}},{text:"Goldilocks woke up, said sorry, and learned that asking first is the kindest manners.",dialogue:{speaker:"Goldilocks",line:"Sorry. I will always ask before I come in."}}],vocabulary:[{word:"porridge",meaning:"warm, soft food, like breakfast cereal",emoji:"🥣"},{word:"cottage",meaning:"a small, cosy house in the forest",emoji:"🏡"},{word:"respect",meaning:"taking care of other people's things and feelings",emoji:"🙏"},{word:"sorry",meaning:"what you say when you regret something",emoji:"💙"}],miniGame:{type:"count",prompt:"How many bears lived in the cosy cottage?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"respectful",prompt:"Goldilocks learned to ask first. When is it kind to ask permission before borrowing something?"},rewardName:"Perfect Bowl"},"three-little-pigs":{title:"The Three Little Pigs",summary:"Three little pigs build three different houses and learn that careful, hard work keeps everyone safe and warm.",theme:"hard work and planning",scenes:[{text:"Three little pigs set off into the world to build their houses."},{text:"The first pig quickly built a house of straw. The second built a house of wood.",dialogue:{speaker:"First pig",line:"Quick and done! I want to go and play!"}},{text:"The third pig worked hard and built a solid house of bricks, one by one.",dialogue:{speaker:"Third pig",line:"I am taking my time so my house will be strong."}},{text:"The big bad wolf blew down the houses of straw and wood, and they collapsed."},{text:"But the brick house stayed firm. The three pigs were safe, and everyone learned that careful work protects.",dialogue:{speaker:"Third pig",line:"Good work takes time, but it is worth it!"}}],vocabulary:[{word:"straw",meaning:"dry plant stems that are easy to break",emoji:"🌾"},{word:"bricks",meaning:"very strong baked earth blocks",emoji:"🧱"},{word:"strong",meaning:"very solid and not easy to break",emoji:"💪"},{word:"plan",meaning:"to think carefully before you start something",emoji:"📋"}],miniGame:{type:"count",prompt:"How many little pigs built houses?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"proud of my work",prompt:"The third pig worked hard and stayed safe. What have you worked hard on?"},rewardName:"Solid Brick"},aladdin:{title:"Aladdin",summary:"An ordinary but kind boy finds a magic lamp and learns that what you wish for matters far less than the good you do for others.",theme:"honesty and humility",scenes:[{text:"In a busy market lived Aladdin, a poor boy with a heart of gold."},{text:"He found an old lamp and, when he rubbed it, a great genie appeared!",dialogue:{speaker:"Genie",line:"I grant you three wishes. Choose carefully!"}},{text:"Aladdin first wished to help his family, then the poor people of his neighbourhood.",dialogue:{speaker:"Aladdin",line:"I want no one in this market to go hungry."}},{text:"His humility and generosity earned him true friends and a great deal of happiness."},{text:"Aladdin learned that the best wishes are the ones you make for others.",dialogue:{speaker:"Aladdin",line:"A generous heart is the greatest treasure."}}],vocabulary:[{word:"market",meaning:"a busy place where people sell and buy things",emoji:"🏪"},{word:"lamp",meaning:"an object that gives light or holds a genie",emoji:"🪔"},{word:"humble",meaning:"someone who does not boast about themselves",emoji:"🙏"},{word:"wish",meaning:"something you want very, very much",emoji:"⭐"}],miniGame:{type:"count",prompt:"How many wishes did the genie give Aladdin?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"generous",prompt:"Aladdin wished to help others. If you had one kind wish, what would it be?"},rewardName:"Wishing Lamp"},"ali-baba":{title:"Ali Baba",summary:"A gentle woodcutter discovers a secret cave and learns that being honest and careful is worth far more than being greedy.",theme:"honesty over greed",scenes:[{text:"Ali Baba was a gentle woodcutter who lived simply and happily."},{text:"One day in the forest, he heard thieves say the magic words in front of a great rock.",dialogue:{speaker:"Thieves",line:"Open Sesame!"}},{text:"Ali Baba entered the cave and saw dazzling treasures of every colour.",dialogue:{speaker:"Ali Baba",line:"I will take only what we need — no more."}},{text:"His greedy brother took too much and was caught by the thieves. Ali Baba understood the lesson."},{text:"Ali Baba shared his good fortune with others and lived simply and happily.",dialogue:{speaker:"Ali Baba",line:"Having enough and being honest — that is true wealth."}}],vocabulary:[{word:"cave",meaning:"a large, natural hollow in the rock",emoji:"🕳️"},{word:"treasure",meaning:"a large amount of gold and precious things",emoji:"💎"},{word:"greedy",meaning:"someone who always wants more than they need",emoji:"😤"},{word:"enough",meaning:"just what you need — no more and no less",emoji:"✅"}],miniGame:{type:"choice",prompt:"What magic words open the cave?",options:["Open Sesame!","Shut the door!","Good morning!"],answerIndex:0},emotionalMoment:{feeling:"content",prompt:"Ali Baba only took what was needed. What thing you already have is just enough for you?"},rewardName:"Secret Cave"},"aesops-fables":{title:"The Hare and the Tortoise",summary:"A speedy hare and a slow tortoise have a friendly race, and the tortoise shows everyone that never giving up wins the day.",theme:"perseverance — slow and steady",scenes:[{text:"In a sunny meadow, a speedy hare was always boasting about how fast he was."},{text:"The slow, calm tortoise suggested a race. The hare accepted with a laugh.",dialogue:{speaker:"Hare",line:"A race against you? Easy! I'll have a rest on the way."}},{text:"The tortoise moved step by step, steadily, never stopping.",dialogue:{speaker:"Tortoise",line:"Slow and steady, I will keep moving forward."}},{text:"The hare fell asleep under a tree, sure that the tortoise could never catch up."},{text:"When the hare woke up, the tortoise had already crossed the finish line. Perseverance always wins.",dialogue:{speaker:"Tortoise",line:"Step by step, you get further than you think."}}],vocabulary:[{word:"hare",meaning:"a large, wild rabbit that is very fast",emoji:"🐇"},{word:"tortoise",meaning:"a shelled animal that walks slowly but never stops",emoji:"🐢"},{word:"steady",meaning:"moving at the same pace without stopping",emoji:"⏱️"},{word:"persevere",meaning:"to keep trying even when it is hard",emoji:"💪"}],miniGame:{type:"choice",prompt:"Who won the race by never giving up?",options:["the speedy hare","the slow, steady tortoise","the sleeping fox"],answerIndex:1},emotionalMoment:{feeling:"determined",prompt:"The tortoise kept going step by step. What do you keep trying at?"},rewardName:"Persevering Tortoise"},"sleeping-beauty":{title:"Sleeping Beauty",summary:"A beautiful princess falls into a magical sleep and awaits true love.",theme:"patience and hope",scenes:[{text:"A happy king and queen finally had a little daughter. They invited all the fairies of the kingdom to her christening."},{text:"The good fairies gave the princess their gifts: beauty, grace, and gentleness. But an angry bad fairy arrived uninvited.",dialogue:{speaker:"Bad fairy",line:"When she turns sixteen, she shall prick her finger on a spindle and fall down dead!"}},{text:"The last good fairy had not yet spoken. She softened the curse: the princess would not die, but sleep for a hundred years.",dialogue:{speaker:"Good fairy",line:"She will sleep, but love shall wake her."}},{text:"At sixteen, the princess found an old woman spinning. She touched the spindle and fell into a deep sleep. The whole castle fell asleep with her."},{text:"A prince heard of the sleeping castle hidden behind a forest of roses. He cut through the thorns and entered the silent castle.",dialogue:{speaker:"Prince",line:"How beautiful she is! I shall wake her."}},{text:"The prince leaned over the beautiful princess and gave her a gentle kiss. She opened her eyes and smiled. The whole castle woke at the same moment, and they lived happily ever after.",dialogue:{speaker:"Princess",line:"I have waited so long. At last you have come!"}}],vocabulary:[{word:"spindle",meaning:"a tool for spinning wool, with a sharp point",emoji:"🧵"},{word:"malevolent",meaning:"someone who uses wicked magic to cause harm",emoji:"🧙"},{word:"enchanted",meaning:"changed by a special spell or magic",emoji:"✨"},{word:"rose bush",meaning:"a thorny bush that grows beautiful roses",emoji:"🌹"}],miniGame:{type:"choice",prompt:"Which bad fairy casts the spell on the princess?",options:["A fairy who was not invited","The palace fairy","The forest fairy"],answerIndex:0},emotionalMoment:{feeling:"hope",prompt:"Have you ever waited impatiently for something? How did it feel?"},rewardName:"Enchanted Rose"},"beauty-and-the-beast":{title:"Beauty and the Beast",summary:"Beauty learns that true beauty lies in the heart, not in appearance.",theme:"kindness and true love",scenes:[{text:"A merchant got lost in the forest during a storm. He found a great mysterious castle and sheltered there for the night."},{text:"As he was leaving, he picked a rose for his daughter Beauty. A terrifying Beast suddenly appeared.",dialogue:{speaker:"Beast",line:"You have stolen my rose! You are my prisoner!"}},{text:"The merchant begged the Beast to let him say goodbye to his children. The Beast agreed, on the condition that one of his daughters return in his place.",dialogue:{speaker:"Beauty",line:"Father, I will go. I am not afraid."}},{text:"Beauty lived in the castle. The Beast was ugly but gentle and kind. Each evening they talked and laughed together."},{text:"Beauty asked to go home to see her sick father. The Beast agreed, sadly.",dialogue:{speaker:"Beast",line:"I will miss you, Beauty. But your happiness comes before my own."}},{text:"Far from the castle, Beauty realised she loved the Beast. She ran back to him. When she confessed her love, the Beast was transformed into a handsome prince.",dialogue:{speaker:"Beauty",line:"I love you, not for your face, but for your heart."}},{text:"The prince explained that a sorceress had enchanted him. Only sincere love could set him free. Beauty and the prince lived happily ever after."}],vocabulary:[{word:"beast",meaning:"a large frightening animal, here an enchanted monster",emoji:"🐾"},{word:"prisoner",meaning:"someone who is not free to leave",emoji:"🔒"},{word:"appearance",meaning:"what you see of someone from the outside",emoji:"👁️"},{word:"transformation",meaning:"to change completely in shape or appearance",emoji:"✨"}],miniGame:{type:"choice",prompt:"Why does Beauty's father go to the castle?",options:["He is looking for treasure","He shelters from the storm and picks a rose","He visits the Beast"],answerIndex:1},emotionalMoment:{feeling:"kindness",prompt:"Have you ever judged someone by their appearance before getting to know them?"},rewardName:"Magic Rose"},"little-thumb":{title:"Hop o' My Thumb",summary:"The smallest of seven brothers uses his wits to save his whole family.",theme:"courage and intelligence",scenes:[{text:"A poor woodcutter and his wife had seven sons. The smallest was called Hop o' My Thumb. He was tiny but very clever."},{text:"One evening the parents, too poor to feed their children, abandoned them in the forest.",dialogue:{speaker:"Hop o' My Thumb",line:"I knew they would do this. I am ready."}},{text:"Hop o' My Thumb had prepared: he had filled his pockets with small white pebbles. He scattered them all along the path, and the children found their way home by following them."},{text:"The second time they were abandoned, he had only bread to scatter crumbs. The birds ate them and the brothers were truly lost."},{text:"Lost, they arrived at an ogre's house. The ogre's wife hid them, but the ogre found them.",dialogue:{speaker:"Ogre",line:"I smell fresh flesh! Where are they hidden?"}},{text:"Hop o' My Thumb had a brilliant idea: he swapped his brothers' caps with the crowns of the ogre's daughters. The ogre made the wrong choice in the dark."},{text:"Hop o' My Thumb stole the ogre's seven-league boots while he slept. In a few strides he fetched gold and saved his whole family.",dialogue:{speaker:"Hop o' My Thumb",line:"Cleverness is worth more than strength!"}}],vocabulary:[{word:"pebbles",meaning:"small smooth stones you can scatter along a path",emoji:"🪨"},{word:"ogre",meaning:"a giant monster in fairy tales that eats children",emoji:"👹"},{word:"league",meaning:"a great distance, like several kilometres",emoji:"🗺️"},{word:"ruse",meaning:"a clever idea used to trick someone",emoji:"💡"}],miniGame:{type:"sequence",prompt:"Put the steps in the right order!",steps:["Scatter white pebbles to find the way home","Arrive at the ogre's house in the forest","Steal the seven-league boots"]},emotionalMoment:{feeling:"courage",prompt:"Have you ever been frightened but carried on anyway? What helped you?"},rewardName:"Seven-League Boots"},"jack-beanstalk":{title:"Jack and the Beanstalk",summary:"Jack swaps his cow for magic beans and discovers a castle in the clouds.",theme:"adventure and curiosity",scenes:[{text:"Jack and his mother were very poor. One day his mother sent Jack to sell their old cow at the market."},{text:"On the road, an old man offered Jack magic beans in exchange for the cow. Jack accepted.",dialogue:{speaker:"Jack",line:"Magic beans! That's a fine bargain!"}},{text:"Jack's mother was very angry and threw the beans out of the window. But overnight an enormous beanstalk grew all the way up to the clouds."},{text:"Jack climbed the beanstalk and discovered a huge castle in the clouds. A terrible giant lived there.",dialogue:{speaker:"Giant",line:"Fee-fi-fo-fum! I smell the blood of an Englishman!"}},{text:"The giant's wife helped Jack hide. While the giant slept, Jack seized the golden hen and the enchanted harp."},{text:"Jack slid down the beanstalk as fast as he could. The giant gave chase. Jack grabbed his axe and chopped the stalk down. The giant fell far, far away.",dialogue:{speaker:"Jack",line:"Mother! We will be rich! Never hungry again!"}}],vocabulary:[{word:"beanstalk",meaning:"a very tall bean plant that grows up to the sky",emoji:"🫘"},{word:"giant",meaning:"an imaginary creature of enormous size and strength",emoji:"🦣"},{word:"clouds",meaning:"the large white or grey shapes floating in the sky",emoji:"☁️"},{word:"treasure",meaning:"precious objects such as gold or jewels",emoji:"🪙"}],miniGame:{type:"choice",prompt:"What does Jack swap his cow for?",options:["Gold coins","Magic beans","A harp"],answerIndex:1},emotionalMoment:{feeling:"curiosity",prompt:"Have you ever discovered something surprising? How did you feel?"},rewardName:"Giant's Treasure"},thumbelina:{title:"Thumbelina",summary:"Thumbelina, a tiny little girl, searches for her place in a world that is far too big for her.",theme:"identity and belonging",scenes:[{text:"A woman who longed for a child planted a magic seed. A flower grew, and inside it slept a very tiny girl. Her name was Thumbelina."},{text:"One evening a horrible toad kidnapped Thumbelina to marry his son. Thumbelina wept on her lily pad.",dialogue:{speaker:"Thumbelina",line:"I don't want to stay here. I want to find my true home."}},{text:"Friendly fish nibbled through the lily-pad stalk and Thumbelina escaped. She travelled through fields and forests, always too small for everyone around her."},{text:"In winter, Thumbelina found shelter with a field mouse. But the mouse wanted her to marry an old blind mole."},{text:"Thumbelina found an injured swallow and nursed it tenderly through the whole winter.",dialogue:{speaker:"Swallow",line:"You have saved me. When spring comes I will carry you far from here."}},{text:"In spring, the swallow carried Thumbelina to a warm and flowery land. There she met a tiny flower prince. At last she had found her place.",dialogue:{speaker:"Flower prince",line:"You are welcome here. Will you be our queen?"}}],vocabulary:[{word:"tiny",meaning:"extremely small, much smaller than everyone else",emoji:"🔬"},{word:"kidnap",meaning:"to take someone away by force without their permission",emoji:"😨"},{word:"swallow",meaning:"a small, swift bird that travels to warm countries",emoji:"🐦"},{word:"fairy",meaning:"a magical winged creature that helps others",emoji:"🧚"}],miniGame:{type:"find",prompt:"Find the flower where Thumbelina sleeps!",target:"the big pink flower",decoys:["a green lily pad","a dry leaf","a mushroom"]},emotionalMoment:{feeling:"belonging",prompt:"Have you ever felt you did not quite fit in? How did you find your place?"},rewardName:"Fairy Wings"},"twelve-dancing-princesses":{title:"The Twelve Dancing Princesses",summary:"Every night twelve princesses secretly wear out their shoes dancing. A soldier uncovers their mystery.",theme:"mystery and perseverance",scenes:[{text:"A king had twelve daughters. Every morning their shoes were worn through as if they had danced all night. But nobody knew why."},{text:"The king announced that whoever discovered the secret could marry one of his daughters. Princes tried, but all fell mysteriously asleep.",dialogue:{speaker:"King",line:"Who will solve this mystery? Their shoes are worn out again!"}},{text:"An old soldier returning from the wars met a wise old woman who gave him an invisible cloak.",dialogue:{speaker:"Old woman",line:"Do not drink the drink they offer you. And take care!"}},{text:"The soldier pretended to sleep. At midnight the princesses rose. He followed them invisibly through a secret passage underground."},{text:"Underground he discovered a lake with boats, a forest of silver and golden trees, and a lit castle where twelve princes waited to dance with the princesses."},{text:"The soldier secretly broke off a silver branch to prove his discovery. The eldest princess heard a sound.",dialogue:{speaker:"Eldest princess",line:"Something is not right tonight. I am afraid."}},{text:"Next morning the soldier showed the king the branch and told him everything. The king accepted the truth. The soldier chose to marry the eldest princess, and the secret was revealed for ever.",dialogue:{speaker:"Soldier",line:"The truth is worth more than any secret."}}],vocabulary:[{word:"mystery",meaning:"something hidden that you do not yet understand",emoji:"🔍"},{word:"invisible",meaning:"cannot be seen even though it is there",emoji:"👻"},{word:"slipper",meaning:"an elegant shoe, often used for dancing",emoji:"👠"},{word:"underground",meaning:"beneath the ground, hidden below",emoji:"🕳️"}],miniGame:{type:"match",prompt:"Match each princess to her dancing prince!",pairs:[{left:"Princess Rose",right:"Prince Dorian"},{left:"Princess Moon",right:"Prince Silvain"},{left:"Princess Star",right:"Prince Aurele"},{left:"Princess Violet",right:"Prince Florian"}]},emotionalMoment:{feeling:"mystery",prompt:"Do you have a secret? How does it feel to keep one?"},rewardName:"Crown of Mystery"},rumpelstiltskin:{title:"Rumpelstiltskin",summary:"A mysterious little man helps a girl spin straw into gold — but at what price?",theme:"promises and honesty",scenes:[{text:'A miller wanted to impress the king and told a great lie: "My daughter can spin straw into gold!" The king locked the girl in a tower full of straw.'},{text:"The girl was weeping when a strange little man appeared.",dialogue:{speaker:"Rumpelstiltskin",line:"What will you give me if I spin all this straw into gold for you?"}},{text:"She gave him her necklace. The little man spun all the straw into gold. The king, astonished, put her in an even larger room."},{text:"On the third night the girl had nothing left to give. She promised her first child. The king married her and she became queen."},{text:"A year later the little man returned to claim the child. The queen pleaded with him. He gave her three days to guess his name.",dialogue:{speaker:"Rumpelstiltskin",line:"If you guess my name, you may keep the child!"}},{text:"A messenger overheard the little man dancing and singing his name in the forest. He ran back to tell the queen.",dialogue:{speaker:"Messenger",line:"His name is Rumpelstiltskin! I heard him singing it!"}}],vocabulary:[{word:"straw",meaning:"dry cereal stalks, yellow and light",emoji:"🌾"},{word:"spin",meaning:"to turn fibres into thread using a spinning wheel",emoji:"🧶"},{word:"promise",meaning:"what you say you will do and must keep",emoji:"🤝"},{word:"riddle",meaning:"a puzzle question with a hidden answer to find",emoji:"❓"}],miniGame:{type:"choice",prompt:"How does the queen guess the imp's name?",options:["A messenger heard him singing in the forest","She read it in a book","The imp told her himself"],answerIndex:0},emotionalMoment:{feeling:"honesty",prompt:"Is it important to keep your promises? Why?"},rewardName:"Golden Thread"},"emperor-new-clothes":{title:"The Emperor's New Clothes",summary:"Two swindlers convince a vain emperor they are weaving him invisible clothes that only clever people can see.",theme:"honesty and courage",scenes:[{text:"Once upon a time there was an emperor who loved fine clothes above all else. He changed his outfit several times a day."},{text:"Two swindlers presented themselves as the finest weavers in the world. They claimed to weave a magical cloth: invisible to fools and incompetents.",dialogue:{speaker:"Swindler",line:"Only truly intelligent people can see these clothes!"}},{text:"Ministers were sent to check on the work. They saw nothing at all, but dared not say so for fear of looking foolish.",dialogue:{speaker:"Minister",line:"It is magnificent... absolutely magnificent."}},{text:"The swindlers handed the emperor his imaginary new clothes. The emperor saw nothing either, but he pretended."},{text:"The emperor processed through the streets. Everyone cheered, afraid to seem foolish."},{text:"Suddenly a small child cried out the truth.",dialogue:{speaker:"Child",line:"But he has nothing on! The emperor is completely naked!"}}],vocabulary:[{word:"vain",meaning:"someone who thinks too much about their looks and believes themselves beautiful",emoji:"🪞"},{word:"swindler",meaning:"someone who lies to steal from or deceive others",emoji:"🎭"},{word:"invisible",meaning:"impossible to see with your eyes",emoji:"👻"},{word:"truth",meaning:"what is really true, even if it is uncomfortable",emoji:"✅"}],miniGame:{type:"choice",prompt:"Who tells the truth first?",options:["A small child","A minister","The emperor himself"],answerIndex:0},emotionalMoment:{feeling:"courage",prompt:"Have you ever had the courage to tell a difficult truth?"},rewardName:"Courage of Truth"},"steadfast-tin-soldier":{title:"The Steadfast Tin Soldier",summary:"A brave little tin soldier lives a great adventure and proves that courage comes from the heart.",theme:"courage and faithfulness",scenes:[{text:"Among a box of tin soldiers, one had only a single leg. Yet he stood straight and proud like all the others."},{text:"On a shelf opposite, a little paper dancer held up one leg. The soldier thought she was like him, and he fell in love with her.",dialogue:{speaker:"Soldier",line:"She is so beautiful. I wish I could stay close to her for ever."}},{text:"A jealous goblin inside a box shouted that the soldier must not look at the dancer. The next day the soldier fell from a window."},{text:"In the street, children found him and put him in a paper boat. He sailed down the gutter in the rain, and was later swallowed by a large fish."},{text:"The fish was caught and brought to the kitchen. The cook cut it open and found the tin soldier unharmed, still standing straight.",dialogue:{speaker:"Cook",line:"How on earth did you survive all of that!"}},{text:"The soldier was returned to the child. But the jealous goblin threw the soldier into the fire. The little dancer also fell in on a gust of wind. All that remained of the soldier was a tiny heart of metal, a symbol of his undying faithfulness.",dialogue:{speaker:"Soldier",line:"I stayed steadfast to the very end."}}],vocabulary:[{word:"tin",meaning:"a grey heavy metal once used for making toys",emoji:"⚙️"},{word:"steadfast",meaning:"brave and firm in the face of danger",emoji:"🛡️"},{word:"torrent",meaning:"a powerful, rushing stream of water",emoji:"🌊"},{word:"faithfulness",meaning:"staying loyal to someone you love, whatever happens",emoji:"💙"}],miniGame:{type:"choice",prompt:"Who does the tin soldier fall in love with?",options:["A little paper dancer","A princess in the castle","A magic fairy"],answerIndex:0},emotionalMoment:{feeling:"faithfulness",prompt:"Is there someone or something you are very faithful to? What does that mean to you?"},rewardName:"Medal of Courage"},"la-fontaine-crow-fox":{title:"The Crow and the Fox",summary:"A very cunning fox flatters a crow to steal his cheese. A fable about vanity.",theme:"cunning and humility",scenes:[{text:"A crow was perched on a branch, holding a fine piece of fragrant cheese in his beak."},{text:"A very crafty fox came by and smelled the cheese. He decided to steal it through flattery.",dialogue:{speaker:"Fox",line:"O Master Crow, how handsome you are! What magnificent feathers you have!"}},{text:"The crow, puffed up with pleasure at the compliments, ruffled his feathers proudly. The fox went on.",dialogue:{speaker:"Fox",line:"If your voice is as beautiful as your feathers, you are the king of birds!"}},{text:"The crow, far too flattered, opened his beak wide to sing. The cheese fell."},{text:"The fox snatched the cheese up laughing and spoke the moral of the fable.",dialogue:{speaker:"Fox",line:"Every flatterer lives at the expense of those who listen to him. That lesson is well worth a cheese!"}}],vocabulary:[{word:"crow",meaning:"a large black bird with a strong curved beak",emoji:"🐦‍⬛"},{word:"flatterer",meaning:"someone who pays too many compliments to get something",emoji:"😏"},{word:"cheese",meaning:"a food made from milk, often yellow or white",emoji:"🧀"},{word:"moral",meaning:"the lesson you learn at the end of a fable",emoji:"📜"}],miniGame:{type:"choice",prompt:"How does the fox get the cheese?",options:["By flattering the crow into opening his beak","By climbing the tree","By asking politely"],answerIndex:0},emotionalMoment:{feeling:"humility",prompt:"Have you ever been flattered into doing something silly? What did you learn?"},rewardName:"Wisdom of the Fable"},"musicians-of-bremen":{title:"The Bremen Town Musicians",summary:"A donkey, dog, cat and rooster — too old for their masters — head to Bremen and discover that friendship is stronger than force.",theme:"friendship and courage",scenes:[{text:"An old donkey decided to head to Bremen to become a musician."},{text:"Along the way he met a dog, cat and rooster. Together they walked on.",dialogue:{speaker:"Donkey",line:"Come with me! In Bremen we will make music together!"}},{text:"That night they found a house with robbers inside and climbed on each other outside the window."},{text:"They all sang at once. The terrified robbers fled into the forest.",dialogue:{speaker:"Rooster",line:"Our music chases the bad guys away!"}},{text:"The four friends settled into the house, so happy together they never needed to go to Bremen."}],vocabulary:[{word:"musician",meaning:"someone who plays music",emoji:"🎵"},{word:"robber",meaning:"a thief who scares people",emoji:"😈"},{word:"together",meaning:"all with each other",emoji:"🤝"},{word:"terrified",meaning:"very, very frightened",emoji:"😱"}],miniGame:{type:"count",prompt:"How many animals go to Bremen?",answer:4,options:[3,4,5]},emotionalMoment:{feeling:"friendship",prompt:"When did friends help you be brave?"},rewardName:"Bremen Trumpet"},"pied-piper":{title:"The Pied Piper of Hamelin",summary:"A magical piper promises to solve a rat problem and teaches everyone that promises must always be kept.",theme:"honesty and promises",scenes:[{text:"The town of Hamelin was overrun with rats."},{text:"A colourful piper promised to chase all the rats away for a reward.",dialogue:{speaker:"Piper",line:"I can chase your rats. But you must keep your promise to pay."}},{text:"He played a magic melody. All the rats followed him to the river and disappeared."},{text:"The townspeople refused to pay.",dialogue:{speaker:"Mayor",line:"We will not pay you. Go away!"}},{text:"The children followed the music. That day the whole town learned that promises must be kept."}],vocabulary:[{word:"flute",meaning:"a wind instrument you blow",emoji:"🎵"},{word:"promise",meaning:"saying you will do something and really doing it",emoji:"🤝"},{word:"melody",meaning:"a sequence of notes that make music",emoji:"🎼"},{word:"reward",meaning:"something given in exchange for a service",emoji:"🏆"}],miniGame:{type:"choice",prompt:"What happens when you break a promise?",options:["Nothing","You lose the trust of others","Others are happy"],answerIndex:1},emotionalMoment:{feeling:"honest",prompt:"Have you ever kept a hard promise? How did it feel?"},rewardName:"Magic flute"},"little-match-girl":{title:"The Little Match Girl",summary:"On a cold night, a poor little girl lights matches that show her beautiful dreams of warmth and love.",theme:"hope and kindness",scenes:[{text:"On New Year's Eve in terrible cold, a little girl walked barefoot in the snow selling matches."},{text:"No one bought any. She huddled in a corner and lit a match to warm her fingers.",dialogue:{speaker:"Little girl",line:"Just one match for a little warmth..."}},{text:"In the flame she saw a big warm stove, then a table full of food."},{text:"She lit another match and saw her kind grandmother smiling at her.",dialogue:{speaker:"Grandmother",line:"I am here, dear. Come with me to a warm place."}},{text:"The next morning passers-by found the little girl asleep with a peaceful smile on her face."}],vocabulary:[{word:"match",meaning:"a small stick that makes fire when struck",emoji:"🔥"},{word:"peaceful",meaning:"calm and serene, without fear",emoji:"😌"},{word:"hope",meaning:"believing something good can happen",emoji:"🌟"},{word:"huddle",meaning:"curl up tightly to keep warm",emoji:"🤗"}],miniGame:{type:"choice",prompt:"What does the girl see in her first match flame?",options:["A big warm stove","Her grandmother","A Christmas tree"],answerIndex:0},emotionalMoment:{feeling:"hope",prompt:"What gives you hope when things are hard?"},rewardName:"Light of Hope"},"princess-pea":{title:"The Princess and the Pea",summary:"A real princess is recognised by her great sensitivity — a fun fable about being yourself.",theme:"being yourself",scenes:[{text:"A prince was looking for a real princess to marry. But how do you know if she is real?"},{text:"On a stormy night a soaking wet girl knocked and said she was a princess.",dialogue:{speaker:"Girl",line:"I am a real princess, I assure you!"}},{text:"The queen had a clever idea. She placed a tiny pea under twenty mattresses."},{text:"The next morning they asked the girl how she had slept.",dialogue:{speaker:"Girl",line:"Terribly! I felt something hard all night. I am covered in bruises!"}},{text:"Only a real princess could feel a pea through so many mattresses. The prince married her and they were very happy."}],vocabulary:[{word:"princess",meaning:"the daughter of a king or queen",emoji:"👸"},{word:"mattress",meaning:"the soft part of a bed you sleep on",emoji:"🛏️"},{word:"sensitive",meaning:"who feels things very strongly",emoji:"💝"},{word:"storm",meaning:"very bad weather with wind and rain",emoji:"⛈️"}],miniGame:{type:"count",prompt:"How many mattresses did the queen stack?",answer:20,options:[10,15,20]},emotionalMoment:{feeling:"being yourself",prompt:"What makes you unique?"},rewardName:"Crown of Sensitivity"},"wild-swans":{title:"The Wild Swans",summary:"A brave princess works in silence for years to break the spell that turned her eleven brothers into swans.",theme:"quiet courage and love",scenes:[{text:"Elise had eleven brothers turned into wild swans by a wicked stepmother's spell."},{text:"A fairy told her the secret: she had to knit eleven nettle coats without speaking a single word.",dialogue:{speaker:"Fairy",line:"One single word and your brothers stay swans forever."}},{text:"Elise knitted without stopping, even when her hands bled."},{text:"Years passed. Finally, she threw the coats over the swans.",dialogue:{speaker:"Elise",line:"My brothers! I waited so long for you!"}},{text:"The swans became her brothers again. Elise could at last speak and tell them all her love."}],vocabulary:[{word:"spell",meaning:"a magic that transforms someone",emoji:"✨"},{word:"nettle",meaning:"a plant with stinging leaves",emoji:"🌿"},{word:"knit",meaning:"to make clothes with yarn and needles",emoji:"🧶"},{word:"silence",meaning:"not saying a single word",emoji:"🤫"}],miniGame:{type:"count",prompt:"How many brothers does Elise need to save?",answer:11,options:[7,9,11]},emotionalMoment:{feeling:"determination",prompt:"What would you do for someone you love?"},rewardName:"Swan Feather"},"chevre-monsieur-seguin":{title:"The Goat of Monsieur Seguin",summary:"The little goat Blanquette wants freedom but discovers that true freedom comes with responsibility.",theme:"freedom and caution",scenes:[{text:"Monsieur Seguin had a beautiful white goat called Blanquette. But Blanquette wanted the freedom of the mountains."},{text:"Monsieur Seguin begged her to stay.",dialogue:{speaker:"M. Seguin",line:"Blanquette, stay! There is a big wolf in the mountains!"}},{text:"Blanquette did not listen. She leapt over the fence and ran happily to the mountain meadows."},{text:"All day she frolicked, ate fine grass and breathed fresh air. But in the evening, the big wolf arrived.",dialogue:{speaker:"Blanquette",line:"I will fight until dawn! I will not give up!"}},{text:"Blanquette fought bravely all night and learned that freedom also asks for caution."}],vocabulary:[{word:"goat",meaning:"a farm animal with horns that gives milk",emoji:"🐐"},{word:"frolic",meaning:"to jump and run freely in play",emoji:"🦘"},{word:"dawn",meaning:"the first moment of morning when the sun rises",emoji:"🌅"},{word:"freedom",meaning:"being able to do what you want",emoji:"🕊️"}],miniGame:{type:"choice",prompt:"Why does Monsieur Seguin want to keep Blanquette?",options:["For her milk","To protect her from the wolf","So he is not lonely"],answerIndex:1},emotionalMoment:{feeling:"freedom and caution",prompt:"How can you be free and safe at the same time?"},rewardName:"Mountain Bell"},sinbad:{title:"Sinbad the Sailor",summary:"The brave sailor Sinbad travels the seas of the world and always returns wiser than he left.",theme:"courage and wisdom",scenes:[{text:"Sinbad was a rich merchant from Baghdad who loved adventures. He made seven great voyages."},{text:"On his first voyage his ship ran aground on what seemed like an island — but it was a sleeping giant fish!",dialogue:{speaker:"Sinbad",line:"This is no island... it is a living creature! Flee!"}},{text:"On every voyage Sinbad faced new dangers. He overcame them all with his wits."},{text:"He always brought back treasures, but above all stories and wisdom.",dialogue:{speaker:"Sinbad",line:"True riches are not jewels but what you learn on the journey."}},{text:"Every voyage taught him something new about the world and about himself."}],vocabulary:[{word:"sailor",meaning:"someone who travels and works on the sea",emoji:"⚓"},{word:"run aground",meaning:"when a ship stops on the seabed or a beach",emoji:"🏖️"},{word:"danger",meaning:"a great threat",emoji:"⚠️"},{word:"wisdom",meaning:"knowledge gained through experience",emoji:"🦉"}],miniGame:{type:"count",prompt:"How many great voyages did Sinbad make?",answer:7,options:[5,7,9]},emotionalMoment:{feeling:"adventure and wisdom",prompt:"What did you learn during a trip or new experience?"},rewardName:"Voyager's Compass"},"tinder-box":{title:"The Tinderbox",summary:"A soldier finds a magic tinderbox and learns that a generous heart is the real magic.",theme:"generosity and friendship",scenes:[{text:"A soldier returning from war met an old witch who offered him a deal: fetch a tinderbox from a hollow tree."},{text:"Inside the tree he found three enormous dogs guarding chests full of gold coins.",dialogue:{speaker:"Soldier",line:"They obey me as long as I have the tinderbox!"}},{text:"He became rich and generous — he gave food to everyone in need."},{text:"With the tinderbox the dogs appeared and granted his wishes, but he always asked for kind things.",dialogue:{speaker:"Soldier",line:"Bring food for the whole village!"}},{text:"Through his kindness the soldier won the love of everyone. The real magic was a generous heart."}],vocabulary:[{word:"tinderbox",meaning:"a small object that makes fire",emoji:"🔥"},{word:"generous",meaning:"happy to give and share with others",emoji:"🎁"},{word:"witch",meaning:"a person who does magic",emoji:"🧙"},{word:"chest",meaning:"a large strong box for treasure",emoji:"📦"}],miniGame:{type:"count",prompt:"How many magic dogs guard the treasures?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"generosity",prompt:"Have you ever shared something you loved? How did it feel?"},rewardName:"Tinderbox of Kindness"},"blue-bird":{title:"The Blue Bird",summary:"Two children search the world for the Blue Bird of Happiness and discover that happiness is often close to home.",theme:"happiness and gratitude",scenes:[{text:"Tyltyl and Mytyl, two poor but cheerful children, lived with their parents in a small house at the edge of the forest."},{text:"The fairy Berylune appeared and asked them to find the Blue Bird of Happiness for her sick granddaughter.",dialogue:{speaker:"Fairy Berylune",line:"Go and find the Blue Bird! It is somewhere in the world."}},{text:"The children travelled far and wide. Everywhere the blue birds they found died or changed colour."},{text:"Disappointed, they returned home.",dialogue:{speaker:"Tyltyl",line:"We searched everywhere... does the Blue Bird even exist?"}},{text:"Back home, Tyltyl noticed that his dove — which he had always had — had beautiful blue feathers. Happiness was there all along."}],vocabulary:[{word:"happiness",meaning:"a feeling of deep joy and satisfaction",emoji:"😊"},{word:"gratitude",meaning:"being thankful and content for what you have",emoji:"🙏"},{word:"memory",meaning:"an image or feeling kept in your mind",emoji:"💭"},{word:"disappointed",meaning:"sad because something did not work out",emoji:"😔"}],miniGame:{type:"choice",prompt:"Where does Tyltyl finally find the Blue Bird?",options:["In a distant castle","In his own home","At the bottom of the sea"],answerIndex:1},emotionalMoment:{feeling:"gratitude",prompt:"What beautiful things do you already have that make you happy?"},rewardName:"Feather of Happiness"},"renart-goupil":{title:"Reynard the Fox",summary:"The cunning fox Reynard uses his intelligence in every situation — and learns that even the cleverest can be outsmarted.",theme:"intelligence and humility",scenes:[{text:"In the great forest of the Middle Ages lived Reynard the Fox, the cleverest of all animals."},{text:"One day Reynard stole a chicken from Chanticleer the rooster. But Chanticleer had a plan.",dialogue:{speaker:"Chanticleer",line:"Reynard, you are so handsome! Show me how you sing when you are proud!"}},{text:"Reynard, flattered, opened his mouth to sing — and the chicken escaped!"},{text:"He tried to steal the cheese from Isengrim the wolf. This time the wolf was one step ahead.",dialogue:{speaker:"Isengrim",line:"You are not the only one who can be clever, Reynard!"}},{text:"Reynard learned that even the cleverest fox can be caught. Honesty is sometimes better than trickery."}],vocabulary:[{word:"cunning",meaning:"very good at tricking others",emoji:"🦊"},{word:"flattered",meaning:"pleased by too many compliments",emoji:"😏"},{word:"honest",meaning:"who tells the truth and does not cheat",emoji:"✅"},{word:"outsmart",meaning:"to be cleverer than someone else",emoji:"🎭"}],miniGame:{type:"choice",prompt:"How does Chanticleer get his chicken back?",options:["By running faster","By flattering Reynard into opening his mouth","By calling other animals"],answerIndex:1},emotionalMoment:{feeling:"humility",prompt:"Have you ever learned something important from making a mistake?"},rewardName:"Fox's Tail"}},s={"snow-white":{title:"Blancanieves",summary:"Una dulce princesa con la piel blanca como la nieve encuentra un hogar junto a siete pequenos amigos bondadosos y aprende que los verdaderos amigos siempre cuidan los unos de los otros.",theme:"bondad y amistad",scenes:[{text:"Hace mucho tiempo, nacio una pequena princesa con la piel blanca como la nieve. Todo el mundo la llamaba Blancanieves."},{text:"Una reina celosa tenia un espejo magico y le hacia la misma pregunta cada dia.",dialogue:{speaker:"Reina",line:"Espejito, espejito, quien es la mas bondadosa y hermosa de todas?"}},{text:"Blancanieves camino hasta el corazon del bosque. Siete pequenos mineros bondadosos la acogieron en su acogedora cabana.",dialogue:{speaker:"Un minero",line:"Estas a salvo aqui, pequeña amiga. Ven a descansar."}},{text:"La reina la engano con una manzana brillante, y Blancanieves cayo en un sueno muy, muy profundo."},{text:"Una amiga carinosa la desperto con un gesto muy suave. Blancanieves sonrio, y todos celebraron a su valiente amiga.",dialogue:{speaker:"Blancanieves",line:"Nunca me abandonasteis. Gracias, mis amigos!"}}],vocabulary:[{word:"la mas bella",meaning:"la persona mas bondadosa y mas bonita",emoji:"🌷"},{word:"celosa",meaning:"enfadada porque quiere lo que tiene otra persona",emoji:"😠"},{word:"cabana",meaning:"una casita pequena y acogedora",emoji:"🏡"},{word:"acoger",meaning:"hacer que alguien se sienta feliz de haber llegado",emoji:"🤗"}],miniGame:{type:"count",prompt:"Cuantos pequenos mineros bondadosos acogieron a Blancanieves?",answer:7,options:[6,7,8]},emotionalMoment:{feeling:"rodeada y protegida",prompt:"Los amigos de Blancanieves velaban por ella. Quien vela por ti?"},rewardName:"Espejo bondadoso"},cinderella:{title:"Cenicienta",summary:"Una chica trabajadora con un gran corazon recibe un poco de ayuda de una amiga magica y descubre que ser amable es una magia en si misma.",theme:"esperanza y bondad",scenes:[{text:"Cenicienta hacia todas las tareas y nunca perdia su dulce sonrisa, aunque los demas fueran crueles."},{text:"Una noche, se anuncio un gran baile, pero Cenicienta no tenia nada que ponerse.",dialogue:{speaker:"Cenicienta",line:"Si al menos pudiera ir a bailar, solo una vez."}},{text:"Aparecio un hada bondadosa y, con un toque de su varita, convirtio una calabaza en una carroza.",dialogue:{speaker:"Hada amiga",line:"Vuelve antes de medianoche, querida — entonces la magia se acaba."}},{text:"En el baile, Cenicienta bailo y rio. Pero cuando el reloj empezo a sonar, tuvo que correr."},{text:"El zapatito le quedaba perfectamente. Su bondad siempre habia sido visible, y la alegria lleno sus dias.",dialogue:{speaker:"Cenicienta",line:"Ser amable no cuesta nada."}}],vocabulary:[{word:"tareas",meaning:"pequenos trabajos para ayudar en casa",emoji:"🧹"},{word:"carroza",meaning:"un coche tirado para transportar a personas",emoji:"🛞"},{word:"medianoche",meaning:"las doce de la noche",emoji:"🕛"},{word:"dulce",meaning:"tierno, tranquilo y amable",emoji:"🕊️"}],miniGame:{type:"count",prompt:"A que hora debe volver Cenicienta? Cuenta los golpes del reloj!",answer:12,options:[10,11,12]},emotionalMoment:{feeling:"llena de esperanza",prompt:"Incluso en los dias dificiles, Cenicienta seguia siendo amable. Que te ayuda a mantener la esperanza?"},rewardName:"Zapatilla de cristal"},"little-red-riding-hood":{title:"Caperucita Roja",summary:"Una valiente nina con una caperuza roja va a casa de su abuela y aprende a escuchar sus sabios instintos durante el camino.",theme:"escuchar y mantenerse a salvo",scenes:[{text:"Una ninita llevaba una brillante caperuza roja a todas partes, asi que todo el mundo la llamaba Caperucita Roja."},{text:"Su mama le dio una cesta con pan para la abuela.",dialogue:{speaker:"Mama",line:"Quédate en el camino y todo ira bien."}},{text:"En el bosque, un lobo astuto hizo muchas preguntas. Caperucita sintio que algo era extrano y siguio caminando.",dialogue:{speaker:"Caperucita",line:"No tengo que responderte. Se lo dire a un adulto."}},{text:"Un amable lenador la escucho y camino con ella. Juntos llegaron a casa de la abuela."},{text:"La abuela estaba a salvo, y Caperucita tambien. Compartieron pan caliente y rieron toda la tarde.",dialogue:{speaker:"Abuela",line:"Escuchaste tus sabios instintos. Estoy muy orgullosa de ti."}}],vocabulary:[{word:"camino",meaning:"una senda que te muestra por donde ir a salvo",emoji:"🛤️"},{word:"cesta",meaning:"un portador con asa para llevar cosas",emoji:"🧺"},{word:"astuto",meaning:"alguien que usa trucos para enganarte",emoji:"🦊"},{word:"lenador",meaning:"una persona que trabaja entre los arboles",emoji:"🪓"}],miniGame:{type:"choice",prompt:"Un desconocido le pregunta a Caperucita adonde va. Cual es la eleccion segura?",options:["Contarle todo","Seguir caminando y avisar a un adulto","Seguirle entre los arboles"],answerIndex:1},emotionalMoment:{feeling:"a salvo",prompt:"Caperucita escucho su extrana sensacion. Cuando te ha ayudado un instinto a mantenerte a salvo?"},rewardName:"Caperuza roja"},"hansel-and-gretel":{title:"Hansel y Gretel",summary:"Un hermano y una hermana se pierden en el bosque y usan un plan astuto, y su trabajo en equipo, para llegar sanos y salvos a casa.",theme:"astucia y permanecer juntos",scenes:[{text:"Hansel y Gretel se adentraron en el gran bosque cogidos de la mano para no perderse."},{text:"El astuto Hansel fue dejando caer pequenas piedrecitas blancas y brillantes, una a una, para marcar el camino de vuelta.",dialogue:{speaker:"Hansel",line:"Estas piedrecitas brillaran y nos llevaran a casa."}},{text:"Encontraron una casita hecha de dulces, pero una vieja astuta vivia alli."},{text:"Los ninos eran demasiado listos para dejarse enganar. Se cogieron de la mano y salieron de puntillas.",dialogue:{speaker:"Gretel",line:"Rapido — juntos somos mas valientes que solos."}},{text:"Las brillantes piedrecitas destellaron a la luz de la luna y los llevaron directamente a casa, hacia un calido abrazo."}],vocabulary:[{word:"piedrecitas",meaning:"pequenas y lisas piedritas",emoji:"🪨"},{word:"astuto",meaning:"bueno para pensar ideas inteligentes",emoji:"💡"},{word:"de puntillas",meaning:"caminar muy despacio sobre los dedos de los pies",emoji:"🦶"},{word:"juntos",meaning:"el uno con el otro, codo con codo",emoji:"🤝"}],miniGame:{type:"sequence",prompt:"Pon el plan astuto de Hansel en el orden correcto!",steps:["Dejar caer las piedrecitas brillantes","Seguir el rastro que centellea","Encontrar el camino a casa"]},emotionalMoment:{feeling:"valientes juntos",prompt:"Los ninos eran mas valientes en equipo. Quien te hace mas valiente?"},rewardName:"Piedrecita brillante"},rapunzel:{title:"Rapunzel",summary:"Una nina amable con un pelo muy largo vive en una alta torre y aprende que la paciencia y un corazon lleno de esperanza pueden abrir cualquier puerta.",theme:"paciencia y esperanza",scenes:[{text:"En lo alto de una gran torre vivia Rapunzel, una nina con la trenza dorada mas larga del mundo."},{text:"Cada dia, Rapunzel cantaba a los pajaros. Su dulce cancion flotaba por todo el bosque.",dialogue:{speaker:"Rapunzel",line:"Algun dia vere el mundo de ahi abajo, bajo los arboles."}},{text:'Un amable viajero escucho su cancion y le grito: "Tu musica hace sonreir a todo el bosque!"',dialogue:{speaker:"Viajero",line:"Tu musica hace sonreir a todo el bosque!"}},{text:"Se hicieron amigos. Dia tras dia, con paciencia, pensaron en una forma inteligente de bajar."},{text:"Por fin, Rapunzel puso el pie en la hierba suave y giro bajo el sol, libre y feliz.",dialogue:{speaker:"Rapunzel",line:"Esperar fue dificil, pero la esperanza me mantuvo fuerte."}}],vocabulary:[{word:"torre",meaning:"un edificio muy alto y estrecho",emoji:"🗼"},{word:"trenza",meaning:"pelo entrelazado formando una larga cuerda",emoji:"💇"},{word:"paciencia",meaning:"esperar con calma sin rendirse",emoji:"⏳"},{word:"prado",meaning:"un campo de hierba lleno de flores",emoji:"🌼"}],miniGame:{type:"find",prompt:"Encuentra lo que uso Rapunzel para bajar a salvo.",target:"la escalera de trenza dorada",decoys:["una cometa de papel","una cuchara de madera","una tacita"]},emotionalMoment:{feeling:"paciente",prompt:"Rapunzel espero con esperanza. Que cosa bonita has esperado durante mucho tiempo?"},rewardName:"Trenza dorada"},"the-ugly-duckling":{title:"El Patito Feo",summary:"Un pajarito que se siente diferente a los demas crece y descubre que siempre fue maravilloso exactamente como era.",theme:"pertenecer y quererse a uno mismo",scenes:[{text:"En un estanque soleado, un pajarito no se parecia a sus hermanos y hermanas."},{text:"Los otros pajaros se burlaban de el, y en el fondo se sentia solo y muy triste.",dialogue:{speaker:"Pajarito",line:"Ojala alguien me dejara jugar tambien."}},{text:'Una rana amable se acerco saltando y se sento a su lado. "Eres bienvenido conmigo", dijo.',dialogue:{speaker:"Rana",line:"Eres bienvenido conmigo, amigo mio."}},{text:"Pasaron las estaciones. Una manana luminosa, el pajarito vio su cara en el agua tranquila."},{text:"Se habia convertido en un hermoso cisne! Siempre habia sido especial: simplemente el mismo.",dialogue:{speaker:"Cisne",line:"No necesitaba cambiar. Solo necesitaba crecer."}}],vocabulary:[{word:"estanque",meaning:"una pequena extension de agua tranquila",emoji:"💧"},{word:"solo",meaning:"triste porque te sientes completamente solo",emoji:"🥺"},{word:"reflejo",meaning:"la imagen que ves en el agua tranquila",emoji:"🪞"},{word:"cisne",meaning:"un gran pajaro de agua blanco y elegante",emoji:"🦢"}],miniGame:{type:"choice",prompt:"Un nuevo amigo se siente excluido. Que cosa amable puedes decirle?",options:["No perteneces aqui","Puedes jugar con nosotros!","Vete"],answerIndex:1},emotionalMoment:{feeling:"pertenezco aqui",prompt:"El pajarito era especial tal como era. Que te hace ser un maravilloso tu?"},rewardName:"Cisne suave"},"the-little-mermaid":{title:"La Sirenita",summary:"Una joven sirena curiosa tiene el valor de explorar un mundo nuevo y aprende que un corazon bondadoso y generoso brilla mas que cualquier cosa.",theme:"valentia y buen corazon",scenes:[{text:"En el fondo de las olas vivia una joven sirena, la mas pequena de seis hermanas."},{text:"Le encantaba nadar hasta la superficie y contemplar el luminoso mundo sobre el agua.",dialogue:{speaker:"Sirena",line:"El mundo de ahi arriba esta lleno de cosas que quiero aprender!"}},{text:"Una noche de tormenta, con valentia, ayudo a un marinero a llegar a la orilla a salvo."},{text:"No se quedo para ser agradecida. Ayudar a alguien llenaba su corazon de calor.",dialogue:{speaker:"Sirena",line:"Ayude por bondad, no para recibir las gracias."}},{text:"De vuelta en casa, conto su valiente historia, y su buen corazon hizo brillar todo el mar."}],vocabulary:[{word:"sirena",meaning:"una chica del mar imaginaria, con cola de pez",emoji:"🧜"},{word:"olas",meaning:"el agua que sube y baja en el mar",emoji:"🌊"},{word:"valiente",meaning:"hacer algo dificil aunque de miedo",emoji:"💪"},{word:"generosa",meaning:"feliz de dar y ayudar a los demas",emoji:"💝"}],miniGame:{type:"count",prompt:"Cuantas hermanas mayores tenia la Sirenita?",answer:6,options:[5,6,7]},emotionalMoment:{feeling:"de gran corazon",prompt:"La sirena ayudo solo por bondad. Cuando has ayudado sin que nadie te lo pidiera?"},rewardName:"Perla del mar"},"the-snow-queen":{title:"La Reina de las Nieves",summary:"Cuando el corazon de su mejor amigo se vuelve frio, una fiel nina llamada Gerda viaja lejos entre la nieve para calentarlo con amor.",theme:"amistad fiel",scenes:[{text:"Gerda y Kai eran los mejores amigos y cultivaban rosas juntos cerca de su ventana."},{text:"Un minusculo cristal de hielo toco el corazon de Kai, y el se volvio frio y distante.",dialogue:{speaker:"Gerda",line:"Espera... adonde vas, Kai?"}},{text:"La valiente Gerda no se rindio. Partio a traves de la nieve a buscar a su amigo.",dialogue:{speaker:"Gerda",line:"Te encontrare, Kai. Los amigos no se rinden."}},{text:"Encontro a Kai en un palacio de hielo, sentado, inmovil y frio como una piedra."},{text:"Gerda lo abrazo y lagrimas calidas cayeron. El hielo se derrrtio, y Kai sonrio y lo recordo todo.",dialogue:{speaker:"Kai",line:"Has venido hasta aqui por mi. Gracias, Gerda."}}],vocabulary:[{word:"escarcha",meaning:"una fina capa de hielo que se forma cuando hace mucho frio",emoji:"🌨️"},{word:"fiel",meaning:"siempre estar ahi para tus amigos",emoji:"🤲"},{word:"palacio",meaning:"una casa muy grande y magnifica",emoji:"🏰"},{word:"derretirse",meaning:"pasar del hielo al agua con el calor",emoji:"💧"}],miniGame:{type:"choice",prompt:"Como derrrtio Gerda el hielo en el corazon de Kai?",options:["Con un gran fuego","Con lagrimas calidas y un abrazo","Con un martillo"],answerIndex:1},emotionalMoment:{feeling:"fiel",prompt:"Gerda nunca abandono a su amigo. Como le muestras a un amigo que te importa?"},rewardName:"Rosa calida"},"puss-in-boots":{title:"El Gato con Botas",summary:"Un gato listo con unas botas preciosas usa su ingenio y su leal corazon para ayudar a su bondadoso amigo a encontrar la felicidad.",theme:"astucia y lealtad",scenes:[{text:"Un gato listo se puso unas botas preciosas y un sombrero con pluma, listo para la aventura."},{text:"Su amigo era pobre pero bondadoso, asi que el gato penso en un plan astuto para ayudarle.",dialogue:{speaker:"El Gato",line:"Confía en mi, amigo. Una idea lista esta en camino!"}},{text:"El gato saludo al rey con cortesia y le ofrecio regalos, haciendo sonreir a todo el mundo."},{text:"Con ingenio en lugar de trucos, el gato ayudo a su amigo a ganar un gran castillo junto al rio.",dialogue:{speaker:"El Gato",line:"Las buenas ideas abren mas puertas que los grandes rugidos."}},{text:"Su amigo fue feliz por fin, y el gato se acurruco junto al fuego, el gato mas fiel de todos."}],vocabulary:[{word:"listo",meaning:"bueno para encontrar ideas ingeniosas",emoji:"🧠"},{word:"botas",meaning:"zapatos que suben alto por las piernas",emoji:"🥾"},{word:"cortes",meaning:"amable y gentil con sus palabras",emoji:"🙏"},{word:"leal",meaning:"siempre estar ahi para tus amigos",emoji:"🤝"}],miniGame:{type:"sequence",prompt:"Pon el plan astuto del Gato en el orden correcto!",steps:["Ponerse las botas preciosas","Saludar al rey con cortesia","Ayudar a su amigo a ganar el dia"]},emotionalMoment:{feeling:"servicial",prompt:"El Gato uso ideas listas para ayudar a un amigo. De que forma astuta has ayudado tu a alguien?"},rewardName:"Botas preciosas"},pinocchio:{title:"Pinocho",summary:"Un muneco de madera que suena con ser un nino de verdad aprende que decir la verdad es lo que hace crecer un buen corazon.",theme:"honestidad",scenes:[{text:"Habia una vez un pequeno muneco de madera llamado Pinocho, que sonaba con convertirse en un nino de verdad."},{text:"Cada vez que Pinocho decia una mentira, su nariz crecía como una rama.",dialogue:{speaker:"Pinocho",line:"No fui yo! Te lo prometo!"}},{text:"Su amigo el grillo intentaba ensenarle a decir siempre la verdad.",dialogue:{speaker:"Grillo",line:"Decir la verdad te hara sentir ligero como una pluma."}},{text:"Pinocho cometio un gran error y se perdio. Aprendio entonces que la honestidad era su unica guia."},{text:"Cuando Pinocho dijo por fin la verdad, su corazon crecio, y su mayor deseo se hizo realidad.",dialogue:{speaker:"Pinocho",line:"La verdad es la magia mas poderosa de todas."}}],vocabulary:[{word:"muneco",meaning:"una muneca que se hace mover",emoji:"🎭"},{word:"verdad",meaning:"decir exactamente lo que ha pasado",emoji:"✅"},{word:"mentira",meaning:"decir algo que no es cierto",emoji:"❌"},{word:"honesto",meaning:"alguien que siempre dice la verdad",emoji:"🌟"}],miniGame:{type:"choice",prompt:"Cuando se alarga la nariz de Pinocho?",options:["Cuando dice la verdad","Cuando dice una mentira","Cuando canta una cancion"],answerIndex:1},emotionalMoment:{feeling:"honesto",prompt:"Decir la verdad hizo sentir a Pinocho ligero. Como te sientes tu cuando dices la verdad?"},rewardName:"Grillo de la verdad"},"peter-pan":{title:"Peter Pan",summary:"Un nino que nunca crece lleva a nuevos amigos a una aventura voladora donde los pensamientos felices y un poco de valentia te llevan a cualquier parte.",theme:"imaginacion y valentia",scenes:[{text:"En una habitacion llena de estrellas, un nino llamado Peter Pan enseno a los ninos a volar."},{text:"Peter le dijo a Wendy el secreto: habia que pensar en algo muy feliz.",dialogue:{speaker:"Peter Pan",line:"Piensa en tu cosa mas feliz — y hop, te elevas!"}},{text:"Juntos volaron hacia el Pais de Nunca Jamas, una isla magica llena de aventuras."},{text:"Incluso frente al malvado capitan, Peter no tuvo miedo. Afronto el peligro con una gran sonrisa.",dialogue:{speaker:"Peter Pan",line:"Ser valiente es intentarlo de todas formas."}},{text:"Los ninos volvieron a casa con recuerdos en el corazon y un poco de magia para siempre."}],vocabulary:[{word:"habitacion",meaning:"la habitacion donde duermes y suenas",emoji:"🛏️"},{word:"sombra",meaning:"la forma oscura que hace tu cuerpo en el suelo",emoji:"👤"},{word:"imaginar",meaning:"crear cosas bonitas dentro de tu cabeza",emoji:"💭"},{word:"valentia",meaning:"intentarlo aunque tengas miedo",emoji:"💪"}],miniGame:{type:"choice",prompt:"Que ayudo a los ninos a volar?",options:["Pensamientos felices y polvo de hada","Botas pesadas","Gritar muy fuerte"],answerIndex:0},emotionalMoment:{feeling:"valiente",prompt:"Peter dice que ser valiente es intentarlo de todas formas. Que cosa valiente te gustaria intentar?"},rewardName:"Polvo de hada"},"alice-in-wonderland":{title:"Alicia en el Pais de las Maravillas",summary:"Una nina curiosa sigue a un conejo apresurado a un mundo al reves y aprende que hacer preguntas es una especie de magia.",theme:"curiosidad",scenes:[{text:"Alicia vio un conejo blanco apresurado que saltaba a una madriguera y, muy curiosa, lo siguio."},{text:"Cayo por un largo pasillo magico y encontro una pequenísima puerta que daba a un jardin.",dialogue:{speaker:"Alicia",line:"Que raro! Me pregunto que pasa aqui."}},{text:"Alicia bebio un pequeno frasco y se encogio, luego comio un pastel y crecio muy rapido.",dialogue:{speaker:"Alicia",line:"Las preguntas son la llave de todas las maravillas!"}},{text:"Conocio a un gato sonriente, una reina enfadada y un sombrerero muy loco."},{text:"Alicia se desperto y sonrio. Hacer preguntas la habia llevado al mas bonito de los suenos.",dialogue:{speaker:"Alicia",line:"La curiosidad es la aventura mas grande."}}],vocabulary:[{word:"curiosa",meaning:"alguien que ama descubrir cosas nuevas",emoji:"🔍"},{word:"madriguera",meaning:"un tunel excavado en la tierra por un animal",emoji:"🕳️"},{word:"encogerse",meaning:"hacerse mas pequeno",emoji:"🔻"},{word:"maravilla",meaning:"algo increible y muy sorprendente",emoji:"😲"}],miniGame:{type:"sequence",prompt:"Pon la aventura de Alicia en el orden correcto!",steps:["Beber el frasco y encogerse","Comer el pastel y crecer","Encontrar la pequena puerta del jardin"]},emotionalMoment:{feeling:"curiosa",prompt:"A Alicia le encantaba hacer preguntas. De que tienes curiosidad hoy?"},rewardName:"Reloj curioso"},"the-wizard-of-oz":{title:"El Mago de Oz",summary:"Una nina y tres nuevos amigos siguen un camino dorado y descubren que los dones que buscaban estaban dentro de ellos desde el principio.",theme:"ya tienes lo que necesitas",scenes:[{text:"Un gran torbellino llevo a Dorothy y a su pequeno perro Toto al magico pais de Oz."},{text:"En el camino dorado, Dorothy conocio a un espantapajaros, un hombre de hojalata y un leon.",dialogue:{speaker:"Espantapajaros",line:"Solo quiero un cerebro listo!"}},{text:"Juntos caminaron hacia la Ciudad Esmeralda para encontrar al gran Mago.",dialogue:{speaker:"Dorothy",line:"Si estamos juntos, podemos hacer cualquier cosa."}},{text:"El Mago les revelo un gran secreto: ya tenian todo lo que deseaban."},{text:"Dorothy golpeo tres veces sus zapatillas y volvio a casa. Cada uno habia encontrado su don.",dialogue:{speaker:"Dorothy",line:"No hay ningun lugar como el hogar."}}],vocabulary:[{word:"torbellino",meaning:"un viento muy fuerte que gira en redondo",emoji:"🌪️"},{word:"espantapajaros",meaning:"un muneco grande de paja para espantar a los pajaros",emoji:"🌾"},{word:"valentia",meaning:"seguir adelante aunque tengas miedo",emoji:"💪"},{word:"viaje",meaning:"un largo camino o aventura hacia un lugar nuevo",emoji:"🗺️"}],miniGame:{type:"choice",prompt:"Cual de los amigos ya tenia valentia desde el principio?",options:["El espantapajaros","El hombre de hojalata","El leon"],answerIndex:2},emotionalMoment:{feeling:"capaz",prompt:"Los amigos ya tenian sus dones dentro de ellos. Que don tienes ya en ti?"},rewardName:"Zapatillas brillantes"},"robin-hood":{title:"Robin Hood",summary:"Un amable arquero del bosque verde comparte con quienes tienen muy poco y ensena a sus amigos que la justicia hace a todos mas felices.",theme:"justicia y generosidad",scenes:[{text:"En un gran bosque verde vivia Robin Hood, el mejor arquero del pais."},{text:"Vio que mucha gente era muy pobre mientras que otros lo tenian todo.",dialogue:{speaker:"Robin",line:"Compartir es el mejor de los regalos."}},{text:"Con sus alegres amigos, Robin diseno un plan para ayudar a quienes estaban en necesidad.",dialogue:{speaker:"Pequeno Juan",line:"Juntos somos la fuerza del bosque!"}},{text:"Robin repartio lo que la gente necesitaba, y las sonrisas florecieron por todas partes."},{text:"El bosque vibro de felicidad. Robin habia aprendido que la generosidad es la verdadera victoria.",dialogue:{speaker:"Robin",line:"La generosidad hace a todos mas ricos."}}],vocabulary:[{word:"arquero",meaning:"alguien que dispara flechas con un arco",emoji:"🎯"},{word:"bosque",meaning:"un gran lugar lleno de arboles y animales",emoji:"🌳"},{word:"justo",meaning:"tratar a todo el mundo de la misma manera",emoji:"⚖️"},{word:"generoso",meaning:"que le gusta dar y compartir",emoji:"🎁"}],miniGame:{type:"choice",prompt:"Robin Hood compartia con personas que estaban...",options:["hambrientas y necesitadas","ya muy ricas","siendo crueles con otros"],answerIndex:0},emotionalMoment:{feeling:"justo",prompt:"A Robin le encantaba compartir. Que podrias compartir para hacer sonreir a un amigo?"},rewardName:"Arco amistoso"},goldilocks:{title:"Ricitos de Oro",summary:"Una nina curiosa entra en la acogedora cabana de los osos y aprende que es mejor pedir permiso primero y cuidar las cosas de los demas.",theme:"respeto a los demas",scenes:[{text:"Una ninita con rizos dorados paseaba por el bosque cuando encontro una bonita cabana."},{text:"Entro y probo tres cuencos de gachas. El del osito era perfecto.",dialogue:{speaker:"Ricitos de Oro",line:"Oh! Este cuenco es perfecto, ni demasiado caliente ni demasiado frio!"}},{text:"Probo tres sillas y luego tres camas. Se quedo dormida en la mas acogedora."},{text:"Los tres osos volvieron y encontraron su casa desordenada.",dialogue:{speaker:"Osito",line:"Alguien ha comido de mi cuenco!"}},{text:"Ricitos de Oro se desperto, pidio perdon y aprendio que pedir primero es la educacion mas dulce.",dialogue:{speaker:"Ricitos de Oro",line:"Perdon. Siempre pedire permiso antes de entrar."}}],vocabulary:[{word:"gachas",meaning:"una comida caliente y suave, como los cereales del desayuno",emoji:"🥣"},{word:"cabana",meaning:"una casita acogedora en el bosque",emoji:"🏡"},{word:"respeto",meaning:"cuidar las cosas y los sentimientos de los demas",emoji:"🙏"},{word:"perdon",meaning:"lo que dices cuando sientes haber hecho algo mal",emoji:"💙"}],miniGame:{type:"count",prompt:"Cuantos osos vivian en la acogedora cabana?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"respetuosa",prompt:"Ricitos de Oro aprendio a pedir primero. Cuando es amable pedir permiso antes de coger algo prestado?"},rewardName:"Cuenco perfecto"},"three-little-pigs":{title:"Los Tres Cerditos",summary:"Tres cerditos construyen tres casas diferentes y aprenden que un trabajo cuidadoso y aplicado mantiene a todos a salvo y calentitos.",theme:"trabajo y organizacion",scenes:[{text:"Tres cerditos se fueron al mundo a construir sus casas."},{text:"El primero construyo rapidamente una casa de paja. El segundo, una casa de madera.",dialogue:{speaker:"Primer cerdito",line:"Rapido y listo! Quiero ir a jugar!"}},{text:"El tercer cerdito trabajo duro y construyo ladrillo a ladrillo una casa solida de ladrillos.",dialogue:{speaker:"Tercer cerdito",line:"Me tomo mi tiempo para que mi casa sea solida."}},{text:"El gran lobo malo soplo sobre las casas de paja y madera, y se derrumbaron."},{text:"Pero la casa de ladrillos siguio firme. Los tres cerditos estaban a salvo, y todos aprendieron que trabajar con cuidado protege.",dialogue:{speaker:"Tercer cerdito",line:"Un buen trabajo lleva tiempo, pero merece la pena!"}}],vocabulary:[{word:"paja",meaning:"tallos secos de plantas, faciles de romper",emoji:"🌾"},{word:"ladrillos",meaning:"bloques de tierra cocida muy solidos",emoji:"🧱"},{word:"resistente",meaning:"muy solido, no facil de romper",emoji:"💪"},{word:"planificar",meaning:"pensar antes de empezar algo",emoji:"📋"}],miniGame:{type:"count",prompt:"Cuantos cerditos construyeron casas?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"orgulloso de mi trabajo",prompt:"El tercer cerdito trabajo duro y se mantuvo a salvo. En que has trabajado duro tu?"},rewardName:"Ladrillo solido"},aladdin:{title:"Aladino",summary:"Un nino ordinario pero bondadoso encuentra una lampara magica y aprende que lo que deseas importa menos que el bien que haces por los demas.",theme:"honestidad y corazon humilde",scenes:[{text:"En un animado mercado vivia Aladino, un nino pobre con un corazon de oro."},{text:"Encontro una vieja lampara y, al frotarla, aparecio un gran genio!",dialogue:{speaker:"Genio",line:"Te concedo tres deseos. Elige con cuidado!"}},{text:"Aladino deseo primero ayudar a su familia, luego a la gente pobre de su barrio.",dialogue:{speaker:"Aladino",line:"Quiero que nadie en este mercado pase hambre."}},{text:"Su humildad y generosidad le ganaron amigos de verdad y mucha felicidad."},{text:"Aladino aprendio que los mejores deseos son los que uno pide para los demas.",dialogue:{speaker:"Aladino",line:"Un corazon generoso es el mas grande de los tesoros."}}],vocabulary:[{word:"mercado",meaning:"un lugar animado donde la gente vende y compra",emoji:"🏪"},{word:"lampara",meaning:"un objeto que da luz o guarda un genio",emoji:"🪔"},{word:"humilde",meaning:"alguien que no presume de si mismo",emoji:"🙏"},{word:"deseo",meaning:"algo que quieres muchísimo",emoji:"⭐"}],miniGame:{type:"count",prompt:"Cuantos deseos le dio el genio a Aladino?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"generoso",prompt:"Aladino deseo ayudar a los demas. Si tuvieras un deseo bondadoso, cual seria?"},rewardName:"Lampara de los deseos"},"ali-baba":{title:"Ali Baba",summary:"Un dulce lenador descubre una cueva secreta y aprende que ser honesto y prudente vale mucho mas que ser codicioso.",theme:"la honestidad antes que la codicia",scenes:[{text:"Ali Baba era un dulce lenador que vivia de manera sencilla y contenta."},{text:"Un dia en el bosque, oyo a unos ladrones decir las palabras magicas frente a una gran roca.",dialogue:{speaker:"Ladrones",line:"Abrete, Sesamo!"}},{text:"Ali Baba entro en la cueva y vio tesoros deslumbrantes de todos los colores.",dialogue:{speaker:"Ali Baba",line:"Tomare solo lo que necesitamos, nada mas."}},{text:"Su codicioso hermano tomo demasiado y fue sorprendido por los ladrones. Ali Baba entendio la leccion."},{text:"Ali Baba compartio su buena fortuna con los demas y vivio de manera sencilla y feliz.",dialogue:{speaker:"Ali Baba",line:"Tener suficiente y ser honesto es la verdadera riqueza."}}],vocabulary:[{word:"cueva",meaning:"una gran cavidad natural en la roca",emoji:"🕳️"},{word:"tesoro",meaning:"una gran cantidad de oro y cosas valiosas",emoji:"💎"},{word:"codicioso",meaning:"alguien que siempre quiere mas de lo que necesita",emoji:"😤"},{word:"suficiente",meaning:"justo lo que uno necesita, ni mas ni menos",emoji:"✅"}],miniGame:{type:"choice",prompt:"Cuales son las palabras magicas que abren la cueva?",options:["Abrete, Sesamo!","Cierra la puerta!","Buenos dias!"],answerIndex:0},emotionalMoment:{feeling:"contento",prompt:"Ali Baba solo tomo lo que necesitaba. Que cosa que ya tienes es justo suficiente para ti?"},rewardName:"Cueva secreta"},"aesops-fables":{title:"La Liebre y la Tortuga",summary:"Una liebre rapida y una tortuga lenta hacen una carrera amistosa, y la tortuga le ensenaa todos que nunca rendirse gana el dia.",theme:"perseverancia — despacio pero sin parar",scenes:[{text:"En un prado soleado, una liebre rapida siempre presumia de su velocidad."},{text:"La tortuga lenta y tranquila le propuso un reto. La liebre acepto riendose.",dialogue:{speaker:"Liebre",line:"Una carrera contra ti? Facilísimo! Descansare por el camino."}},{text:"La tortuga avanzo paso a paso, de manera constante, sin detenerse nunca.",dialogue:{speaker:"Tortuga",line:"Despacio pero sin parar, seguire avanzando."}},{text:"La liebre se durmio bajo un arbol, segura de que la tortuga jamas podria alcanzarla."},{text:"Cuando la liebre se desperto, la tortuga ya habia cruzado la linea de meta. Perseverar siempre gana.",dialogue:{speaker:"Tortuga",line:"Paso a paso, se llega mas lejos de lo que uno cree."}}],vocabulary:[{word:"liebre",meaning:"un conejo salvaje grande que es muy rapido",emoji:"🐇"},{word:"tortuga",meaning:"un animal con caparazon que camina despacio pero sin parar",emoji:"🐢"},{word:"constante",meaning:"avanzar al mismo ritmo sin detenerse",emoji:"⏱️"},{word:"perseverar",meaning:"seguir intentandolo aunque sea dificil",emoji:"💪"}],miniGame:{type:"choice",prompt:"Quien gano la carrera sin rendirse nunca?",options:["la liebre rapida","la tortuga lenta y constante","el zorro dormido"],answerIndex:1},emotionalMoment:{feeling:"determinado",prompt:"La tortuga siguio paso a paso. En que sigues tu intentandolo?"},rewardName:"Tortuga perseverante"},"sleeping-beauty":{title:"La Bella Durmiente",summary:"Una bella princesa cae en un sueno magico y espera el amor verdadero.",theme:"paciencia y esperanza",scenes:[{text:"Un rey y una reina felices tuvieron por fin una hijita. Invitaron a todas las hadas del reino a su bautizo."},{text:"Las buenas hadas ofrecieron sus dones a la princesa: belleza, gracia y dulzura. Pero un hada malvada llego furiosa sin haber sido invitada.",dialogue:{speaker:"Hada malvada",line:"Cuando cumpla dieciseis anos, se pinchara el dedo con un huso y caera muerta!"}},{text:"El ultimo hada buena aun no habia hablado. Suavizo el hechizo: la princesa no moriria, sino que dormira cien anos.",dialogue:{speaker:"Hada buena",line:"Dormira, pero el amor la despertara."}},{text:"A los dieciseis anos, la princesa encontro a una anciana que hilaba. Toco el huso y cayo en un profundo sueno. Todo el castillo se durmio con ella."},{text:"Un principe oyo hablar del castillo dormido escondido tras un bosque de rosas. Corto las zarzas y entro en el silencioso castillo.",dialogue:{speaker:"Principe",line:"Que bella es! La voy a despertar."}},{text:"El principe se acerco a la bella princesa y le dio un suave beso. Ella abrio los ojos y sonrio. Todo el castillo desperto al mismo tiempo y vivieron felices para siempre.",dialogue:{speaker:"Princesa",line:"He esperado tanto tiempo. Por fin has llegado!"}}],vocabulary:[{word:"huso",meaning:"una herramienta para hilar lana, con una punta afilada",emoji:"🧵"},{word:"maleficio",meaning:"alguien que usa magia mala para hacer dano",emoji:"🧙"},{word:"encantado",meaning:"transformado por un hechizo especial",emoji:"✨"},{word:"rosal",meaning:"un arbusto espinoso que hace crecer bonitas rosas",emoji:"🌹"}],miniGame:{type:"choice",prompt:"Que hada malvada lanza el hechizo sobre la princesa?",options:["Un hada que no fue invitada","El hada del palacio","El hada del bosque"],answerIndex:0},emotionalMoment:{feeling:"esperanza",prompt:"Has esperado alguna vez algo con impaciencia? Como te sentiste?"},rewardName:"Rosa Encantada"},"beauty-and-the-beast":{title:"La Bella y la Bestia",summary:"Bella aprende que la verdadera belleza esta en el corazon, no en el aspecto.",theme:"bondad y amor verdadero",scenes:[{text:"Un mercader se perdio en el bosque durante una tormenta. Encontro un gran castillo misterioso y se refugio alli para pasar la noche."},{text:"Al marcharse, corto una rosa para su hija Bella. Una terrible Bestia aparecio de repente.",dialogue:{speaker:"Bestia",line:"Has robado mi rosa! Eres mi prisionero!"}},{text:"El mercader suplico a la Bestia que le dejara despedirse de sus hijos. La Bestia acepto, con la condicion de que una de sus hijas volviera en su lugar.",dialogue:{speaker:"Bella",line:"Papa, yo ire. No tengo miedo."}},{text:"Bella vivio en el castillo. La Bestia era fea pero dulce y bondadosa. Cada noche hablaban y reian juntos."},{text:"Bella pidio volver a casa para ver a su padre enfermo. La Bestia acepto tristemente.",dialogue:{speaker:"Bestia",line:"Te echare de menos, Bella. Pero tu felicidad esta antes que la mia."}},{text:"Lejos del castillo, Bella se dio cuenta de que amaba a la Bestia. Corrio a reunirse con ella. Al confesar su amor, la Bestia se transformo en un apuesto principe.",dialogue:{speaker:"Bella",line:"Te quiero, no por tu cara, sino por tu corazon."}},{text:"El principe explico que una bruja lo habia hechizado. Solo el amor sincero podia liberarlo. Bella y el principe vivieron felices para siempre."}],vocabulary:[{word:"bestia",meaning:"un gran animal aterrador, aqui un monstruo hechizado",emoji:"🐾"},{word:"prisionero",meaning:"alguien que no puede marcharse libremente",emoji:"🔒"},{word:"apariencia",meaning:"lo que ves de alguien por fuera",emoji:"👁️"},{word:"transformacion",meaning:"cambiar completamente de forma o aspecto",emoji:"✨"}],miniGame:{type:"choice",prompt:"Por que va el padre de Bella al castillo?",options:["Busca un tesoro","Se refugia de la tormenta y corta una rosa","Visita a la Bestia"],answerIndex:1},emotionalMoment:{feeling:"bondad",prompt:"Has juzgado alguna vez a alguien por su apariencia antes de conocerlo?"},rewardName:"Rosa Magica"},"little-thumb":{title:"Pulgarcito",summary:"El mas pequeno de siete hermanos usa su inteligencia para salvar a toda su familia.",theme:"valor e inteligencia",scenes:[{text:"Un pobre lenador y su mujer tenian siete hijos. El mas pequeno se llamaba Pulgarcito. Era minusculo pero muy inteligente."},{text:"Una tarde los padres, demasiado pobres para alimentar a los ninos, los abandonaron en el bosque.",dialogue:{speaker:"Pulgarcito",line:"Sabia que iban a hacer esto. Estoy preparado."}},{text:"Pulgarcito se habia preparado: habia llenado sus bolsillos de pequenas piedrecitas blancas. Las fue sembrando a lo largo del camino, y los ninos encontraron el camino a casa siguiendolas."},{text:"La segunda vez que los abandonaron, Pulgarcito solo tenia pan para sembrar migas. Los pajaros se las comieron y los hermanos se perdieron de verdad."},{text:"Perdidos, llegaron a la casa de un ogro. La mujer del ogro los escondio, pero el ogro los encontro.",dialogue:{speaker:"Ogro",line:"Huelo carne fresca! Donde estan escondidos?"}},{text:"Pulgarcito tuvo una idea brillante: intercambio los gorros de sus hermanos con las coronas de las hijas del ogro. El ogro se equivoco en la oscuridad."},{text:"Pulgarcito robo las botas de siete leguas del ogro dormido. En unos pocos pasos trajo oro y salvo a toda su familia.",dialogue:{speaker:"Pulgarcito",line:"La inteligencia vale mas que la fuerza!"}}],vocabulary:[{word:"piedrecitas",meaning:"pequenas piedras lisas que puedes sembrar a lo largo de un camino",emoji:"🪨"},{word:"ogro",meaning:"un monstruo gigante en los cuentos que come ninos",emoji:"👹"},{word:"legua",meaning:"una gran distancia, como varios kilometros",emoji:"🗺️"},{word:"astucia",meaning:"una idea lista para enganar a alguien",emoji:"💡"}],miniGame:{type:"sequence",prompt:"Pon los pasos en el orden correcto!",steps:["Sembrar piedrecitas blancas para encontrar el camino","Llegar a la casa del ogro en el bosque","Robar las botas de siete leguas"]},emotionalMoment:{feeling:"valor",prompt:"Has tenido miedo alguna vez pero seguiste adelante de todas formas? Que te ayudo?"},rewardName:"Botas de Siete Leguas"},"jack-beanstalk":{title:"Juan y las Habichuelas Magicas",summary:"Juan cambia su vaca por habichuelas magicas y descubre un castillo entre las nubes.",theme:"aventura y curiosidad",scenes:[{text:"Juan y su madre eran muy pobres. Un dia su madre envio a Juan a vender su vieja vaca al mercado."},{text:"Por el camino, un viejo le ofrecio a Juan habichuelas magicas a cambio de la vaca. Juan acepto.",dialogue:{speaker:"Juan",line:"Habichuelas magicas! Es un buen trato!"}},{text:"La madre de Juan se enfado mucho y tiro las habichuelas por la ventana. Pero durante la noche crecio un enorme tallo de habichuela hasta las nubes."},{text:"Juan trepo por el tallo y descubrio un inmenso castillo entre las nubes. Alli vivia un terrible gigante.",dialogue:{speaker:"Gigante",line:"Fe, fi, fo, fum! Huelo sangre de cristiano!"}},{text:"La mujer del gigante ayudo a Juan a esconderse. Mientras el gigante dormia, Juan robo la gallina de los huevos de oro y el arpa encantada."},{text:"Juan bajo por el tallo corriendo. El gigante lo persiguio. Juan agarro su hacha y corto el tallo. El gigante cayo muy, muy lejos.",dialogue:{speaker:"Juan",line:"Mama! Seremos ricos! Nunca mas pasaremos hambre!"}}],vocabulary:[{word:"habichuela",meaning:"una pequena semilla que puede crecer muy alta",emoji:"🫘"},{word:"gigante",meaning:"un ser imaginario de tamano enorme y muy fuerte",emoji:"🦣"},{word:"nubes",meaning:"las grandes formas blancas o grises en el cielo",emoji:"☁️"},{word:"tesoro",meaning:"objetos preciosos como el oro o las joyas",emoji:"🪙"}],miniGame:{type:"choice",prompt:"Por que cambia Juan su vaca?",options:["Monedas de oro","Habichuelas magicas","Un arpa"],answerIndex:1},emotionalMoment:{feeling:"curiosidad",prompt:"Has descubierto alguna vez algo sorprendente? Como te sentiste?"},rewardName:"Tesoro del Gigante"},thumbelina:{title:"Pulgarcita",summary:"Pulgarcita, una nina muy pequena, busca su lugar en un mundo demasiado grande para ella.",theme:"identidad y pertenencia",scenes:[{text:"Una mujer que deseaba tener un hijo planto una semilla magica. Crecio una flor y dentro de ella dormia una nina muy pequena. Se llamaba Pulgarcita."},{text:"Una noche, un sapo horrible rapto a Pulgarcita para casarla con su hijo. Pulgarcita lloraba sobre su nenufar.",dialogue:{speaker:"Pulgarcita",line:"No quiero quedarme aqui. Quiero encontrar mi verdadero hogar."}},{text:"Unos peces amables royeron el tallo del nenufar y Pulgarcita escapo. Viajo por prados y bosques, siempre demasiado pequena para los demas."},{text:"En invierno, Pulgarcita encontro refugio en casa de un raton campesino. Pero el raton queria casarla con un viejo topo ciego."},{text:"Pulgarcita encontro una golondrina herida y la cuido con ternura durante todo el invierno.",dialogue:{speaker:"Golondrina",line:"Me has salvado. Cuando llegue la primavera, te llevare lejos de aqui."}},{text:"En primavera, la golondrina llevo a Pulgarcita a una tierra calida y florida. Alli conocio a un pequeno principe de las flores. Por fin habia encontrado su lugar.",dialogue:{speaker:"Principe de las flores",line:"Eres bienvenida aqui. Quieres ser nuestra reina?"}}],vocabulary:[{word:"minuscula",meaning:"extremadamente pequena, mucho mas pequena que todos los demas",emoji:"🔬"},{word:"raptar",meaning:"llevarse a alguien a la fuerza sin su permiso",emoji:"😨"},{word:"golondrina",meaning:"un pajaro pequeno y rapido que viaja a paises calidos",emoji:"🐦"},{word:"hada",meaning:"un ser magico con alas que ayuda a los demas",emoji:"🧚"}],miniGame:{type:"find",prompt:"Encuentra la flor donde duerme Pulgarcita!",target:"la gran flor rosa",decoys:["un nenufar verde","una hoja seca","una seta"]},emotionalMoment:{feeling:"pertenencia",prompt:"Has tenido alguna vez la sensacion de no estar en tu lugar? Como encontraste tu lugar?"},rewardName:"Alas de Hada"},"twelve-dancing-princesses":{title:"Las Doce Princesas Bailarinas",summary:"Cada noche doce princesas desgastan en secreto sus zapatos bailando. Un soldado descubre su misterio.",theme:"misterio y perseverancia",scenes:[{text:"Un rey tenia doce hijas. Cada manana sus zapatos aparecian desgastados como si hubieran bailado toda la noche. Pero nadie sabia por que."},{text:"El rey anuncio que quien descubriera el secreto podria casarse con una de sus hijas. Varios principes lo intentaron, pero todos se quedaban dormidos misteriosamente.",dialogue:{speaker:"Rey",line:"Quien resolvera este misterio? Sus zapatos estan desgastados otra vez!"}},{text:"Un viejo soldado que volvia de la guerra encontro a una anciana sabia que le dio una capa invisible.",dialogue:{speaker:"Anciana",line:"No bebas la bebida que te ofrezcan. Y ten cuidado!"}},{text:"El soldado fingio dormir. A medianoche las princesas se levantaron. El las siguio invisible por un pasadizo secreto bajo tierra."},{text:"Bajo tierra descubrio un lago con barcas, un bosque de arboles de plata y oro, y un castillo iluminado donde doce principes esperaban a las princesas para bailar."},{text:"El soldado corto en secreto una rama de plata para probar su descubrimiento. La princesa mayor oyo un ruido.",dialogue:{speaker:"Princesa mayor",line:"Esta noche algo no va bien. Tengo miedo."}},{text:"A la manana siguiente, el soldado presento la rama al rey y le conto todo. El rey reconocio la verdad. El soldado eligio casarse con la princesa mayor y el secreto quedo revelado para siempre.",dialogue:{speaker:"Soldado",line:"La verdad vale mas que todos los secretos."}}],vocabulary:[{word:"misterio",meaning:"algo oculto que todavia no comprendes",emoji:"🔍"},{word:"invisible",meaning:"que no se puede ver aunque este alli",emoji:"👻"},{word:"zapato",meaning:"un zapato elegante, a menudo para bailar",emoji:"👠"},{word:"subterraneo",meaning:"lo que se encuentra bajo tierra, escondido debajo",emoji:"🕳️"}],miniGame:{type:"match",prompt:"Empareja a cada princesa con su principe bailarin!",pairs:[{left:"Princesa Rosa",right:"Principe Dorian"},{left:"Princesa Luna",right:"Principe Silvain"},{left:"Princesa Estrella",right:"Principe Aurele"},{left:"Princesa Violeta",right:"Principe Florian"}]},emotionalMoment:{feeling:"misterio",prompt:"Tienes algun secreto? Como se siente guardar un secreto?"},rewardName:"Corona del Misterio"},rumpelstiltskin:{title:"Rumpelstiltskin",summary:"Un misterioso hombrecillo ayuda a una chica a hilar paja en oro — pero a que precio?",theme:"promesas y honestidad",scenes:[{text:'Un molinero quiso impresionar al rey y dijo una gran mentira: "Mi hija puede hilar paja en oro!" El rey encerro a la chica en una torre llena de paja.'},{text:"La chica lloraba cuando aparecio un extrano hombrecillo.",dialogue:{speaker:"Rumpelstiltskin",line:"Que me daras si hilo toda esta paja en oro por ti?"}},{text:"Ella le dio su collar. El hombrecillo hilo toda la paja en oro. El rey, maravillado, la metio en una sala aun mas grande."},{text:"La tercera noche la chica no tenia nada mas que dar. Prometio a su primer hijo. El rey se caso con ella y se convirtio en reina."},{text:"Un ano despues el hombrecillo volvio a reclamar al nino. La reina le suplico. El le dio tres dias para adivinar su nombre.",dialogue:{speaker:"Rumpelstiltskin",line:"Si adivinas mi nombre, podras quedarte con el nino!"}},{text:"Un mensajero oyo al hombrecillo bailando y cantando su nombre en el bosque. Corrio de vuelta a decirlo a la reina.",dialogue:{speaker:"Mensajero",line:"Se llama Rumpelstiltskin! Lo oí cantarlo!"}}],vocabulary:[{word:"paja",meaning:"tallos secos de cereales, amarillos y ligeros",emoji:"🌾"},{word:"hilar",meaning:"convertir fibras en hilo con una rueca",emoji:"🧶"},{word:"promesa",meaning:"lo que dices que vas a hacer y debes cumplir",emoji:"🤝"},{word:"adivinanza",meaning:"una pregunta con una respuesta oculta que hay que encontrar",emoji:"❓"}],miniGame:{type:"choice",prompt:"Como adivina la reina el nombre del duende?",options:["Un mensajero lo oyo cantar en el bosque","Lo leyo en un libro","El duende se lo dijo el mismo"],answerIndex:0},emotionalMoment:{feeling:"honestidad",prompt:"Es importante cumplir las promesas? Por que?"},rewardName:"Hilo de Oro"},"emperor-new-clothes":{title:"El Traje Nuevo del Emperador",summary:"Dos estafadores convencen a un emperador vanidoso de que le estan tejiendo un traje invisible para los tontos.",theme:"honestidad y valentia",scenes:[{text:"Habia una vez un emperador que amaba la ropa fina por encima de todo. Se cambiaba de traje varias veces al dia."},{text:"Dos estafadores se presentaron como los mejores tejedores del mundo. Dijeron que tejian una tela magica: invisible para los tontos e incompetentes.",dialogue:{speaker:"Estafador",line:"Solo las personas verdaderamente inteligentes pueden ver esta ropa!"}},{text:"Los ministros fueron enviados a ver los avances. No veian nada, pero no se atrevieron a decirlo por miedo a parecer tontos.",dialogue:{speaker:"Ministro",line:"Es magnifico... absolutamente magnifico."}},{text:"Los estafadores entregaron al emperador su ropa nueva imaginaria. El emperador tampoco veia nada, pero fingio."},{text:"El emperador desfilo por las calles. Todo el mundo aplaudio, temeroso de parecer tonto."},{text:"De repente, un nino pequeno grito la verdad.",dialogue:{speaker:"Nino",line:"Pero si no lleva nada puesto! El emperador esta completamente desnudo!"}}],vocabulary:[{word:"vanidoso",meaning:"alguien que piensa demasiado en su aspecto y se cree guapo",emoji:"🪞"},{word:"estafador",meaning:"alguien que miente para robar o enganar a otros",emoji:"🎭"},{word:"invisible",meaning:"imposible de ver con los ojos",emoji:"👻"},{word:"verdad",meaning:"lo que es realmente cierto, aunque incomode",emoji:"✅"}],miniGame:{type:"choice",prompt:"Quien dice la verdad primero?",options:["Un nino pequeno","Un ministro","El propio emperador"],answerIndex:0},emotionalMoment:{feeling:"valentia",prompt:"Has tenido alguna vez el valor de decir una verdad dificil?"},rewardName:"Valor de la Verdad"},"steadfast-tin-soldier":{title:"El Soldadito de Plomo",summary:"Un valiente soldadito de plomo vive una gran aventura y demuestra que el valor viene del corazon.",theme:"valor y fidelidad",scenes:[{text:"Entre una caja de soldaditos de plomo, uno tenia una sola pierna. Pero se mantenia erguido y orgulloso como los demas."},{text:"En un estante enfrente, una pequena bailarina de papel levantaba una pierna. El soldado penso que era como el, y se enamoro de ella.",dialogue:{speaker:"Soldado",line:"Es tan bonita. Quisiera quedarme cerca de ella para siempre."}},{text:"Un duende celoso dentro de una caja grito que el soldado no debia mirar a la bailarina. Al dia siguiente el soldado cayo por una ventana."},{text:"En la calle, unos ninos lo encontraron y lo pusieron en un barco de papel. Navego por el arroyo bajo la lluvia, y despues fue tragado por un gran pez."},{text:"El pez fue pescado y llego a la cocina. La cocinera lo abrio y encontro al soldadito ileso, todavia erguido.",dialogue:{speaker:"Cocinera",line:"Como pudiste sobrevivir a todo eso!"}},{text:"El soldado fue devuelto al nino. Pero el duende celoso arrojo al soldado al fuego. La pequena bailarina tambien cayo por el viento. Del soldado solo quedo un pequeno corazon de metal, simbolo de su fidelidad eterna.",dialogue:{speaker:"Soldado",line:"Me mantuve firme hasta el final."}}],vocabulary:[{word:"plomo",meaning:"un metal gris muy pesado, antes usado para hacer juguetes",emoji:"⚙️"},{word:"valiente",meaning:"con coraje y firmeza ante el peligro",emoji:"🛡️"},{word:"torrente",meaning:"una corriente de agua fuerte y rapida",emoji:"🌊"},{word:"fidelidad",meaning:"permanecer leal a alguien que amas pase lo que pase",emoji:"💙"}],miniGame:{type:"choice",prompt:"De quien se enamora el soldadito de plomo?",options:["De una pequena bailarina de papel","De una princesa en el castillo","De un hada magica"],answerIndex:0},emotionalMoment:{feeling:"fidelidad",prompt:"Hay alguien o algo a quien seas muy fiel? Que significa eso para ti?"},rewardName:"Medalla de Valor"},"la-fontaine-crow-fox":{title:"El Cuervo y el Zorro",summary:"Un zorro muy astuto halaga a un cuervo para robarle su queso. Una fabula sobre la vanidad.",theme:"astucia y humildad",scenes:[{text:"Un cuervo estaba posado en una rama, sosteniendo en su pico un buen trozo de queso muy perfumado."},{text:"Un zorro muy astuto paso por alli y olio el queso. Decidio robarselo usando halagos.",dialogue:{speaker:"Zorro",line:"Oh senor Cuervo, que hermoso es usted! Que magnifico plumaje tiene!"}},{text:"El cuervo, muy orgulloso de los cumplidos, esponjaba sus plumas de placer. El zorro continuo.",dialogue:{speaker:"Zorro",line:"Si su voz es tan bella como sus plumas, usted es el rey de las aves!"}},{text:"El cuervo, demasiado halagado, abrio el pico de par en par para cantar. El queso cayo."},{text:"El zorro atrapo el queso riendose y dijo la moraleja de la fabula.",dialogue:{speaker:"Zorro",line:"Todo adulador vive a expensas de quien lo escucha. Esta leccion bien vale un queso!"}}],vocabulary:[{word:"cuervo",meaning:"un gran pajaro negro con un pico fuerte y curvo",emoji:"🐦‍⬛"},{word:"adulador",meaning:"alguien que da demasiados cumplidos para conseguir algo",emoji:"😏"},{word:"queso",meaning:"un alimento hecho con leche, a menudo amarillo o blanco",emoji:"🧀"},{word:"moraleja",meaning:"la leccion que aprendes al final de una fabula",emoji:"📜"}],miniGame:{type:"choice",prompt:"Como consigue el zorro el queso?",options:["Halagando al cuervo para que abra el pico","Subiendo al arbol","Pidiendolo amablemente"],answerIndex:0},emotionalMoment:{feeling:"humildad",prompt:"Te han halagado alguna vez y has hecho algo tonto? Que aprendiste?"},rewardName:"Sabiduria de la Fabula"},"musicians-of-bremen":{title:"Los Musicos de Bremen",summary:"Un burro, un perro, un gato y un gallo — demasiado viejos para sus amos — se dirigen a Bremen y descubren que la amistad es mas fuerte que la fuerza.",theme:"amistad y valentia",scenes:[{text:"Un viejo burro decidio ir a Bremen para convertirse en musico."},{text:"Por el camino encontro a un perro, un gato y un gallo. Juntos siguieron andando.",dialogue:{speaker:"Burro",line:"Venid conmigo! En Bremen haremos musica juntos!"}},{text:"Esa noche encontraron una casa con ladrones dentro y se subieron unos encima de otros ante la ventana."},{text:"Todos cantaron a la vez. Los ladrones, aterrorizados, huyeron al bosque.",dialogue:{speaker:"Gallo",line:"Nuestra musica ahuyenta a los malos!"}},{text:"Los cuatro amigos se instalaron en la casa. Tan felices juntos que nunca necesitaron ir a Bremen."}],vocabulary:[{word:"musico",meaning:"alguien que toca musica",emoji:"🎵"},{word:"ladron",meaning:"un ladron que asusta a la gente",emoji:"😈"},{word:"juntos",meaning:"todos unos con otros",emoji:"🤝"},{word:"aterrorizados",meaning:"muy, muy asustados",emoji:"😱"}],miniGame:{type:"count",prompt:"Cuantos animales van a Bremen?",answer:4,options:[3,4,5]},emotionalMoment:{feeling:"amistad",prompt:"Cuando te ayudaron los amigos a ser valiente?"},rewardName:"Trompeta de Bremen"},"pied-piper":{title:"El Flautista de Hamelin",summary:"Un flautista magico promete resolver un problema de ratas y ensena a todos que las promesas siempre deben cumplirse.",theme:"honestidad y promesas",scenes:[{text:"La ciudad de Hamelin estaba invadida por ratas."},{text:"Un flautista de colores prometio ahuyentar todas las ratas a cambio de una recompensa.",dialogue:{speaker:"Flautista",line:"Puedo alejar vuestras ratas. Pero debeis cumplir vuestra promesa de pagar."}},{text:"Toco una melodia magica. Todas las ratas lo siguieron hasta el rio y desaparecieron."},{text:"Los habitantes se negaron a pagar.",dialogue:{speaker:"Alcalde",line:"No te pagaremos. Vete!"}},{text:"Los ninos siguieron la musica. Aquel dia toda la ciudad aprendio que las promesas deben cumplirse."}],vocabulary:[{word:"flauta",meaning:"un instrumento de viento en el que se sopla",emoji:"🎵"},{word:"promesa",meaning:"decir que hara algo y cumplirlo de verdad",emoji:"🤝"},{word:"melodia",meaning:"una secuencia de notas que hace musica",emoji:"🎼"},{word:"recompensa",meaning:"algo dado a cambio de un servicio",emoji:"🏆"}],miniGame:{type:"choice",prompt:"Que pasa cuando rompes una promesa?",options:["Nada","Pierdes la confianza de los demas","Los demas estan contentos"],answerIndex:1},emotionalMoment:{feeling:"honestidad",prompt:"Has cumplido alguna vez una promesa dificil? Como te sentiste?"},rewardName:"Flauta Magica"},"little-match-girl":{title:"La Pequena Vendedora de Cerillas",summary:"En una noche de frio, una ninita pobre enciende cerillas que le muestran suenos hermosos de calor y amor.",theme:"esperanza y bondad",scenes:[{text:"La noche de Ano Nuevo, con un frio terrible, una ninita caminaba descalza por la nieve vendiendo cerillas."},{text:"Nadie le compro ninguna. Se acurruco en un rincon y encendio una cerilla para calentarse los dedos.",dialogue:{speaker:"Ninita",line:"Solo una cerilla para un poco de calor..."}},{text:"En la llama vio una gran estufa caliente y luego una mesa llena de comida."},{text:"Encendio otra cerilla y vio a su querida abuela sonriendole.",dialogue:{speaker:"Abuela",line:"Estoy aqui, querida. Ven conmigo a un lugar calido."}},{text:"A la manana siguiente los transeuntes encontraron a la ninita dormida con una sonrisa serena en el rostro."}],vocabulary:[{word:"cerilla",meaning:"un palito pequeno que hace fuego al frotarlo",emoji:"🔥"},{word:"serena",meaning:"tranquila y en paz, sin miedo",emoji:"😌"},{word:"esperanza",meaning:"creer que algo bueno puede pasar",emoji:"🌟"},{word:"acurrucarse",meaning:"enroscarse para mantenerse caliente",emoji:"🤗"}],miniGame:{type:"choice",prompt:"Que ve la nina en la llama de su primera cerilla?",options:["Una gran estufa caliente","Su abuela","Un arbol de Navidad"],answerIndex:0},emotionalMoment:{feeling:"esperanza",prompt:"Que te da esperanza cuando las cosas son dificiles?"},rewardName:"Luz de Esperanza"},"princess-pea":{title:"La Princesa y el Guisante",summary:"Una verdadera princesa se reconoce por su gran sensibilidad — una divertida fabula sobre ser uno mismo.",theme:"ser uno mismo",scenes:[{text:"Un principe buscaba una verdadera princesa con quien casarse. Pero como saber si era real?"},{text:"Una noche de tormenta una chica empapada llamo a la puerta diciendo que era una princesa.",dialogue:{speaker:"Chica",line:"Soy una verdadera princesa, os lo aseguro!"}},{text:"La reina tuvo una idea ingeniosa. Coloco un diminuto guisante bajo veinte colchones."},{text:"A la manana siguiente le preguntaron a la chica como habia dormido.",dialogue:{speaker:"Chica",line:"Horriblemente! Senti algo duro toda la noche. Estoy llena de cardenales!"}},{text:"Solo una verdadera princesa podia sentir un guisante bajo tantos colchones. El principe se caso con ella y fueron muy felices."}],vocabulary:[{word:"princesa",meaning:"la hija de un rey o una reina",emoji:"👸"},{word:"colchon",meaning:"la parte blanda de la cama donde se duerme",emoji:"🛏️"},{word:"sensible",meaning:"quien siente las cosas con mucha fuerza",emoji:"💝"},{word:"tormenta",meaning:"tiempo muy malo con viento y lluvia",emoji:"⛈️"}],miniGame:{type:"count",prompt:"Cuantos colchones apilo la reina?",answer:20,options:[10,15,20]},emotionalMoment:{feeling:"ser uno mismo",prompt:"Que te hace unico?"},rewardName:"Corona de la Sensibilidad"},"wild-swans":{title:"Los Cisnes Salvajes",summary:"Una valiente princesa trabaja en silencio durante anos para romper el hechizo que convirtio a sus once hermanos en cisnes.",theme:"valentia silenciosa y amor",scenes:[{text:"Elise tenia once hermanos transformados en cisnes salvajes por el hechizo de una malvada madrastra."},{text:"Un hada le revelo el secreto: debia tejer once abrigos de ortiga sin pronunciar una sola palabra.",dialogue:{speaker:"Hada",line:"Una sola palabra y tus hermanos se quedaran cisnes para siempre."}},{text:"Elise tejio sin parar, aunque sus manos sangraban."},{text:"Pasaron anos. Por fin, lanzo los abrigos sobre los cisnes.",dialogue:{speaker:"Elise",line:"Hermanos mios! Os espere tanto tiempo!"}},{text:"Los cisnes volvieron a ser sus hermanos. Elise pudo por fin hablar y contarles todo su amor."}],vocabulary:[{word:"hechizo",meaning:"una magia que transforma a alguien",emoji:"✨"},{word:"ortiga",meaning:"una planta con hojas que pican",emoji:"🌿"},{word:"tejer",meaning:"hacer ropa con hilo y agujas",emoji:"🧶"},{word:"silencio",meaning:"no decir ni una sola palabra",emoji:"🤫"}],miniGame:{type:"count",prompt:"Cuantos hermanos necesita salvar Elise?",answer:11,options:[7,9,11]},emotionalMoment:{feeling:"determinacion",prompt:"Que harias por alguien a quien quieres?"},rewardName:"Pluma de Cisne"},"chevre-monsieur-seguin":{title:"La Cabra del Senor Seguin",summary:"La cabrita Blanquette quiere la libertad pero descubre que la verdadera libertad viene con responsabilidad.",theme:"libertad y precaucion",scenes:[{text:"El senor Seguin tenia una hermosa cabra blanca llamada Blanquette. Pero Blanquette queria la libertad de las montanas."},{text:"El senor Seguin le rogo que se quedara.",dialogue:{speaker:"Sr. Seguin",line:"Blanquette, quedate! Hay un gran lobo en las montanas!"}},{text:"Blanquette no escucho. Salto la cerca y corrio feliz a los prados de la montana."},{text:"Todo el dia retozo, comio hierba fina y respiro aire fresco. Pero al atardecer llego el gran lobo.",dialogue:{speaker:"Blanquette",line:"Luchare hasta el amanecer! No me rendire!"}},{text:"Blanquette lucho valientemente toda la noche y aprendio que la libertad tambien exige precaucion."}],vocabulary:[{word:"cabra",meaning:"un animal de granja con cuernos que da leche",emoji:"🐐"},{word:"retozar",meaning:"saltar y correr libremente jugando",emoji:"🦘"},{word:"amanecer",meaning:"el primer momento de la manana cuando sale el sol",emoji:"🌅"},{word:"libertad",meaning:"poder hacer lo que uno quiere",emoji:"🕊️"}],miniGame:{type:"choice",prompt:"Por que el senor Seguin quiere retener a Blanquette?",options:["Por su leche","Para protegerla del lobo","Para no estar solo"],answerIndex:1},emotionalMoment:{feeling:"libertad y precaucion",prompt:"Como puedes ser libre y estar seguro al mismo tiempo?"},rewardName:"Cencerro de Montana"},sinbad:{title:"Simbad el Marinero",summary:"El valiente marinero Simbad recorre los mares del mundo y siempre regresa mas sabio de lo que partio.",theme:"valentia y sabiduria",scenes:[{text:"Simbad era un rico mercader de Bagdad que amaba las aventuras. Realizo siete grandes viajes."},{text:"En su primer viaje su barco encallo en lo que parecia una isla... pero era un pez gigante dormido!",dialogue:{speaker:"Simbad",line:"Esto no es una isla... es una criatura viva! Huid!"}},{text:"En cada viaje Simbad enfrentaba nuevos peligros. Los supero todos con su ingenio."},{text:"Siempre trajo tesoros, pero sobre todo historias y sabiduria.",dialogue:{speaker:"Simbad",line:"Las verdaderas riquezas no son las joyas sino lo que aprendes en el camino."}},{text:"Cada viaje le enseno algo nuevo sobre el mundo y sobre si mismo."}],vocabulary:[{word:"marinero",meaning:"alguien que viaja y trabaja en el mar",emoji:"⚓"},{word:"encallar",meaning:"cuando un barco se detiene en el fondo del mar o en una playa",emoji:"🏖️"},{word:"peligro",meaning:"una gran amenaza",emoji:"⚠️"},{word:"sabiduria",meaning:"el conocimiento ganado a traves de la experiencia",emoji:"🦉"}],miniGame:{type:"count",prompt:"Cuantos grandes viajes hizo Simbad?",answer:7,options:[5,7,9]},emotionalMoment:{feeling:"aventura y sabiduria",prompt:"Que aprendiste durante un viaje o una nueva experiencia?"},rewardName:"Brujula del Viajero"},"tinder-box":{title:"El Eslabón de Fuego",summary:"Un soldado encuentra un eslabon de fuego magico y aprende que un corazon generoso es la verdadera magia.",theme:"generosidad y amistad",scenes:[{text:"Un soldado que volvia de la guerra encontro a una vieja bruja que le ofrecio un trato: buscar un eslabon de fuego en un arbol hueco."},{text:"Dentro del arbol encontro tres enormes perros que guardaban cofres llenos de monedas de oro.",dialogue:{speaker:"Soldado",line:"Obedecen mientras yo tenga el eslabon de fuego!"}},{text:"Se volvio rico y generoso — daba comida a todos los necesitados."},{text:"Con el eslabon los perros aparecian y concedian sus deseos, pero siempre pedia cosas buenas.",dialogue:{speaker:"Soldado",line:"Traed comida para todo el pueblo!"}},{text:"Gracias a su bondad el soldado se gano el amor de todos. La verdadera magia era un corazon generoso."}],vocabulary:[{word:"eslabon de fuego",meaning:"un objeto pequeno que hace fuego",emoji:"🔥"},{word:"generoso",meaning:"feliz de dar y compartir con los demas",emoji:"🎁"},{word:"bruja",meaning:"una persona que hace magia",emoji:"🧙"},{word:"cofre",meaning:"una caja grande y fuerte para guardar tesoros",emoji:"📦"}],miniGame:{type:"count",prompt:"Cuantos perros magicos guardan los tesoros?",answer:3,options:[2,3,4]},emotionalMoment:{feeling:"generosidad",prompt:"Has compartido alguna vez algo que amabas? Como te sentiste?"},rewardName:"Eslabon de la Bondad"},"blue-bird":{title:"El Pajaro Azul",summary:"Dos ninos buscan por el mundo el Pajaro Azul de la Felicidad y descubren que la felicidad a menudo esta cerca de casa.",theme:"felicidad y gratitud",scenes:[{text:"Tyltyl y Mytyl, dos ninos pobres pero alegres, vivian con sus padres en una pequena casa al borde del bosque."},{text:"El hada Berylune aparecio y les pidio que encontraran el Pajaro Azul de la Felicidad para su nieta enferma.",dialogue:{speaker:"Hada Berylune",line:"Id a buscar el Pajaro Azul! Esta en algun lugar del mundo."}},{text:"Los ninos viajaron muy lejos. En todas partes los pajaros azules que encontraban morian o cambiaban de color."},{text:"Decepcionados, regresaron a casa.",dialogue:{speaker:"Tyltyl",line:"Buscamos en todas partes... existe realmente el Pajaro Azul?"}},{text:"De vuelta en casa, Tyltyl noto que su paloma — que siempre habia tenido — tenia unas hermosas plumas azules. La felicidad siempre habia estado alli."}],vocabulary:[{word:"felicidad",meaning:"un sentimiento de profunda alegria y satisfaccion",emoji:"😊"},{word:"gratitud",meaning:"estar agradecido y contento por lo que tienes",emoji:"🙏"},{word:"recuerdo",meaning:"una imagen o sensacion guardada en la mente",emoji:"💭"},{word:"decepcionado",meaning:"triste porque algo no ha salido bien",emoji:"😔"}],miniGame:{type:"choice",prompt:"Donde encuentra Tyltyl finalmente el Pajaro Azul?",options:["En un castillo lejano","En su propia casa","En el fondo del mar"],answerIndex:1},emotionalMoment:{feeling:"gratitud",prompt:"Que cosas hermosas ya tienes que te hacen feliz?"},rewardName:"Pluma de la Felicidad"},"renart-goupil":{title:"Reinardo el Zorro",summary:"El astuto zorro Reinardo usa su inteligencia en cada situacion — y aprende que incluso el mas listo puede ser superado.",theme:"inteligencia y humildad",scenes:[{text:"En el gran bosque de la Edad Media vivia Reinardo el Zorro, el mas astuto de todos los animales."},{text:"Un dia Reinardo robo una gallina a Canteclaro el gallo. Pero Canteclaro tenia un plan.",dialogue:{speaker:"Canteclaro",line:"Reinardo, que guapo eres! Muestrame como cantas cuando estas orgulloso!"}},{text:"Reinardo, halagado, abrio la boca para cantar... y la gallina escapo!"},{text:"Intento robar el queso a Isengrin el lobo. Esta vez el lobo le gano la mano.",dialogue:{speaker:"Isengrin",line:"No eres el unico que puede ser listo, Reinardo!"}},{text:"Reinardo aprendio que incluso el zorro mas astuto puede ser atrapado. La honestidad a veces vale mas que el engano."}],vocabulary:[{word:"astuto",meaning:"muy bueno engannando a los demas",emoji:"🦊"},{word:"halagado",meaning:"complacido por demasiados cumplidos",emoji:"😏"},{word:"honesto",meaning:"quien dice la verdad y no hace trampa",emoji:"✅"},{word:"superar",meaning:"ser mas listo que alguien",emoji:"🎭"}],miniGame:{type:"choice",prompt:"Como recupera Canteclaro su gallina?",options:["Corriendo mas rapido","Halagando a Reinardo para que abra la boca","Llamando a otros animales"],answerIndex:1},emotionalMoment:{feeling:"humildad",prompt:"Has aprendido alguna vez algo importante de un error que cometiste?"},rewardName:"Cola de Zorro"}};export{o as C,s as a,r as b,t as c,i as g};
